/* ==========================================================================
   LA ESPADA CELESTIAL — RPG RETRO
   Design system: celestial gold, deep astral navy, aurora teal.
   ========================================================================== */

:root {
  --ink: #060a14;
  --ink-2: #0a1020;
  --ink-3: #111a30;
  --panel: rgba(10, 16, 31, .92);
  --panel-2: rgba(18, 27, 49, .82);
  --line: rgba(190, 214, 255, .16);
  --line-strong: rgba(232, 210, 154, .38);
  --gold: #f2d188;
  --gold-2: #c89a49;
  --gold-3: #8a6327;
  --teal: #6fe8d4;
  --violet: #a68bff;
  --blue: #7fb4ff;
  --rose: #ff7d9d;
  --green: #8fe3a4;
  --text: #eef3ff;
  --muted: #9eabc6;
  --muted-2: #6c7a98;
  --hp: linear-gradient(90deg, #ff5570, #ff9a7a);
  --mp: linear-gradient(90deg, #4d7dff, #74d7ff);
  --st: linear-gradient(90deg, #56c98a, #b9f07d);
  --shadow: 0 24px 70px rgba(0, 0, 0, .55);
  --font-display: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --font-ui: "Avenir Next", "Segoe UI", Inter, system-ui, -apple-system, sans-serif;
  --radius: 18px;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
html { background: var(--ink); }
body {
  font-family: var(--font-ui);
  color: var(--text);
  background:
    radial-gradient(1200px 700px at 70% -10%, #172a4d 0%, transparent 60%),
    radial-gradient(900px 600px at 10% 110%, #122b2c 0%, transparent 60%),
    var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  background: #08101e;
}

#world-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(0, 0, 0, .45) 100%);
  mix-blend-mode: multiply;
  opacity: .85;
}

/* --------------------------------------------------------------------------
   Boot
   -------------------------------------------------------------------------- */
.boot-screen {
  position: absolute;
  inset: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(600px 400px at 50% 40%, rgba(72, 107, 178, .18), transparent 70%),
    linear-gradient(160deg, #070b16, #0a1426 55%, #071018);
  transition: opacity .6s ease, visibility .6s;
}
.boot-screen.done { opacity: 0; visibility: hidden; }
.boot-emblem { width: 108px; height: 108px; filter: drop-shadow(0 0 28px rgba(242, 209, 136, .45)); animation: emblemFloat 3.4s ease-in-out infinite; }
.boot-emblem svg { width: 100%; height: 100%; }
.boot-screen h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(22px, 4vw, 38px);
  letter-spacing: .34em;
  color: var(--gold);
  text-shadow: 0 0 34px rgba(242, 209, 136, .4);
  font-weight: 500;
}
.boot-screen p { margin: 0; color: var(--muted); font-size: 13px; letter-spacing: .18em; text-transform: uppercase; }
.boot-bar { width: min(360px, 62vw); height: 3px; border-radius: 3px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.boot-bar span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--gold-3), var(--gold), #fff6d6); transition: width .25s ease; box-shadow: 0 0 12px var(--gold); }
@keyframes emblemFloat { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-8px) rotate(2deg); } }

/* --------------------------------------------------------------------------
   HUD
   -------------------------------------------------------------------------- */
#hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) 14px max(16px, env(safe-area-inset-left)); }
.hud-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; }
.hud-left { width: min(330px, 40vw); }
.char-badge { display: flex; gap: 10px; padding: 8px 12px 8px 8px; border-radius: 16px; background: linear-gradient(135deg, rgba(10, 18, 34, .92), rgba(15, 26, 46, .76)); border: 1px solid var(--line); box-shadow: 0 12px 30px rgba(0, 0, 0, .32); backdrop-filter: blur(10px); }
.char-portrait { width: 52px; height: 52px; border-radius: 12px; flex: 0 0 auto; background: radial-gradient(circle at 50% 30%, #33476f, #0c1424 70%); border: 1px solid var(--line-strong); overflow: hidden; display: grid; place-items: center; position: relative; }
.char-portrait::after { content: ""; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 18px rgba(242, 209, 136, .18); }
.char-portrait svg { width: 100%; height: 100%; }
.char-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.char-line { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 12px; letter-spacing: .04em; }
.char-line span { font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.char-line b { color: var(--gold); font-size: 10px; letter-spacing: .12em; }
.bar { position: relative; height: 8px; border-radius: 6px; background: rgba(255, 255, 255, .08); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .5); }
.bar i { display: block; height: 100%; width: 100%; border-radius: inherit; transition: width .18s ease; }
.bar span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 7.5px; font-weight: 700; letter-spacing: .08em; text-shadow: 0 1px 2px #000; opacity: .92; }
.bar.hp { height: 10px; } .bar.hp i { background: var(--hp); box-shadow: 0 0 12px rgba(255, 85, 112, .5); }
.bar.mp i { background: var(--mp); }
.bar.st { height: 5px; } .bar.st i { background: var(--st); }
.xp-rail { margin: 5px 4px 0 6px; height: 4px; border-radius: 4px; background: rgba(255, 255, 255, .07); overflow: hidden; position: relative; }
.xp-rail i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #8b6bff, #d9c7ff); box-shadow: 0 0 10px rgba(166, 139, 255, .7); transition: width .25s ease; }
.xp-rail span { position: absolute; right: 0; top: 5px; font-size: 8px; letter-spacing: .12em; color: var(--muted-2); text-transform: uppercase; }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.zone-chip, .gold-chip { display: flex; align-items: center; gap: 8px; padding: 7px 13px; border-radius: 999px; background: rgba(8, 14, 27, .82); border: 1px solid var(--line); backdrop-filter: blur(10px); font-size: 11px; letter-spacing: .06em; }
.zone-chip .zone-rune { color: var(--gold); font-size: 13px; text-shadow: 0 0 10px var(--gold); }
.zone-chip b { font-weight: 600; }
.gold-chip { color: var(--gold); }
.gold-chip .ico { width: 15px; height: 15px; }
.gold-chip b { font-variant-numeric: tabular-nums; }

.hud-side { position: absolute; left: max(16px, env(safe-area-inset-left)); top: 106px; display: flex; flex-direction: column; gap: 10px; width: min(250px, 30vw); }
.quest-tracker { padding: 11px 13px; border-radius: 14px; background: linear-gradient(135deg, rgba(9, 15, 29, .86), rgba(13, 22, 40, .62)); border: 1px solid var(--line); border-left: 2px solid var(--gold-2); backdrop-filter: blur(8px); }
.tracker-head { display: flex; align-items: center; gap: 6px; color: var(--gold); font-size: 8.5px; letter-spacing: .24em; font-weight: 700; margin-bottom: 5px; }
.quest-tracker b { display: block; font-family: var(--font-display); font-size: 13px; letter-spacing: .03em; color: #f7f2e5; }
.quest-tracker p { margin: 3px 0 0; font-size: 10.5px; line-height: 1.35; color: var(--muted); }

.creature-chip { display: flex; align-items: center; gap: 9px; padding: 7px 11px; border-radius: 13px; background: rgba(9, 15, 29, .8); border: 1px solid var(--line); position: relative; overflow: hidden; backdrop-filter: blur(8px); }
.creature-orb { width: 30px; height: 30px; border-radius: 50%; flex: 0 0 auto; background: radial-gradient(circle at 35% 30%, #fff, var(--orb, #7fb4ff) 35%, #121a2c 78%); box-shadow: 0 0 16px var(--orb, #7fb4ff); position: relative; }
.creature-orb::after { content: ""; position: absolute; inset: 7px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .5); }
.creature-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.creature-meta b { font-size: 10.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.creature-meta span { font-size: 8.5px; color: var(--muted-2); letter-spacing: .12em; text-transform: uppercase; }
.creature-cd { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgba(255, 255, 255, .07); }
.creature-cd i { display: block; height: 100%; width: 100%; background: var(--teal); box-shadow: 0 0 8px var(--teal); }

.boss-bar { position: absolute; left: 50%; bottom: 26px; transform: translateX(-50%); width: min(560px, 70vw); padding: 10px 16px 12px; border-radius: 14px; background: linear-gradient(180deg, rgba(28, 10, 24, .88), rgba(10, 8, 18, .92)); border: 1px solid rgba(255, 120, 150, .32); box-shadow: 0 0 40px rgba(255, 60, 100, .18), inset 0 0 30px rgba(255, 60, 100, .05); backdrop-filter: blur(10px); }
.boss-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px; }
.boss-head span { font-size: 8px; letter-spacing: .3em; color: #ff9caf; }
.boss-head b { font-family: var(--font-display); font-size: 13px; letter-spacing: .08em; color: #ffe9ee; }
.boss-track { height: 8px; border-radius: 6px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.boss-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #ff3d68, #ff8b6b); box-shadow: 0 0 14px #ff3d68; transition: width .2s ease; }

.interact-prompt { position: absolute; left: 50%; bottom: 128px; transform: translateX(-50%); display: flex; align-items: center; gap: 9px; padding: 8px 14px; border-radius: 999px; background: rgba(8, 13, 25, .92); border: 1px solid var(--line-strong); box-shadow: 0 10px 30px rgba(0, 0, 0, .4); font-size: 11.5px; letter-spacing: .03em; animation: promptIn .22s ease; pointer-events: none; }
.interact-prompt kbd { display: inline-grid; place-items: center; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 6px; background: linear-gradient(180deg, #f6dfa2, #c1974a); color: #241708; font-weight: 800; font-size: 11px; box-shadow: 0 2px 0 #6e4d17; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }

.toasts { position: absolute; right: max(16px, env(safe-area-inset-right)); top: 94px; display: flex; flex-direction: column; align-items: flex-end; gap: 8px; width: min(320px, 46vw); }
.toast { display: flex; align-items: center; gap: 9px; padding: 9px 13px; border-radius: 11px; background: linear-gradient(135deg, rgba(12, 20, 37, .96), rgba(17, 30, 50, .9)); border: 1px solid var(--line); box-shadow: 0 10px 28px rgba(0, 0, 0, .38); font-size: 11px; animation: toastIn .28s ease both; }
.toast.out { animation: toastOut .3s ease both; }
.toast .t-ico { width: 20px; height: 20px; flex: 0 0 auto; color: var(--gold); }
.toast.good { border-color: rgba(143, 227, 164, .35); } .toast.good .t-ico { color: var(--green); }
.toast.bad { border-color: rgba(255, 125, 157, .35); } .toast.bad .t-ico { color: var(--rose); }
.toast.gold { border-color: rgba(242, 209, 136, .38); } .toast.gold .t-ico { color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateX(22px) scale(.96); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateX(22px) scale(.96); } }

.hint-bar { position: absolute; left: 50%; bottom: 16px; transform: translateX(-50%); display: flex; gap: 14px; padding: 7px 14px; border-radius: 999px; background: rgba(7, 12, 23, .7); border: 1px solid rgba(255, 255, 255, .07); color: var(--muted-2); font-size: 9px; letter-spacing: .08em; white-space: nowrap; backdrop-filter: blur(6px); }
.hint-bar kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; margin-right: 3px; padding: 0 4px; border-radius: 4px; background: rgba(255, 255, 255, .1); color: #dfe7fa; font-size: 8.5px; font-weight: 700; }

/* --------------------------------------------------------------------------
   Touch controls
   -------------------------------------------------------------------------- */
.touch-controls { position: absolute; inset: 0; z-index: 30; pointer-events: none; }
.touch-controls .tbtn { pointer-events: auto; }
.joystick { position: absolute; left: max(22px, env(safe-area-inset-left)); bottom: max(22px, env(safe-area-inset-bottom)); width: 132px; height: 132px; pointer-events: auto; touch-action: none; }
.joystick-ring { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle, rgba(20, 34, 58, .5), rgba(9, 15, 28, .34) 66%, transparent 70%); border: 1px solid rgba(190, 214, 255, .2); box-shadow: inset 0 0 30px rgba(0, 0, 0, .4); }
.joystick-ring::before, .joystick-ring::after { content: ""; position: absolute; background: rgba(190, 214, 255, .13); }
.joystick-ring::before { left: 50%; top: 14%; bottom: 14%; width: 1px; }
.joystick-ring::after { top: 50%; left: 14%; right: 14%; height: 1px; }
.joystick-stick { position: absolute; left: 50%; top: 50%; width: 54px; height: 54px; margin: -27px 0 0 -27px; border-radius: 50%; background: radial-gradient(circle at 36% 30%, rgba(111, 232, 212, .5), rgba(24, 47, 74, .92) 70%); border: 1px solid rgba(190, 240, 255, .4); box-shadow: 0 8px 24px rgba(0, 0, 0, .4), 0 0 18px rgba(111, 232, 212, .18); transition: transform .06s linear; }
.action-cluster { position: absolute; right: max(24px, env(safe-area-inset-right)); bottom: max(24px, env(safe-area-inset-bottom)); width: 176px; height: 176px; pointer-events: none; }
.tbtn { border: 1px solid rgba(230, 216, 176, .34); background: radial-gradient(circle at 35% 28%, rgba(38, 58, 92, .92), rgba(10, 17, 31, .92) 70%); color: #f4ecd8; border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; box-shadow: 0 8px 22px rgba(0, 0, 0, .38), inset 0 1px 0 rgba(255, 255, 255, .12); touch-action: none; transition: transform .07s, background .12s, box-shadow .12s; }
.tbtn span { font-family: var(--font-display); font-weight: 700; font-size: 19px; line-height: 1; }
.tbtn small { font-size: 7px; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
.tbtn.active { transform: scale(.92); background: radial-gradient(circle at 35% 28%, rgba(242, 209, 136, .85), rgba(122, 85, 29, .92) 70%); color: #1a1002; box-shadow: 0 0 24px rgba(242, 209, 136, .45); }
.tbtn.active small { color: rgba(26, 16, 2, .75); }
.tbtn-a { position: absolute; right: 4px; bottom: 42px; width: 64px; height: 64px; }
.tbtn-b { position: absolute; right: 62px; bottom: 0; width: 58px; height: 58px; }
.tbtn-x { position: absolute; right: 68px; bottom: 64px; width: 58px; height: 58px; }
.tbtn-y { position: absolute; right: 4px; bottom: 112px; width: 54px; height: 54px; }
.tbtn.mini { position: absolute; width: 42px; height: 42px; border-radius: 12px; }
.tbtn.mini span { font-size: 14px; }
.tbtn.mini small { display: none; }
.touch-top { position: absolute; right: max(24px, env(safe-area-inset-right)); top: max(16px, env(safe-area-inset-top)); display: flex; gap: 8px; pointer-events: none; }
.touch-top .tbtn { position: relative; }
.touch-shoulders { position: absolute; left: 50%; bottom: max(18px, env(safe-area-inset-bottom)); transform: translateX(-50%); display: flex; gap: 10px; pointer-events: none; }
.tbtn.shoulder { width: 54px; height: 36px; border-radius: 11px; flex-direction: row; gap: 4px; }
.tbtn.shoulder span { font-size: 13px; }
.tbtn.shoulder small { font-size: 7px; }
.touch-controls.compact .joystick { width: 108px; height: 108px; }
.touch-controls.compact .joystick-stick { width: 44px; height: 44px; margin: -22px 0 0 -22px; }
.touch-controls.compact .action-cluster { width: 148px; height: 148px; }
.touch-controls.compact .tbtn-a { width: 54px; height: 54px; bottom: 36px; }
.touch-controls.compact .tbtn-b { width: 48px; height: 48px; right: 52px; }
.touch-controls.compact .tbtn-x { width: 48px; height: 48px; right: 57px; bottom: 54px; }
.touch-controls.compact .tbtn-y { width: 46px; height: 46px; bottom: 95px; }

/* --------------------------------------------------------------------------
   Screens & menus
   -------------------------------------------------------------------------- */
.ui-root { position: absolute; inset: 0; z-index: 50; pointer-events: none; }
.ui-root > * { pointer-events: auto; }
.screen { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; padding: max(16px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left)); background: radial-gradient(1200px 700px at 50% 20%, rgba(24, 44, 78, .42), transparent 70%), rgba(4, 8, 16, .72); backdrop-filter: blur(9px); animation: screenIn .28s ease both; overflow: hidden; }
.screen::before { content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .5; background-image: radial-gradient(rgba(242, 209, 136, .16) 1px, transparent 1px); background-size: 46px 46px; mask-image: radial-gradient(ellipse at center, black, transparent 74%); }
.screen.closing { animation: screenOut .2s ease both; }
@keyframes screenIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes screenOut { to { opacity: 0; } }

/* Title */
.title-screen { background: linear-gradient(180deg, rgba(4, 8, 17, .12), rgba(4, 8, 17, .55) 62%, rgba(4, 8, 17, .92)); backdrop-filter: none; align-items: center; justify-content: flex-start; }
.title-screen::before { opacity: .3; }
.title-content { position: relative; width: min(1180px, 100%); height: 100%; display: flex; flex-direction: column; justify-content: center; padding-left: clamp(10px, 7vw, 100px); gap: 8px; }
.title-eyebrow { display: flex; align-items: center; gap: 10px; color: var(--gold); font-size: 10px; letter-spacing: .42em; font-weight: 700; text-transform: uppercase; }
.title-eyebrow::before { content: ""; width: 42px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.title-emblem { width: 58px; height: 58px; margin: 6px 0 -4px; filter: drop-shadow(0 0 22px rgba(242, 209, 136, .4)); animation: emblemFloat 4.5s ease-in-out infinite; }
.title-emblem svg { width: 100%; height: 100%; }
.game-title { margin: 0; font-family: var(--font-display); font-weight: 500; line-height: .86; letter-spacing: .04em; text-transform: uppercase; }
.game-title span { display: block; font-size: clamp(42px, 7.2vw, 104px); background: linear-gradient(180deg, #fff9e3 6%, #f3d488 38%, #b98737 72%, #f6e3a9 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 5px 0 rgba(0, 0, 0, .32)) drop-shadow(0 0 34px rgba(242, 209, 136, .18)); }
.game-title span:last-child { font-size: clamp(46px, 8.4vw, 122px); letter-spacing: .13em; margin-left: .04em; }
.title-sub { margin: 8px 0 18px; color: #cfd9ef; font-size: clamp(9px, 1.3vw, 13px); letter-spacing: .68em; text-transform: uppercase; text-shadow: 0 0 20px rgba(111, 232, 212, .4); }
.title-menu { display: flex; flex-direction: column; align-items: flex-start; gap: 9px; width: min(330px, 74vw); }
.title-menu .btn { width: 100%; justify-content: flex-start; }
.title-foot { position: absolute; left: clamp(10px, 7vw, 100px); bottom: 26px; display: flex; gap: 18px; color: var(--muted-2); font-size: 9.5px; letter-spacing: .16em; text-transform: uppercase; }
.title-foot span { display: flex; align-items: center; gap: 6px; }
.title-foot i { width: 4px; height: 4px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); }
.title-side { position: absolute; right: clamp(20px, 6vw, 90px); top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 14px; align-items: flex-end; max-width: 280px; text-align: right; }
.title-side .feature { display: flex; align-items: center; gap: 10px; padding: 8px 13px; border-radius: 999px; background: rgba(7, 12, 23, .48); border: 1px solid rgba(190, 214, 255, .1); color: #b9c6dd; font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase; backdrop-filter: blur(6px); }
.title-side .feature b { color: var(--gold); font-size: 11px; }

/* Buttons */
.btn { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 10px 20px; border-radius: 12px; border: 1px solid rgba(230, 216, 176, .28); background: linear-gradient(180deg, rgba(28, 43, 70, .86), rgba(11, 19, 34, .92)); color: #eaf0ff; font-size: 12.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; transition: transform .12s, border-color .18s, box-shadow .18s, background .18s; box-shadow: 0 8px 20px rgba(0, 0, 0, .24); overflow: hidden; }
.btn::after { content: ""; position: absolute; inset: 0; background: linear-gradient(120deg, transparent 30%, rgba(255, 255, 255, .14) 48%, transparent 62%); transform: translateX(-120%); transition: transform .5s ease; }
.btn:hover::after { transform: translateX(120%); }
.btn:hover { border-color: rgba(242, 209, 136, .55); transform: translateY(-1px); box-shadow: 0 12px 26px rgba(0, 0, 0, .32), 0 0 22px rgba(242, 209, 136, .08); }
.btn:active { transform: translateY(0) scale(.985); }
.btn:disabled { opacity: .38; cursor: not-allowed; transform: none; box-shadow: none; }
.btn.primary { border-color: rgba(242, 209, 136, .55); background: linear-gradient(180deg, rgba(122, 93, 41, .88), rgba(64, 46, 19, .95)); color: #fff4d2; text-shadow: 0 1px 2px rgba(0, 0, 0, .4); box-shadow: 0 10px 26px rgba(90, 60, 15, .3), inset 0 1px 0 rgba(255, 245, 205, .28); }
.btn.primary:hover { background: linear-gradient(180deg, rgba(150, 116, 52, .95), rgba(80, 58, 24, .98)); box-shadow: 0 12px 32px rgba(120, 82, 22, .4), 0 0 28px rgba(242, 209, 136, .16); }
.btn.ghost { background: rgba(9, 15, 28, .55); }
.btn.danger { border-color: rgba(255, 125, 157, .4); color: #ffd7df; background: linear-gradient(180deg, rgba(78, 24, 42, .85), rgba(39, 12, 23, .92)); }
.btn.small { min-height: 34px; padding: 7px 13px; font-size: 10px; border-radius: 9px; letter-spacing: .06em; }
.btn.icon-only { min-width: 40px; padding: 8px; }
.btn .ico { width: 17px; height: 17px; flex: 0 0 auto; }
.btn.primary .ico { color: var(--gold); }
.btn kbd { margin-left: auto; }

.kbd { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 5px; background: rgba(255, 255, 255, .1); border: 1px solid rgba(255, 255, 255, .14); color: #dfe7fa; font-size: 9px; font-weight: 700; }

/* Creation */
.creation-screen { background: radial-gradient(900px 600px at 26% 44%, rgba(54, 84, 141, .3), transparent 70%), rgba(4, 8, 16, .8); }
.creation-wrap { display: grid; grid-template-columns: minmax(260px, .85fr) minmax(340px, 1.15fr); width: min(1000px, 94vw); height: min(650px, 88vh); border-radius: 22px; overflow: hidden; border: 1px solid var(--line-strong); box-shadow: var(--shadow); background: rgba(7, 12, 24, .72); }
.creation-preview { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 42%, rgba(64, 108, 171, .28), transparent 64%), linear-gradient(160deg, #0b1528, #070c17); border-right: 1px solid var(--line); overflow: hidden; }
.creation-preview::before { content: ""; position: absolute; width: 320px; height: 320px; border-radius: 50%; border: 1px solid rgba(242, 209, 136, .14); top: 50%; left: 50%; transform: translate(-50%, -54%); box-shadow: 0 0 80px rgba(242, 209, 136, .06), inset 0 0 80px rgba(111, 232, 212, .05); }
.creation-preview::after { content: ""; position: absolute; width: 220px; height: 220px; border-radius: 50%; border: 1px dashed rgba(242, 209, 136, .13); top: 50%; left: 50%; transform: translate(-50%, -54%); animation: spin 40s linear infinite; }
#previewCanvas { position: relative; z-index: 1; width: 280px; height: 340px; max-width: 80%; }
.preview-caption { position: absolute; bottom: 26px; left: 0; right: 0; text-align: center; z-index: 1; }
.preview-caption b { display: block; font-family: var(--font-display); font-size: 19px; letter-spacing: .06em; color: #f7f0dc; }
.preview-caption span { font-size: 9px; letter-spacing: .22em; color: var(--muted-2); text-transform: uppercase; }
.creation-panel { display: flex; flex-direction: column; min-height: 0; background: linear-gradient(160deg, rgba(11, 19, 35, .92), rgba(7, 12, 23, .96)); }
.creation-head { padding: 20px 24px 12px; border-bottom: 1px solid var(--line); }
.creation-head .kicker { color: var(--gold); font-size: 8.5px; letter-spacing: .34em; font-weight: 700; }
.creation-head h2 { margin: 4px 0 2px; font-family: var(--font-display); font-weight: 500; font-size: 25px; letter-spacing: .03em; }
.creation-head p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.45; }
.creation-scroll { flex: 1; overflow-y: auto; padding: 16px 24px 20px; display: flex; flex-direction: column; gap: 16px; scrollbar-width: thin; scrollbar-color: rgba(242, 209, 136, .3) transparent; }
.creation-scroll::-webkit-scrollbar { width: 6px; }
.creation-scroll::-webkit-scrollbar-thumb { background: rgba(242, 209, 136, .3); border-radius: 4px; }
.field label, .field-label { display: block; font-size: 9px; letter-spacing: .2em; color: var(--muted-2); text-transform: uppercase; margin-bottom: 7px; font-weight: 700; }
.text-input { width: 100%; height: 42px; padding: 0 13px; border-radius: 10px; border: 1px solid var(--line); background: rgba(5, 10, 20, .7); color: #f2f6ff; font-family: var(--font-display); font-size: 16px; letter-spacing: .04em; outline: none; transition: border-color .18s, box-shadow .18s; }
.text-input:focus { border-color: rgba(242, 209, 136, .55); box-shadow: 0 0 0 3px rgba(242, 209, 136, .1); }
.choice-row { display: flex; flex-wrap: wrap; gap: 7px; }
.choice { min-width: 36px; height: 36px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--line); background: rgba(12, 21, 38, .8); color: var(--muted); font-size: 10.5px; letter-spacing: .04em; transition: all .15s; display: inline-flex; align-items: center; gap: 7px; }
.choice:hover { border-color: rgba(190, 214, 255, .38); color: #e8eeff; }
.choice.selected { border-color: rgba(242, 209, 136, .7); background: rgba(92, 68, 25, .5); color: #ffedb8; box-shadow: 0 0 16px rgba(242, 209, 136, .12); }
.swatch { width: 17px; height: 17px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .3); }
.option-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 7px; }
.option-card { padding: 9px 10px; border-radius: 10px; border: 1px solid var(--line); background: rgba(11, 19, 35, .7); text-align: left; transition: all .15s; }
.option-card b { display: block; font-size: 11px; color: #dfe7fa; }
.option-card span { display: block; font-size: 8.5px; color: var(--muted-2); margin-top: 2px; }
.option-card.selected { border-color: rgba(242, 209, 136, .6); background: rgba(78, 58, 22, .35); box-shadow: 0 0 18px rgba(242, 209, 136, .08); }
.option-card.selected b { color: var(--gold); }
.creation-foot { padding: 14px 24px; border-top: 1px solid var(--line); display: flex; align-items: center; gap: 10px; background: rgba(5, 9, 18, .5); }
.creation-foot .btn { flex: 1; }
.creation-foot .stat-mini { font-size: 9px; color: var(--muted-2); letter-spacing: .08em; }

/* Pause shell */
.pause-screen { padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left)); }
.pause-shell { display: grid; grid-template-columns: 236px 1fr; width: min(1180px, 97vw); height: min(720px, 92vh); border-radius: 20px; overflow: hidden; border: 1px solid var(--line-strong); box-shadow: var(--shadow); background: linear-gradient(160deg, rgba(9, 16, 30, .97), rgba(5, 9, 18, .98)); }
.pause-rail { display: flex; flex-direction: column; padding: 16px 12px; gap: 4px; border-right: 1px solid var(--line); background: linear-gradient(180deg, rgba(16, 28, 49, .72), rgba(7, 12, 23, .8)); min-height: 0; }
.rail-head { padding: 5px 10px 14px; margin-bottom: 4px; border-bottom: 1px solid var(--line); }
.rail-head .kicker { color: var(--gold); font-size: 7.5px; letter-spacing: .3em; }
.rail-head h3 { margin: 3px 0 0; font-family: var(--font-display); font-size: 17px; font-weight: 500; letter-spacing: .04em; }
.rail-head p { margin: 2px 0 0; font-size: 9px; color: var(--muted-2); }
.rail-nav { display: flex; flex-direction: column; gap: 2px; overflow-y: auto; flex: 1; scrollbar-width: none; }
.rail-nav::-webkit-scrollbar { display: none; }
.rail-btn { display: flex; align-items: center; gap: 9px; width: 100%; padding: 8px 10px; border-radius: 9px; border: 1px solid transparent; background: transparent; color: #aebbd4; font-size: 10.5px; letter-spacing: .04em; text-align: left; transition: all .14s; }
.rail-btn .ico { width: 16px; height: 16px; opacity: .8; }
.rail-btn small { margin-left: auto; font-size: 8px; color: var(--muted-2); }
.rail-btn:hover { background: rgba(255, 255, 255, .045); color: #e8efff; }
.rail-btn.active { background: linear-gradient(90deg, rgba(92, 68, 25, .42), rgba(35, 28, 14, .18)); border-color: rgba(242, 209, 136, .28); color: var(--gold); }
.rail-btn.active .ico { opacity: 1; }
.rail-foot { padding-top: 10px; margin-top: 4px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 4px; }
.pause-main { display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.panel-head { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 16px 22px 13px; border-bottom: 1px solid var(--line); background: rgba(7, 12, 23, .35); }
.panel-head .kicker { color: var(--gold); font-size: 8px; letter-spacing: .3em; font-weight: 700; }
.panel-head h2 { margin: 2px 0 0; font-family: var(--font-display); font-weight: 500; font-size: 22px; letter-spacing: .03em; }
.panel-actions { display: flex; align-items: center; gap: 7px; }
.panel-body { flex: 1; min-height: 0; overflow-y: auto; padding: 16px 22px 22px; scrollbar-width: thin; scrollbar-color: rgba(242, 209, 136, .26) transparent; }
.panel-body::-webkit-scrollbar { width: 6px; }
.panel-body::-webkit-scrollbar-thumb { background: rgba(242, 209, 136, .26); border-radius: 4px; }

/* generic content */
.section-title { display: flex; align-items: center; gap: 9px; margin: 2px 0 10px; color: var(--muted-2); font-size: 8.5px; letter-spacing: .24em; text-transform: uppercase; font-weight: 700; }
.section-title::after { content: ""; flex: 1; height: 1px; background: var(--line); }
.empty-note { padding: 30px 20px; text-align: center; color: var(--muted-2); font-size: 11px; border: 1px dashed var(--line); border-radius: 12px; }
.empty-note b { display: block; color: var(--muted); font-size: 13px; margin-bottom: 4px; }

.inventory-layout { display: grid; grid-template-columns: 1fr 270px; gap: 16px; align-items: start; }
.inv-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(92px, 1fr)); gap: 8px; }
.item-card { position: relative; display: flex; flex-direction: column; align-items: center; gap: 5px; padding: 10px 7px 8px; border-radius: 11px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(18, 30, 52, .7), rgba(9, 16, 30, .8)); transition: all .14s; min-height: 92px; }
.item-card:hover { border-color: rgba(190, 214, 255, .34); transform: translateY(-2px); }
.item-card.selected { border-color: rgba(242, 209, 136, .55); background: linear-gradient(160deg, rgba(58, 47, 23, .55), rgba(17, 22, 35, .9)); box-shadow: 0 0 20px rgba(242, 209, 136, .08); }
.item-card .item-ico { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 9px; background: radial-gradient(circle at 40% 30%, rgba(255, 255, 255, .12), rgba(255, 255, 255, .02)); border: 1px solid rgba(255, 255, 255, .07); }
.item-card .item-ico svg { width: 21px; height: 21px; }
.item-card b { font-size: 9px; font-weight: 600; text-align: center; line-height: 1.2; color: #dbe4f6; }
.item-card .qty { position: absolute; right: 5px; bottom: 4px; font-size: 8px; color: var(--gold); font-weight: 700; }
.item-card .rarity { position: absolute; left: 5px; top: 5px; width: 4px; height: 4px; border-radius: 50%; background: var(--r, #8fa2c4); box-shadow: 0 0 6px var(--r, #8fa2c4); }
.detail-panel { position: sticky; top: 0; padding: 14px; border-radius: 13px; border: 1px solid var(--line); background: linear-gradient(165deg, rgba(17, 28, 49, .76), rgba(8, 14, 27, .88)); }
.detail-head { display: flex; gap: 11px; align-items: center; margin-bottom: 10px; }
.detail-ico { width: 46px; height: 46px; border-radius: 12px; display: grid; place-items: center; background: radial-gradient(circle at 40% 30%, rgba(255, 255, 255, .13), rgba(255, 255, 255, .02)); border: 1px solid var(--line); flex: 0 0 auto; }
.detail-ico svg { width: 27px; height: 27px; }
.detail-head h4 { margin: 0; font-family: var(--font-display); font-size: 16px; font-weight: 500; letter-spacing: .02em; }
.detail-head span { font-size: 8.5px; color: var(--muted-2); letter-spacing: .14em; text-transform: uppercase; }
.detail-desc { margin: 0 0 11px; font-size: 10.5px; line-height: 1.5; color: var(--muted); }
.stat-row { display: flex; justify-content: space-between; gap: 10px; padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, .05); font-size: 10px; color: var(--muted); }
.stat-row b { color: #e8efff; font-weight: 600; }
.stat-row b.up { color: var(--green); } .stat-row b.down { color: var(--rose); }
.detail-actions { display: flex; flex-direction: column; gap: 6px; margin-top: 12px; }
.detail-actions .btn { width: 100%; min-height: 36px; font-size: 10px; }
.tag-row { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 9px; }
.tag { padding: 3px 7px; border-radius: 5px; background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .08); font-size: 7.5px; letter-spacing: .1em; color: var(--muted); text-transform: uppercase; }
.tag.gold { color: var(--gold); border-color: rgba(242, 209, 136, .3); background: rgba(242, 209, 136, .08); }
.tag.teal { color: var(--teal); border-color: rgba(111, 232, 212, .3); background: rgba(111, 232, 212, .08); }
.tag.rose { color: var(--rose); border-color: rgba(255, 125, 157, .3); background: rgba(255, 125, 157, .08); }
.tag.violet { color: var(--violet); border-color: rgba(166, 139, 255, .3); background: rgba(166, 139, 255, .08); }

/* equipment */
.equip-layout { display: grid; grid-template-columns: 1fr 300px; gap: 16px; align-items: start; }
.equip-slots { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.equip-slot { display: flex; align-items: center; gap: 10px; padding: 11px; border-radius: 11px; border: 1px solid var(--line); background: rgba(13, 22, 40, .62); text-align: left; transition: all .14s; }
.equip-slot:hover { border-color: rgba(242, 209, 136, .4); }
.equip-slot .slot-ico { width: 38px; height: 38px; border-radius: 9px; display: grid; place-items: center; background: rgba(255, 255, 255, .04); border: 1px solid rgba(255, 255, 255, .07); flex: 0 0 auto; }
.equip-slot .slot-ico svg { width: 22px; height: 22px; }
.equip-slot .slot-meta { min-width: 0; }
.equip-slot .slot-meta span { display: block; font-size: 7.5px; letter-spacing: .18em; color: var(--muted-2); text-transform: uppercase; }
.equip-slot .slot-meta b { display: block; font-size: 10.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: #e4ebfa; font-weight: 600; }
.equip-preview { grid-column: 1 / -1; height: 210px; border-radius: 13px; border: 1px solid var(--line); background: radial-gradient(circle at 50% 42%, rgba(54, 88, 145, .25), transparent 66%), rgba(6, 11, 21, .7); position: relative; overflow: hidden; display: grid; place-items: center; }
.equip-preview canvas { width: 100%; height: 100%; }
.equip-preview .preview-badge { position: absolute; top: 10px; left: 12px; font-size: 8px; letter-spacing: .22em; color: var(--muted-2); }
.derived-stats { display: flex; flex-direction: column; gap: 2px; }
.derived-stat { display: flex; justify-content: space-between; align-items: center; padding: 7px 2px; border-bottom: 1px solid rgba(255, 255, 255, .05); font-size: 10.5px; }
.derived-stat span { color: var(--muted); display: flex; align-items: center; gap: 6px; }
.derived-stat b { font-variant-numeric: tabular-nums; color: #f0f4ff; }
.derived-stat small { color: var(--green); font-size: 8.5px; margin-left: 4px; }

/* skills */
.skill-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 10px; }
.skill-card { position: relative; padding: 13px; border-radius: 12px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(20, 33, 58, .72), rgba(9, 16, 30, .82)); transition: all .15s; overflow: hidden; }
.skill-card.locked { opacity: .6; }
.skill-card.active-skill { border-color: rgba(111, 232, 212, .55); box-shadow: 0 0 24px rgba(111, 232, 212, .1); }
.skill-card:hover { border-color: rgba(190, 214, 255, .34); }
.skill-top { display: flex; gap: 10px; align-items: flex-start; }
.skill-glyph { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; font-family: var(--font-display); font-size: 18px; color: var(--gold); background: radial-gradient(circle at 40% 30%, rgba(242, 209, 136, .16), rgba(255, 255, 255, .02)); border: 1px solid rgba(242, 209, 136, .24); flex: 0 0 auto; }
.skill-top h4 { margin: 0; font-family: var(--font-display); font-size: 15px; font-weight: 500; }
.skill-top span { display: block; font-size: 8px; color: var(--muted-2); letter-spacing: .14em; text-transform: uppercase; margin-top: 2px; }
.skill-desc { margin: 8px 0 10px; font-size: 10px; line-height: 1.45; color: var(--muted); min-height: 28px; }
.skill-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.skill-cost { font-size: 8.5px; color: var(--blue); letter-spacing: .08em; }
.skill-card .btn { min-height: 28px; padding: 4px 9px; font-size: 8.5px; }
.skill-card .ribbon { position: absolute; top: 9px; right: -24px; transform: rotate(38deg); background: rgba(111, 232, 212, .18); border-top: 1px solid rgba(111, 232, 212, .4); border-bottom: 1px solid rgba(111, 232, 212, .4); color: var(--teal); font-size: 6.5px; letter-spacing: .14em; padding: 2px 24px; }

/* map */
.map-layout { display: grid; grid-template-columns: 1fr 230px; gap: 16px; align-items: start; }
.map-canvas-wrap { position: relative; border-radius: 13px; border: 1px solid var(--line); background: rgba(5, 10, 20, .7); overflow: hidden; aspect-ratio: 16 / 11; }
.map-canvas-wrap canvas { width: 100%; height: 100%; display: block; }
.map-legend { position: absolute; left: 10px; bottom: 10px; display: flex; gap: 10px; padding: 5px 9px; border-radius: 7px; background: rgba(5, 9, 18, .8); font-size: 7.5px; color: var(--muted); letter-spacing: .08em; }
.map-legend i { width: 5px; height: 5px; border-radius: 50%; display: inline-block; margin-right: 3px; }
.zone-list { display: flex; flex-direction: column; gap: 5px; }
.zone-item { display: flex; align-items: center; gap: 9px; padding: 9px 11px; border-radius: 9px; border: 1px solid var(--line); background: rgba(11, 19, 35, .6); text-align: left; transition: all .14s; }
.zone-item.current { border-color: rgba(242, 209, 136, .45); background: rgba(74, 55, 21, .3); }
.zone-item.locked { opacity: .45; }
.zone-item .z-ico { width: 27px; height: 27px; border-radius: 7px; display: grid; place-items: center; background: rgba(255, 255, 255, .05); font-size: 12px; color: var(--teal); flex: 0 0 auto; }
.zone-item b { display: block; font-size: 10px; }
.zone-item span { display: block; font-size: 8px; color: var(--muted-2); }

/* quests */
.quest-list { display: flex; flex-direction: column; gap: 9px; }
.quest-card { display: flex; gap: 12px; padding: 13px; border-radius: 12px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(18, 30, 52, .68), rgba(8, 14, 27, .8)); }
.quest-card.done { opacity: .62; }
.quest-card.main { border-left: 2px solid var(--gold-2); }
.quest-mark { width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; flex: 0 0 auto; background: rgba(242, 209, 136, .09); border: 1px solid rgba(242, 209, 136, .22); color: var(--gold); font-family: var(--font-display); }
.quest-mark.side { background: rgba(111, 232, 212, .08); border-color: rgba(111, 232, 212, .2); color: var(--teal); }
.quest-body { flex: 1; min-width: 0; }
.quest-body h4 { margin: 0 0 2px; font-family: var(--font-display); font-size: 14px; font-weight: 500; }
.quest-body p { margin: 0 0 6px; font-size: 10px; line-height: 1.4; color: var(--muted); }
.quest-progress { display: flex; align-items: center; gap: 8px; }
.quest-progress .track { flex: 1; height: 4px; border-radius: 4px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.quest-progress .track i { display: block; height: 100%; background: linear-gradient(90deg, var(--gold-3), var(--gold)); border-radius: 4px; }
.quest-progress span { font-size: 8px; color: var(--muted-2); letter-spacing: .06em; white-space: nowrap; }
.quest-reward { display: flex; gap: 5px; margin-top: 7px; flex-wrap: wrap; }

/* creatures */
.creature-layout { display: grid; grid-template-columns: 1fr 290px; gap: 16px; align-items: start; }
.creature-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 8px; }
.creature-card { position: relative; padding: 11px 10px 9px; border-radius: 12px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(20, 33, 58, .7), rgba(8, 14, 27, .82)); text-align: center; transition: all .15s; overflow: hidden; }
.creature-card:hover { transform: translateY(-2px); border-color: rgba(190, 214, 255, .34); }
.creature-card.active { border-color: rgba(111, 232, 212, .55); box-shadow: 0 0 22px rgba(111, 232, 212, .1); }
.creature-card.locked { opacity: .48; filter: saturate(.3); }
.creature-card .c-orb { width: 42px; height: 42px; margin: 0 auto 6px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--el, #7fb4ff) 38%, #101a2e 80%); box-shadow: 0 0 18px var(--el, #7fb4ff); position: relative; }
.creature-card .c-orb::after { content: ""; position: absolute; inset: 9px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .45); }
.creature-card b { display: block; font-size: 10.5px; color: #e4ebfa; }
.creature-card span { display: block; font-size: 8px; color: var(--muted-2); letter-spacing: .1em; text-transform: uppercase; }
.creature-card .c-lv { position: absolute; top: 7px; right: 8px; font-size: 7.5px; color: var(--gold); }
.creature-detail { padding: 14px; border-radius: 13px; border: 1px solid var(--line); background: linear-gradient(165deg, rgba(17, 28, 49, .76), rgba(8, 14, 27, .88)); position: sticky; top: 0; }
.creature-hero { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.creature-hero .big-orb { width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--el, #7fb4ff) 38%, #101a2e 80%); box-shadow: 0 0 26px var(--el, #7fb4ff); position: relative; flex: 0 0 auto; }
.creature-hero .big-orb::after { content: ""; position: absolute; inset: 12px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .5); }
.creature-hero h4 { margin: 0; font-family: var(--font-display); font-size: 19px; font-weight: 500; }
.creature-hero span { font-size: 8.5px; color: var(--muted-2); letter-spacing: .16em; text-transform: uppercase; }
.creature-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: 12px; }
.creature-actions .btn { min-height: 33px; font-size: 9px; padding: 6px 8px; }
.creature-actions .btn.wide { grid-column: 1 / -1; }
.bond-bar { display: flex; align-items: center; gap: 7px; font-size: 8.5px; color: var(--muted); margin-top: 4px; }
.bond-bar .track { flex: 1; height: 4px; border-radius: 4px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.bond-bar .track i { display: block; height: 100%; background: linear-gradient(90deg, #ff8aa5, #ffd27a); border-radius: 4px; }

/* collection */
.collection-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 9px; }
.collection-card { position: relative; display: flex; align-items: center; gap: 10px; padding: 11px; border-radius: 12px; border: 1px solid var(--line); background: rgba(13, 22, 40, .62); }
.collection-card.unseen { opacity: .45; filter: saturate(.2); }
.collection-card .c-orb { width: 38px; height: 38px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--el, #7fb4ff) 38%, #101a2e 80%); box-shadow: 0 0 16px var(--el, #7fb4ff); flex: 0 0 auto; }
.collection-card b { display: block; font-size: 10.5px; }
.collection-card span { display: block; font-size: 8px; color: var(--muted-2); letter-spacing: .1em; text-transform: uppercase; }
.collection-card .seen-mark { margin-left: auto; color: var(--green); font-size: 13px; }
.collection-progress { display: flex; align-items: center; gap: 10px; margin-bottom: 13px; padding: 10px 13px; border-radius: 11px; border: 1px solid var(--line); background: rgba(111, 232, 212, .04); }
.collection-progress b { font-family: var(--font-display); font-size: 21px; color: var(--teal); font-weight: 500; }
.collection-progress span { font-size: 9px; color: var(--muted); letter-spacing: .12em; text-transform: uppercase; }
.collection-progress .track { flex: 1; height: 5px; border-radius: 5px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.collection-progress .track i { display: block; height: 100%; background: linear-gradient(90deg, #3f9c8e, var(--teal)); box-shadow: 0 0 10px var(--teal); }

/* crafting */
.craft-layout { display: grid; grid-template-columns: 1fr 270px; gap: 16px; align-items: start; }
.recipe-list { display: flex; flex-direction: column; gap: 7px; }
.recipe-card { display: flex; align-items: center; gap: 11px; padding: 10px 12px; border-radius: 11px; border: 1px solid var(--line); background: rgba(13, 22, 40, .6); text-align: left; transition: all .14s; }
.recipe-card:hover { border-color: rgba(242, 209, 136, .4); }
.recipe-card.selected { border-color: rgba(242, 209, 136, .55); background: rgba(60, 47, 22, .36); }
.recipe-ico { width: 36px; height: 36px; border-radius: 9px; display: grid; place-items: center; background: rgba(255, 255, 255, .04); border: 1px solid rgba(255, 255, 255, .07); flex: 0 0 auto; }
.recipe-ico svg { width: 20px; height: 20px; }
.recipe-card b { display: block; font-size: 10.5px; }
.recipe-card span { display: block; font-size: 8px; color: var(--muted-2); }
.recipe-card .can { margin-left: auto; font-size: 8px; color: var(--green); }
.recipe-card .cannot { margin-left: auto; font-size: 8px; color: var(--rose); }
.mats-list { display: flex; flex-direction: column; gap: 4px; margin: 9px 0; }
.mat-row { display: flex; justify-content: space-between; gap: 8px; font-size: 9.5px; color: var(--muted); }
.mat-row b { color: #e8efff; } .mat-row b.miss { color: var(--rose); }

/* stats */
.stats-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
.stat-block { padding: 13px; border-radius: 12px; border: 1px solid var(--line); background: rgba(13, 22, 40, .6); }
.stat-block h4 { margin: 0 0 8px; font-family: var(--font-display); font-size: 15px; font-weight: 500; color: #f1e7cd; }
.stat-big { display: flex; align-items: baseline; gap: 8px; margin-bottom: 8px; }
.stat-big b { font-family: var(--font-display); font-size: 34px; font-weight: 500; color: var(--gold); line-height: 1; }
.stat-big span { font-size: 9px; color: var(--muted-2); letter-spacing: .14em; text-transform: uppercase; }
.attr-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 0; border-bottom: 1px solid rgba(255, 255, 255, .05); font-size: 10.5px; }
.attr-row span { color: var(--muted); }
.attr-row b { font-variant-numeric: tabular-nums; }
.attr-row .plus { width: 24px; height: 24px; border-radius: 6px; border: 1px solid rgba(242, 209, 136, .4); background: rgba(242, 209, 136, .1); color: var(--gold); font-size: 13px; display: grid; place-items: center; }
.attr-row .plus:disabled { opacity: .3; }

/* settings */
.settings-list { display: flex; flex-direction: column; gap: 4px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 11px 2px; border-bottom: 1px solid rgba(255, 255, 255, .06); }
.setting-row .s-label b { display: block; font-size: 11px; font-weight: 600; }
.setting-row .s-label span { display: block; font-size: 8.5px; color: var(--muted-2); margin-top: 2px; }
.setting-control { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
input[type="range"] { -webkit-appearance: none; appearance: none; width: 130px; height: 4px; border-radius: 4px; background: rgba(255, 255, 255, .14); outline: none; }
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 10px rgba(242, 209, 136, .5); cursor: pointer; }
input[type="range"]::-moz-range-thumb { width: 14px; height: 14px; border: none; border-radius: 50%; background: var(--gold); cursor: pointer; }
.range-val { width: 30px; text-align: right; font-size: 9px; color: var(--gold); font-variant-numeric: tabular-nums; }
.toggle { width: 42px; height: 23px; border-radius: 999px; border: 1px solid var(--line); background: rgba(255, 255, 255, .08); position: relative; transition: all .18s; flex: 0 0 auto; }
.toggle::after { content: ""; position: absolute; top: 2px; left: 2px; width: 17px; height: 17px; border-radius: 50%; background: #8fa2c4; transition: all .18s; }
.toggle.on { background: rgba(111, 232, 212, .22); border-color: rgba(111, 232, 212, .5); }
.toggle.on::after { left: 21px; background: var(--teal); box-shadow: 0 0 10px var(--teal); }
.setting-row .select-like { padding: 7px 10px; border-radius: 8px; border: 1px solid var(--line); background: rgba(9, 15, 28, .8); font-size: 9.5px; color: #dfe7fa; }

/* save slots */
.save-list { display: flex; flex-direction: column; gap: 8px; }
.save-slot { display: flex; align-items: center; gap: 13px; padding: 13px; border-radius: 12px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(18, 30, 52, .68), rgba(8, 14, 27, .8)); text-align: left; transition: all .14s; }
.save-slot:hover { border-color: rgba(242, 209, 136, .45); }
.save-slot .slot-num { width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; background: rgba(242, 209, 136, .09); border: 1px solid rgba(242, 209, 136, .22); color: var(--gold); font-family: var(--font-display); font-size: 16px; flex: 0 0 auto; }
.save-slot .slot-info { flex: 1; min-width: 0; }
.save-slot .slot-info b { display: block; font-size: 11.5px; }
.save-slot .slot-info span { display: block; font-size: 8.5px; color: var(--muted-2); margin-top: 2px; }
.save-slot .slot-actions { display: flex; gap: 5px; }

/* Shop */
.shop-shell { width: min(820px, 94vw); height: min(620px, 88vh); display: flex; flex-direction: column; border-radius: 20px; border: 1px solid var(--line-strong); box-shadow: var(--shadow); background: linear-gradient(160deg, rgba(10, 17, 32, .98), rgba(5, 9, 18, .99)); overflow: hidden; animation: modalIn .25s ease; }
.shop-head { display: flex; align-items: center; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--line); }
.shop-portrait { width: 42px; height: 42px; border-radius: 11px; display: grid; place-items: center; background: radial-gradient(circle at 40% 30%, rgba(111, 232, 212, .2), rgba(255, 255, 255, .02)); border: 1px solid rgba(111, 232, 212, .24); color: var(--teal); font-family: var(--font-display); font-size: 18px; }
.shop-head h3 { margin: 0; font-family: var(--font-display); font-size: 19px; font-weight: 500; }
.shop-head p { margin: 1px 0 0; font-size: 9px; color: var(--muted-2); }
.shop-head .shop-gold { margin-left: auto; display: flex; align-items: center; gap: 7px; color: var(--gold); font-size: 13px; font-weight: 700; }
.shop-head .shop-gold svg { width: 16px; height: 16px; }
.shop-tabs { display: flex; gap: 3px; padding: 9px 18px 0; }
.shop-tab { padding: 7px 13px; border-radius: 8px 8px 0 0; border: 1px solid transparent; background: transparent; color: var(--muted); font-size: 9.5px; letter-spacing: .08em; text-transform: uppercase; }
.shop-tab.active { border-color: var(--line); border-bottom-color: transparent; background: rgba(255, 255, 255, .03); color: var(--gold); }
.shop-body { flex: 1; overflow-y: auto; padding: 13px 18px 18px; }
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 7px; }
.shop-item { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-radius: 10px; border: 1px solid var(--line); background: rgba(13, 22, 40, .55); text-align: left; transition: all .14s; }
.shop-item:hover { border-color: rgba(242, 209, 136, .4); background: rgba(30, 34, 42, .6); }
.shop-item .s-ico { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; background: rgba(255, 255, 255, .04); border: 1px solid rgba(255, 255, 255, .07); flex: 0 0 auto; }
.shop-item .s-ico svg { width: 18px; height: 18px; }
.shop-item .s-info { flex: 1; min-width: 0; }
.shop-item .s-info b { display: block; font-size: 10px; }
.shop-item .s-info span { display: block; font-size: 8px; color: var(--muted-2); }
.shop-item .price { color: var(--gold); font-size: 10px; font-weight: 700; display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.shop-item .price svg { width: 12px; height: 12px; }
.shop-item .price.cant { color: var(--rose); }
.shop-foot { padding: 10px 18px; border-top: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.shop-foot span { font-size: 8.5px; color: var(--muted-2); }

/* Dialogue */
.dialogue-layer { position: absolute; inset: 0; z-index: 60; display: flex; align-items: flex-end; justify-content: center; padding: 0 max(18px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left)); pointer-events: none; }
.dialogue-box { width: min(900px, 94vw); display: flex; gap: 14px; padding: 14px; border-radius: 17px; border: 1px solid var(--line-strong); background: linear-gradient(160deg, rgba(10, 17, 32, .97), rgba(6, 10, 20, .98)); box-shadow: 0 24px 60px rgba(0, 0, 0, .55), inset 0 0 40px rgba(242, 209, 136, .03); pointer-events: auto; animation: dialogueIn .25s ease; }
@keyframes dialogueIn { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
.dialogue-portrait { width: 92px; height: 104px; border-radius: 13px; flex: 0 0 auto; background: radial-gradient(circle at 50% 35%, rgba(111, 232, 212, .18), rgba(8, 14, 26, .9) 70%); border: 1px solid var(--line); overflow: hidden; display: grid; place-items: end center; position: relative; }
.dialogue-portrait canvas { width: 100%; height: 100%; }
.dialogue-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.dialogue-name { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.dialogue-name b { font-family: var(--font-display); font-size: 16px; color: var(--gold); font-weight: 500; letter-spacing: .03em; }
.dialogue-name span { font-size: 7.5px; letter-spacing: .2em; color: var(--muted-2); text-transform: uppercase; }
.dialogue-text { margin: 0; font-size: 12px; line-height: 1.6; color: #dfe7f6; min-height: 40px; }
.dialogue-text .caret { display: inline-block; width: 7px; height: 13px; background: var(--gold); margin-left: 2px; vertical-align: -2px; animation: blink 1s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0; } }
.dialogue-choices { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.dialogue-choices .btn { min-height: 32px; padding: 6px 12px; font-size: 9.5px; }
.dialogue-next { align-self: flex-end; margin-top: 8px; font-size: 8px; color: var(--muted-2); letter-spacing: .14em; text-transform: uppercase; display: flex; align-items: center; gap: 5px; }
.dialogue-next kbd { min-width: 18px; height: 18px; font-size: 8px; }

/* modal */
.modal-root { position: absolute; inset: 0; z-index: 70; display: flex; align-items: center; justify-content: center; padding: 18px; background: rgba(3, 6, 12, .62); backdrop-filter: blur(5px); }
.modal-root > * { pointer-events: auto; }
.modal-card { width: min(440px, 94vw); padding: 20px; border-radius: 18px; border: 1px solid var(--line-strong); background: linear-gradient(160deg, rgba(16, 26, 46, .98), rgba(7, 12, 23, .99)); box-shadow: var(--shadow); animation: modalIn .22s ease; }
@keyframes modalIn { from { opacity: 0; transform: translateY(12px) scale(.98); } to { opacity: 1; transform: none; } }
.modal-card h3 { margin: 0 0 5px; font-family: var(--font-display); font-weight: 500; font-size: 20px; }
.modal-card p { margin: 0 0 14px; font-size: 11px; line-height: 1.5; color: var(--muted); }
.modal-card .modal-actions { display: flex; justify-content: flex-end; gap: 7px; }
.modal-card .modal-actions .btn { min-height: 36px; font-size: 10px; }

/* quick panel */
.quick-panel { position: absolute; right: 24px; bottom: 120px; z-index: 55; width: 250px; padding: 11px; border-radius: 15px; border: 1px solid var(--line-strong); background: rgba(8, 14, 27, .96); box-shadow: var(--shadow); animation: modalIn .2s ease; }
.quick-panel h4 { margin: 0 0 8px; font-size: 8px; letter-spacing: .22em; color: var(--gold); text-transform: uppercase; }
.quick-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.quick-actions .btn { min-height: 42px; font-size: 8.5px; padding: 6px; flex-direction: column; gap: 3px; }
.quick-actions .btn .ico { width: 18px; height: 18px; }

/* game over / victory */
.cinematic-screen { flex-direction: column; text-align: center; gap: 12px; background: radial-gradient(700px 500px at 50% 40%, rgba(90, 20, 35, .3), transparent 70%), rgba(3, 5, 10, .88); }
.cinematic-screen h1 { margin: 0; font-family: var(--font-display); font-size: clamp(34px, 6vw, 64px); font-weight: 500; letter-spacing: .12em; background: linear-gradient(180deg, #fff4d0, #d7a84c); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cinematic-screen p { margin: 0; max-width: 560px; color: var(--muted); font-size: 12px; line-height: 1.6; }
.cinematic-stats { display: flex; gap: 20px; margin: 10px 0; flex-wrap: wrap; justify-content: center; }
.cinematic-stats div { padding: 9px 16px; border-radius: 10px; border: 1px solid var(--line); background: rgba(255, 255, 255, .03); min-width: 90px; }
.cinematic-stats b { display: block; font-family: var(--font-display); font-size: 22px; color: var(--gold); font-weight: 500; }
.cinematic-stats span { font-size: 8px; letter-spacing: .16em; color: var(--muted-2); text-transform: uppercase; }

/* credits */
.credits-scroll { max-width: 640px; width: 100%; height: 100%; overflow-y: auto; padding: 30px 20px; text-align: center; }
.credits-scroll h1 { font-family: var(--font-display); font-size: 30px; color: var(--gold); font-weight: 500; letter-spacing: .16em; margin: 0 0 4px; }
.credits-scroll h2 { font-size: 9px; letter-spacing: .34em; color: var(--muted-2); text-transform: uppercase; margin: 0 0 24px; }
.credits-block { margin-bottom: 18px; }
.credits-block b { display: block; font-size: 9px; letter-spacing: .24em; color: var(--teal); text-transform: uppercase; margin-bottom: 4px; }
.credits-block span { display: block; font-size: 11px; color: #dbe4f5; line-height: 1.6; }
.credits-scroll .btn { margin-top: 12px; }

/* rotate hint */
.rotate-hint { position: absolute; left: 50%; top: 12px; transform: translateX(-50%); z-index: 80; display: flex; align-items: center; gap: 8px; padding: 7px 13px; border-radius: 999px; background: rgba(8, 14, 27, .92); border: 1px solid var(--line); font-size: 9px; color: var(--muted); animation: promptIn .4s ease; }
.rotate-hint b { color: var(--gold); font-size: 9px; }
.rotate-hint span { display: none; }
.rotate-icon { font-size: 14px; color: var(--teal); }

/* utility */
.row { display: flex; align-items: center; gap: 8px; }
.row.between { justify-content: space-between; }
.row.wrap { flex-wrap: wrap; }
.grow { flex: 1; }
.mt6 { margin-top: 6px; } .mt10 { margin-top: 10px; } .mt14 { margin-top: 14px; }
.muted { color: var(--muted); } .muted2 { color: var(--muted-2); }
.gold { color: var(--gold); } .teal { color: var(--teal); } .rose { color: var(--rose); } .green { color: var(--green); }
.center { text-align: center; }
.pill { display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 999px; background: rgba(255, 255, 255, .05); border: 1px solid rgba(255, 255, 255, .08); font-size: 8px; color: var(--muted); letter-spacing: .08em; text-transform: uppercase; }
.divider { height: 1px; background: var(--line); margin: 12px 0; }
.fade-in { animation: screenIn .25s ease both; }

/* Responsive */
@media (max-width: 900px) {
  .pause-shell { grid-template-columns: 78px 1fr; }
  .rail-head { padding: 4px 4px 10px; text-align: center; }
  .rail-head h3, .rail-head p, .rail-head .kicker { display: none; }
  .rail-btn { justify-content: center; padding: 10px 6px; }
  .rail-btn span { display: none; }
  .rail-btn small { display: none; }
  .rail-btn .ico { width: 20px; height: 20px; }
  .rail-foot .btn span { display: none; }
  .inventory-layout, .creature-layout, .craft-layout, .map-layout { grid-template-columns: 1fr; }
  .detail-panel, .creature-detail { position: static; }
  .equip-layout { grid-template-columns: 1fr; }
  .equip-preview { height: 160px; }
  .title-side { display: none; }
  .creation-wrap { grid-template-columns: 1fr; height: 92vh; }
  .creation-preview { min-height: 180px; border-right: 0; border-bottom: 1px solid var(--line); }
  #previewCanvas { width: 180px; height: 200px; }
  .preview-caption { bottom: 8px; }
  .preview-caption b { font-size: 15px; }
  .creation-preview::before, .creation-preview::after { width: 190px; height: 190px; }
  .panel-head { padding: 12px 14px 10px; }
  .panel-body { padding: 12px 14px 18px; }
  .stats-layout { grid-template-columns: 1fr; }
  .hint-bar { display: none; }
  .hud-side { top: 96px; width: 200px; }
  .toasts { top: 82px; width: 230px; }
  .screen { padding: 10px; }
}

@media (max-width: 640px) {
  .hud-left { width: 58vw; }
  .hud-side { display: none; }
  .char-portrait { width: 42px; height: 42px; }
  .char-badge { padding: 6px 9px 6px 6px; }
  .hud-right .zone-chip { display: none; }
  .game-title span { font-size: 40px; }
  .game-title span:last-child { font-size: 45px; }
  .title-content { justify-content: center; padding-left: 22px; }
  .title-foot { left: 22px; font-size: 8px; gap: 10px; }
  .title-menu { width: min(300px, 84vw); }
  .creation-head h2 { font-size: 21px; }
  .creation-scroll { padding: 12px 16px; }
  .creation-head, .creation-foot { padding-left: 16px; padding-right: 16px; }
  .inv-grid { grid-template-columns: repeat(auto-fill, minmax(78px, 1fr)); }
  .item-card { min-height: 82px; }
  .skill-grid { grid-template-columns: 1fr; }
  .boss-bar { bottom: 10px; width: 80vw; }
  .interact-prompt { bottom: 108px; }
  .dialogue-portrait { width: 64px; height: 78px; }
  .dialogue-box { padding: 10px; gap: 9px; }
  .dialogue-text { font-size: 11px; }
  .touch-controls .action-cluster { transform: scale(.92); transform-origin: bottom right; }
  .touch-controls .joystick { transform: scale(.92); transform-origin: bottom left; }
  .shop-grid { grid-template-columns: 1fr; }
}

@media (max-height: 500px) {
  .creation-wrap { height: 96vh; }
  .creation-preview { min-height: 120px; }
  #previewCanvas { width: 130px; height: 150px; }
  .creation-head { padding: 10px 16px 8px; }
  .creation-head p { display: none; }
  .creation-head h2 { font-size: 19px; }
  .creation-scroll { gap: 10px; padding: 10px 16px; }
  .pause-shell { height: 96vh; }
  .title-emblem { width: 42px; height: 42px; }
  .title-sub { margin: 4px 0 10px; }
  .game-title span { font-size: 38px; }
  .game-title span:last-child { font-size: 44px; }
  .title-menu { gap: 5px; }
  .title-menu .btn { min-height: 36px; padding: 7px 14px; font-size: 10.5px; }
  .title-foot { display: none; }
  .hud-side { display: none; }
}

