/* -------------------------------------------------------------------------- */
/* World                                                                      */
/* -------------------------------------------------------------------------- */
export class World {
  constructor(game) {
    this.game = game;
    this.maps = buildMaps();
    this.zoneKey = null;
    this.map = null;
    this.decor = [];
    this.groundCanvas = null;
    this.weather = [];
    this.time = 0;
    this.lights = [];
    this.tileAnimated = [];
    this.transitionCooldown = 0;
  }

  load(zoneKey, spawnTile) {
    this.zoneKey = zoneKey;
    this.zone = ZONES[zoneKey];
    const baseMap = this.maps[zoneKey];
    this.map = {
      ...baseMap,
      tiles: baseMap.tiles.map(row => row.slice()),
      objects: baseMap.objects.map(o => ({ ...o })),
    };
    this.applyFlags();
    this.buildDecor();
    this.bakeGround();
    this.buildLights();
    this.initWeather();
    this.time = 0;
    this.transitionCooldown = .8;
    if (spawnTile) {
      this.spawn = { x: (spawnTile[0] + .5) * T, y: (spawnTile[1] + .5) * T };
    }
  }

  applyFlags() {
    const flags = this.game.state?.flags || {};
    for (const o of this.map.objects) {
      if (o.type === 'obstacle') {
        if (flags[`obstacle:${this.zoneKey}:${o.tx},${o.ty}`]) o.cleared = true;
      }
      if (o.type === 'chest' && flags[`chest:${o.id}`]) o.opened = true;
      if (o.type === 'relic' && flags[`relic:${o.id}`]) o.taken = true;
      if (o.type === 'gate' && (flags[`gate:${o.id}`] || (o.openFlag && flags[o.openFlag]))) o.open = true;
      if (o.type === 'rune' && flags[`rune:${o.id}`]) o.active = true;
      if (o.type === 'runeDisplay') o.active = !!flags[`rune_taken:${o.rune}`] || !!flags[`relic:relic_${o.rune.replace('runa_', 'runa_')}`];
    }
    // Generate obstacle objects from tiles
    for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
      const ch = this.map.tiles[y][x];
      if (ch === 'B' || ch === 'M' || ch === 'H') {
        const key = `obstacle:${this.zoneKey}:${x},${y}`;
        if (flags[key]) {
          this.map.tiles[y][x] = this.map.base;
        } else {
          this.map.objects.push({
            type: 'obstacle', id: `obs_${this.zoneKey}_${x}_${y}`, tx: x, ty: y,
            x: x + .5, y: y + .5, ability: ch === 'B' ? 'burn' : ch === 'M' ? 'freeze' : 'move',
            tile: ch, floor: this.map.base, solid: false,
          });
        }
      }
    }
  }

  buildDecor() {
    this.decor = [];
    const p = PAL[this.zoneKey] || PAL.aldea;
    for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
      const ch = this.map.tiles[y][x];
      const h = hash(x, y, 3);
      if (ch === 't') {
        this.decor.push({
          kind: 'tree', tx: x, ty: y, x: x + .5, y: y + .5,
          sortY: (y + 1) * T + 6, variant: Math.floor(h * 4), phase: h * 6.28,
          canopy: p.tree, canopy2: p.tree2,
        });
      } else if (ch === 'r') {
        this.decor.push({ kind: 'rock', tx: x, ty: y, x: x + .5, y: y + .5, sortY: (y + 1) * T, variant: Math.floor(h * 3), color: p.wall2 });
      } else if (ch === 'c') {
        this.decor.push({ kind: 'crystal', tx: x, ty: y, x: x + .5, y: y + .5, sortY: (y + 1) * T, color: p.water2 });
      } else if (ch === 'e') {
        this.decor.push({ kind: 'ember', tx: x, ty: y, x: x + .5, y: y + .5, sortY: 0, phase: h * 6.28 });
      }
    }
    // obstacle decor
    for (const o of this.map.objects) {
      if (o.type === 'obstacle' && !o.cleared) {
        this.decor.push({ kind: 'obstacle', obj: o, tx: o.tx, ty: o.ty, x: o.x, y: o.y, sortY: (o.ty + 1) * T });
      }
    }
    this.decor.sort((a, b) => a.sortY - b.sortY);
  }

  buildLights() {
    this.lights = [];
    const add = (x, y, r, color, intensity = .8) => this.lights.push({ x: x * T, y: y * T, r, color, intensity });
    for (const o of this.map.objects) {
      if (o.type === 'shrine') add(o.x, o.y, 150, '#ffd98a', .85);
      if (o.type === 'brazier') add(o.x, o.y, 130, '#ff9a55', .7);
      if (o.type === 'crystal') add(o.x, o.y, 120, o.color || '#7fb4ff', .6);
      if (o.type === 'altar') add(o.x, o.y, 200, '#ffd98a', .9);
      if (o.type === 'rune' && o.active) add(o.x, o.y, 150, '#ffd27a', .8);
      if (o.type === 'relic' && !o.taken) add(o.x, o.y, 110, '#ffd27a', .55);
      if (o.type === 'fountain') add(o.x, o.y, 110, '#6fe8d4', .5);
      if (o.type === 'gate' && !o.open) add(o.x, o.y, 80, '#a68bff', .4);
    }
    // ambient crystals from decor
    for (const d of this.decor) if (d.kind === 'crystal') add(d.x, d.y, 100, d.color || '#7fb4ff', .45);
  }

  initWeather() {
    const type = this.map.ambient?.type || 'dust';
    const count = type === 'stars' ? 70 : type === 'fireflies' ? 45 : 55;
    this.weather = [];
    for (let i = 0; i < count; i++) {
      this.weather.push(this._newParticle(type, true));
    }
  }

  _newParticle(type, initial = false) {
    const player = this.game.player;
    const cx = player ? player.x : (this.map.w * T) / 2;
    const cy = player ? player.y : (this.map.h * T) / 2;
    const w = (this.game.viewW || 1100) + 300, h = (this.game.viewH || 650) + 300;
    const x = cx + (Math.random() - .5) * w;
    const y = cy + (Math.random() - .5) * h;
    const base = { type, x, y, phase: Math.random() * 6.28, alpha: .4 + Math.random() * .5 };
    if (type === 'leaves') return { ...base, vx: 12 + Math.random() * 22, vy: 8 + Math.random() * 12, size: 2 + Math.random() * 3, rot: Math.random() * 6.28, spin: (Math.random() - .5) * 2 };
    if (type === 'fireflies') return { ...base, vx: (Math.random() - .5) * 12, vy: (Math.random() - .5) * 12, size: 1.2 + Math.random() * 1.8 };
    if (type === 'dust') return { ...base, vx: 2 + Math.random() * 6, vy: -2 - Math.random() * 5, size: 1 + Math.random() * 2 };
    if (type === 'embers') return { ...base, vx: (Math.random() - .5) * 10, vy: -16 - Math.random() * 26, size: 1 + Math.random() * 2.2 };
    return { ...base, vx: (Math.random() - .5) * 3, vy: (Math.random() - .5) * 3, size: .8 + Math.random() * 1.8 };
  }

  update(dt, player, camera) {
    this.time += dt;
    if (this.transitionCooldown > 0) this.transitionCooldown -= dt;
    for (let i = 0; i < this.weather.length; i++) {
      const p = this.weather[i];
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.phase += dt * 2;
      if (p.type === 'leaves') { p.rot += p.spin * dt; p.x += Math.sin(p.phase) * 8 * dt; }
      if (p.type === 'fireflies') { p.x += Math.sin(p.phase * 1.3) * 10 * dt; p.y += Math.cos(p.phase) * 10 * dt; }
      if (p.type === 'stars') { p.y += Math.sin(p.phase) * 2 * dt; }
      const margin = 220;
      if (p.x < camera.x - margin || p.x > camera.x + camera.w + margin || p.y < camera.y - margin || p.y > camera.y + camera.h + margin) {
        this.weather[i] = this._newParticle(p.type);
      }
    }
  }

  /* ---------------------------------------------------------------------- */
  /* Collision                                                              */
  /* ---------------------------------------------------------------------- */
  tileAt(tx, ty) {
    if (tx < 0 || ty < 0 || tx >= this.map.w || ty >= this.map.h) return 't';
    return this.map.tiles[ty][tx];
  }
  tileAtPx(px, py) {
    return this.tileAt(Math.floor(px / T), Math.floor(py / T));
  }

  isTileSolid(tx, ty, abilities = []) {
    const ch = this.tileAt(tx, ty);
    if (ch === 'w' || ch === 'W') return !abilities.includes('swim');
    if (ch === 'v') return !abilities.includes('fly');
    return SOLID.has(ch);
  }

  collidesCircle(x, y, r, abilities = []) {
    const x0 = Math.floor((x - r) / T), x1 = Math.floor((x + r) / T);
    const y0 = Math.floor((y - r) / T), y1 = Math.floor((y + r) / T);
    for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
      if (this.isTileSolid(tx, ty, abilities)) {
        // circle vs tile AABB
        const cx = Math.max(tx * T, Math.min(x, (tx + 1) * T));
        const cy = Math.max(ty * T, Math.min(y, (ty + 1) * T));
        if ((x - cx) ** 2 + (y - cy) ** 2 < r * r) return true;
      }
    }
    for (const o of this.map.objects) {
      if (!this._objectSolid(o)) continue;
      const ox = o.x * T, oy = o.y * T;
      const half = o.type === 'fountain' ? 30 : o.type === 'altar' ? 28 : o.type === 'shrine' ? 20 : 17;
      const cx = Math.max(ox - half, Math.min(x, ox + half));
      const cy = Math.max(oy - half, Math.min(y, oy + half));
      if ((x - cx) ** 2 + (y - cy) ** 2 < r * r) return true;
    }
    return false;
  }

  _objectSolid(o) {
    if (o.cleared || o.taken) return false;
    if (o.type === 'gate') return !o.open;
    if (o.type === 'chest') return true;
    if (o.type === 'relic') return !o.taken;
    if (o.type === 'obstacle') return false;
    return !!o.solid;
  }

  moveEntity(ent, dx, dy, abilities = []) {
    const r = ent.radius || 14;
    let movedX = false, movedY = false;
    if (dx) {
      if (!this.collidesCircle(ent.x + dx, ent.y, r, abilities)) { ent.x += dx; movedX = true; }
      else {
        // slide small steps
        const step = Math.sign(dx);
        for (let i = 1; i <= Math.abs(dx); i++) {
          if (!this.collidesCircle(ent.x + step, ent.y, r, abilities)) { ent.x += step; movedX = true; } else break;
        }
      }
    }
    if (dy) {
      if (!this.collidesCircle(ent.x, ent.y + dy, r, abilities)) { ent.y += dy; movedY = true; }
      else {
        const step = Math.sign(dy);
        for (let i = 1; i <= Math.abs(dy); i++) {
          if (!this.collidesCircle(ent.x, ent.y + step, r, abilities)) { ent.y += step; movedY = true; } else break;
        }
      }
    }
    ent.x = Math.max(T * .4, Math.min((this.map.w - .4) * T, ent.x));
    ent.y = Math.max(T * .4, Math.min((this.map.h - .4) * T, ent.y));
    return { movedX, movedY };
  }

  /* ---------------------------------------------------------------------- */
  /* Interaction                                                            */
  /* ---------------------------------------------------------------------- */
  findInteractable(px, py, radius = 74, abilities = []) {
    let best = null, bestD = Infinity;
    for (const o of this.map.objects) {
      if (o.taken || o.cleared) continue;
      if (o.type === 'chest' && o.opened) continue;
      if (o.type === 'obstacle' && !o.cleared) {
        // handled below with ability hint
      }
      if (o.type === 'gate' && o.open) continue;
      if (o.type === 'relic' && o.taken) continue;
      if (o.type === 'chest' && o.hidden && !abilities.includes(o.requires)) continue;
      if (o.type === 'npc' || o.type === 'chest' || o.type === 'shrine' || o.type === 'sign' || o.type === 'relic' || o.type === 'rune' || o.type === 'altar' || o.type === 'gate' || o.type === 'obstacle' || o.type === 'runeDisplay') {
        const d = Math.hypot(o.x * T - px, o.y * T - py);
        if (d < radius && d < bestD) { best = o; bestD = d; }
      }
    }
    return best;
  }

  getExitAt(px, py) {
    for (const e of this.map.exits) {
      const [x, y, w, h] = e.rect;
      if (px >= x * T && px <= (x + w) * T && py >= y * T && py <= (y + h) * T) return e;
    }
    return null;
  }

  clearObstacle(obj) {
    obj.cleared = true;
    const tx = obj.tx, ty = obj.ty;
    this.map.tiles[ty][tx] = obj.floor;
    this.decor = this.decor.filter(d => d.obj !== obj);
    this.paintTile(tx, ty, obj.floor);
    this.buildLights();
  }

  /* ---------------------------------------------------------------------- */
  /* Ground baking / rendering                                              */
  /* ---------------------------------------------------------------------- */
  bakeGround() {
    const c = document.createElement('canvas');
    c.width = this.map.w * T; c.height = this.map.h * T;
    const g = c.getContext('2d');
    for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
      this.paintTileTo(g, x, y, this.map.tiles[y][x]);
    }
    this.groundCanvas = c;
  }

  paintTile(tx, ty, ch) {
    if (!this.groundCanvas) return;
    const g = this.groundCanvas.getContext('2d');
    this.paintTileTo(g, tx, ty, ch);
  }

  paintTileTo(g, tx, ty, ch) {
    const p = PAL[this.zoneKey] || PAL.aldea;
    const x = tx * T, y = ty * T;
    const h = hash(tx, ty, 7);
    const h2 = hash(tx, ty, 11);
    switch (ch) {
      case 'g': case 'G': {
        g.fillStyle = h > .5 ? p.grass : p.grass2;
        g.fillRect(x, y, T, T);
        // blades
        g.strokeStyle = p.grass3; g.lineWidth = 1; g.globalAlpha = .45;
        for (let i = 0; i < 4; i++) {
          const bx = x + 6 + hash(tx, ty, i + 20) * 36;
          const by = y + 10 + hash(tx, ty, i + 30) * 30;
          g.beginPath(); g.moveTo(bx, by); g.lineTo(bx + 2, by - 4); g.stroke();
        }
        g.globalAlpha = 1;
        if (h2 > .86) {
          g.fillStyle = p.flower;
          g.globalAlpha = .8;
          for (let i = 0; i < 3; i++) {
            const fx = x + 12 + hash(tx, ty, i + 40) * 24;
            const fy = y + 12 + hash(tx, ty, i + 50) * 24;
            g.beginPath(); g.arc(fx, fy, 1.6, 0, 6.28); g.fill();
          }
          g.globalAlpha = 1;
        }
        break;
      }
      case ',': {
        g.fillStyle = p.tall; g.fillRect(x, y, T, T);
        g.strokeStyle = p.grass2; g.lineWidth = 1.4; g.globalAlpha = .8;
        for (let i = 0; i < 9; i++) {
          const bx = x + 5 + hash(tx, ty, i + 60) * 38;
          const by = y + 14 + hash(tx, ty, i + 70) * 28;
          g.beginPath(); g.moveTo(bx, by); g.quadraticCurveTo(bx + 3, by - 8, bx + 6, by - 13); g.stroke();
        }
        g.globalAlpha = 1;
        break;
      }
      case 'p': {
        g.fillStyle = h > .5 ? p.path : p.path2;
        g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(255,255,255,.06)';
        for (let i = 0; i < 5; i++) {
          const px = x + 4 + hash(tx, ty, i + 80) * 40;
          const py = y + 4 + hash(tx, ty, i + 90) * 40;
          g.beginPath(); g.arc(px, py, 1 + h2 * 1.5, 0, 6.28); g.fill();
        }
        break;
      }
      case 'P': {
        g.fillStyle = (tx + ty) % 2 ? p.plaza : p.plaza2;
        g.fillRect(x, y, T, T);
        g.strokeStyle = 'rgba(20,20,30,.25)'; g.lineWidth = 1;
        g.strokeRect(x + .5, y + .5, T - 1, T - 1);
        g.fillStyle = 'rgba(255,255,255,.05)';
        g.fillRect(x + 3, y + 3, T - 6, 2);
        break;
      }
      case 's': {
        g.fillStyle = (tx + ty) % 2 ? p.plaza : p.plaza2;
        g.fillRect(x, y, T, T);
        g.strokeStyle = 'rgba(10,12,22,.28)'; g.lineWidth = 1;
        g.strokeRect(x + .5, y + .5, T - 1, T - 1);
        if (h > .78) {
          g.strokeStyle = 'rgba(255,255,255,.09)'; g.beginPath();
          g.moveTo(x + 8, y + 10); g.lineTo(x + 16, y + 20); g.lineTo(x + 13, y + 30); g.stroke();
        }
        break;
      }
      case 'd': {
        g.fillStyle = h > .5 ? p.grass : p.grass2;
        g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(255,255,255,.04)';
        for (let i = 0; i < 3; i++) g.fillRect(x + 6 + h * 30, y + 8 + i * 13, 6, 2);
        break;
      }
      case 'S': {
        g.fillStyle = p.wall2; g.fillRect(x, y, T, T);
        g.fillStyle = p.wall; g.fillRect(x + 2, y + 2, T - 4, T - 8);
        g.strokeStyle = 'rgba(0,0,0,.3)'; g.lineWidth = 1;
        g.strokeRect(x + 2.5, y + 2.5, T - 5, T - 9);
        g.fillStyle = 'rgba(255,255,255,.1)'; g.fillRect(x + 4, y + 4, T - 8, 3);
        // bricks
        g.strokeStyle = 'rgba(0,0,0,.18)';
        g.beginPath(); g.moveTo(x + 16, y + 3); g.lineTo(x + 16, y + 26); g.stroke();
        g.beginPath(); g.moveTo(x + 32, y + 22); g.lineTo(x + 32, y + 43); g.stroke();
        break;
      }
      case 't': {
        g.fillStyle = p.grass; g.fillRect(x, y, T, T);
        break;
      }
      case 'r': {
        g.fillStyle = p.grass; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(0,0,0,.08)'; g.beginPath(); g.arc(x + T / 2, y + T / 2 + 5, 16, 0, 6.28); g.fill();
        break;
      }
      case 'w': case 'W': {
        g.fillStyle = p.water; g.fillRect(x, y, T, T);
        g.fillStyle = p.water2; g.globalAlpha = .25;
        for (let i = 0; i < 3; i++) {
          g.beginPath();
          g.ellipse(x + 8 + i * 15 + Math.sin(hash(tx, ty, i) * 6) * 3, y + 12 + i * 12, 8, 2.2, 0, 0, 6.28);
          g.fill();
        }
        g.globalAlpha = 1;
        break;
      }
      case 'b': {
        g.fillStyle = '#7b5a36'; g.fillRect(x, y, T, T);
        g.strokeStyle = '#5c4026'; g.lineWidth = 2;
        for (let i = 0; i < 5; i++) { g.beginPath(); g.moveTo(x + 4 + i * 10, y + 2); g.lineTo(x + 4 + i * 10, y + T - 2); g.stroke(); }
        g.fillStyle = 'rgba(255,255,255,.1)'; g.fillRect(x, y + 4, T, 2);
        break;
      }
      case 'l': {
        const lg = g.createLinearGradient(x, y, x, y + T);
        lg.addColorStop(0, '#d2572b'); lg.addColorStop(.5, '#ff8a3c'); lg.addColorStop(1, '#a8321c');
        g.fillStyle = lg; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(255,220,120,.35)';
        g.beginPath(); g.ellipse(x + 12 + h * 24, y + 14 + h2 * 20, 9, 3, 0, 0, 6.28); g.fill();
        break;
      }
      case 'v': {
        g.fillStyle = '#0a0818'; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(140,110,255,.25)';
        for (let i = 0; i < 3; i++) {
          g.beginPath(); g.arc(x + 8 + hash(tx, ty, i) * 32, y + 8 + hash(tx, ty, i + 5) * 32, 1 + h, 0, 6.28); g.fill();
        }
        break;
      }
      case 'i': {
        g.fillStyle = '#9fdcf0'; g.fillRect(x, y, T, T);
        g.strokeStyle = 'rgba(255,255,255,.5)'; g.lineWidth = 1;
        g.beginPath(); g.moveTo(x + 6, y + 10); g.lineTo(x + 20, y + 24); g.lineTo(x + 16, y + 38); g.stroke();
        break;
      }
      case 'u': {
        g.fillStyle = p.plaza2; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(180,180,200,.18)';
        for (let i = 0; i < 4; i++) g.fillRect(x + 6 + hash(tx, ty, i) * 30, y + 8 + hash(tx, ty, i + 3) * 28, 5 + h * 6, 3);
        break;
      }
      case 'e': {
        g.fillStyle = '#5b3a2e'; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(255,130,60,.22)';
        g.beginPath(); g.arc(x + T / 2, y + T / 2, 14 + h * 6, 0, 6.28); g.fill();
        g.fillStyle = 'rgba(255,210,120,.4)';
        g.beginPath(); g.arc(x + 16 + h * 16, y + 20 + h2 * 12, 1.6, 0, 6.28); g.fill();
        break;
      }
      case 'h': {
        g.fillStyle = p.hedge; g.fillRect(x, y, T, T);
        g.fillStyle = 'rgba(255,255,255,.08)';
        g.beginPath(); g.arc(x + 14, y + 16, 9, 0, 6.28); g.fill();
        g.beginPath(); g.arc(x + 32, y + 28, 8, 0, 6.28); g.fill();
        break;
      }
      case 'B': case 'M': case 'H': case 'R': case 'A': case 'c': {
        g.fillStyle = p.grass; g.fillRect(x, y, T, T);
        if (ch === 'R') {
          g.strokeStyle = 'rgba(242,209,136,.5)'; g.lineWidth = 1.6;
          g.beginPath(); g.arc(x + T / 2, y + T / 2, 15, 0, 6.28); g.stroke();
          g.beginPath(); g.arc(x + T / 2, y + T / 2, 9, 0, 6.28); g.stroke();
          for (let i = 0; i < 4; i++) {
            const a = i * Math.PI / 2 + .4;
            g.beginPath(); g.moveTo(x + T / 2 + Math.cos(a) * 8, y + T / 2 + Math.sin(a) * 8);
            g.lineTo(x + T / 2 + Math.cos(a) * 15, y + T / 2 + Math.sin(a) * 15); g.stroke();
          }
        }
        break;
      }
      default: {
        g.fillStyle = p.grass; g.fillRect(x, y, T, T);
      }
    }
  }

  /* ---------------------------------------------------------------------- */
  /* Drawables & object rendering                                           */
  /* ---------------------------------------------------------------------- */
  visible(x, y, camera, margin = 130) {
    return x > camera.x - margin && x < camera.x + camera.w + margin && y > camera.y - margin && y < camera.y + camera.h + margin;
  }

  getDrawables(camera, abilities = []) {
    const list = [];
    for (const d of this.decor) {
      if (!this.visible(d.x * T, d.y * T, camera)) continue;
      if (d.kind === 'obstacle') {
        list.push({ sortY: d.sortY, draw: ctx => this.drawObstacle(ctx, d.obj) });
      } else if (d.kind === 'tree') list.push({ sortY: d.sortY, draw: ctx => this.drawTree(ctx, d) });
      else if (d.kind === 'rock') list.push({ sortY: d.sortY, draw: ctx => this.drawRock(ctx, d) });
      else if (d.kind === 'crystal') list.push({ sortY: d.sortY, draw: ctx => this.drawCrystal(ctx, d) });
      else if (d.kind === 'ember') list.push({ sortY: 0, draw: ctx => this.drawEmber(ctx, d) });
    }
    for (const o of this.map.objects) {
      if (o.cleared || o.taken) continue;
      if (!this.visible(o.x * T, o.y * T, camera)) continue;
      if (o.type === 'obstacle') continue;
      if (o.type === 'chest' && o.hidden && !abilities.includes(o.requires)) continue;
      const sortY = (o.y + .5) * T;
      list.push({ sortY, draw: ctx => this.drawObject(ctx, o, abilities) });
    }
    list.sort((a, b) => a.sortY - b.sortY);
    return list;
  }

  drawTree(ctx, d) {
    const x = d.x * T, y = d.y * T;
    const sway = Math.sin(this.time * 1.2 + d.phase) * 2.2;
    ctx.save();
    // trunk
    ctx.fillStyle = '#4a3323';
    ctx.beginPath(); ctx.moveTo(x - 5, y + 10); ctx.lineTo(x - 3, y - 34); ctx.lineTo(x + 3, y - 34); ctx.lineTo(x + 5, y + 10); ctx.fill();
    // canopy layers
    const c1 = d.canopy, c2 = d.canopy2;
    const g = ctx.createRadialGradient(x - 10 + sway, y - 62, 4, x, y - 50, 38);
    g.addColorStop(0, lighten(c2, 22)); g.addColorStop(.55, c1); g.addColorStop(1, darken(c1, 24));
    ctx.fillStyle = g;
    const r = 30 + d.variant * 3;
    ctx.beginPath(); ctx.arc(x + sway, y - 58, r, 0, 6.28); ctx.fill();
    ctx.beginPath(); ctx.arc(x - r * .65 + sway * .6, y - 42, r * .7, 0, 6.28); ctx.fill();
    ctx.beginPath(); ctx.arc(x + r * .65 + sway * .6, y - 44, r * .66, 0, 6.28); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.12)';
    ctx.beginPath(); ctx.arc(x - r * .32 + sway, y - 66, r * .3, 0, 6.28); ctx.fill();
    ctx.restore();
  }

  drawRock(ctx, d) {
    const x = d.x * T, y = d.y * T;
    const s = 13 + d.variant * 3;
    ctx.save();
    ctx.fillStyle = d.color;
    ctx.beginPath();
    ctx.moveTo(x - s, y + 8); ctx.lineTo(x - s * .8, y - s * .6);
    ctx.lineTo(x - s * .1, y - s); ctx.lineTo(x + s * .8, y - s * .45);
    ctx.lineTo(x + s, y + 8); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.14)';
    ctx.beginPath(); ctx.moveTo(x - s * .6, y - s * .4); ctx.lineTo(x - s * .1, y - s); ctx.lineTo(x + s * .3, y - s * .5); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(0,0,0,.2)'; ctx.beginPath(); ctx.ellipse(x, y + 8, s, 4, 0, 0, 6.28); ctx.fill();
    ctx.restore();
  }

  drawCrystal(ctx, d) {
    const x = d.x * T, y = d.y * T;
    const color = d.color || '#7fb4ff';
    const pulse = .7 + Math.sin(this.time * 2 + d.x) * .2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(x, y - 22, 2, x, y - 22, 44);
    g.addColorStop(0, hexA(color, .32 * pulse)); g.addColorStop(1, 'transparent');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 22, 44, 0, 6.28); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.moveTo(x - 9, y + 8); ctx.lineTo(x - 5, y - 30); ctx.lineTo(x + 2, y - 44); ctx.lineTo(x + 9, y - 24); ctx.lineTo(x + 7, y + 8); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.45)';
    ctx.beginPath(); ctx.moveTo(x - 2, y + 2); ctx.lineTo(x + 1, y - 38); ctx.lineTo(x + 4, y - 26); ctx.lineTo(x + 2, y + 2); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  drawEmber(ctx, d) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const a = .25 + Math.sin(this.time * 3 + d.phase) * .12;
    ctx.fillStyle = `rgba(255,140,70,${a})`;
    ctx.beginPath(); ctx.ellipse(d.x * T, d.y * T, 18, 6, 0, 0, 6.28); ctx.fill();
    ctx.restore();
  }

  drawObstacle(ctx, o) {
    if (o.cleared) return;
    const x = o.x * T, y = o.y * T;
    ctx.save();
    if (o.tile === 'B') {
      ctx.fillStyle = '#2a3d26';
      for (let i = 0; i < 5; i++) {
        const a = i * 1.3;
        ctx.beginPath(); ctx.ellipse(x + Math.cos(a) * 14, y - 6 + Math.sin(a) * 8, 11, 7, a, 0, 6.28); ctx.fill();
      }
      ctx.strokeStyle = '#5c3a2a'; ctx.lineWidth = 2.2;
      for (let i = 0; i < 5; i++) {
        const a = i * 1.7;
        ctx.beginPath(); ctx.moveTo(x, y + 2); ctx.lineTo(x + Math.cos(a) * 22, y - 18 + Math.sin(a) * 12); ctx.stroke();
      }
      ctx.fillStyle = '#d95a5a';
      for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.arc(x + Math.cos(i * 2) * 15, y - 10 + Math.sin(i * 2) * 8, 2, 0, 6.28); ctx.fill(); }
    } else if (o.tile === 'M') {
      ctx.fillStyle = '#7fc8e8';
      ctx.beginPath(); ctx.moveTo(x - 12, y + 6); ctx.lineTo(x - 9, y - 34); ctx.lineTo(x, y - 46); ctx.lineTo(x + 9, y - 34); ctx.lineTo(x + 12, y + 6); ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.5)';
      ctx.beginPath(); ctx.moveTo(x - 3, y + 2); ctx.lineTo(x, y - 40); ctx.lineTo(x + 4, y - 28); ctx.lineTo(x + 3, y + 2); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(200,245,255,.7)'; ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.arc(x, y - 18, 20, 0, 6.28); ctx.stroke();
    } else {
      ctx.fillStyle = '#6b6577';
      ctx.fillRect(x - 19, y - 32, 38, 38);
      ctx.fillStyle = '#4b4658'; ctx.fillRect(x - 19, y - 32, 38, 6);
      ctx.strokeStyle = '#9b8fd0'; ctx.lineWidth = 1.4;
      ctx.strokeRect(x - 14, y - 26, 28, 26);
      ctx.beginPath(); ctx.arc(x, y - 13, 8, 0, 6.28); ctx.stroke();
    }
    ctx.restore();
  }

  drawObject(ctx, o, abilities = []) {
    const x = o.x * T, y = o.y * T;
    switch (o.type) {
      case 'npc': {
        drawHumanoid(ctx, {
          x, y: y + 8, time: this.time, facing: 'down', walk: 0,
          appearance: resolveAppearance(o.appearance),
          weapon: o.weaponKind ? { kind: o.weaponKind } : null,
          shield: o.weaponKind === 'spear',
          cape: o.id === 'elara' || o.id === 'roderic',
          aura: o.id === 'elara' ? 'rgba(166,139,255,.22)' : null,
        });
        break;
      }
      case 'chest': {
        const open = o.opened;
        ctx.save();
        if (!open) {
          ctx.globalCompositeOperation = 'lighter';
          const g = ctx.createRadialGradient(x, y - 10, 2, x, y - 10, 34);
          g.addColorStop(0, 'rgba(242,209,136,.25)'); g.addColorStop(1, 'transparent');
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 10, 34, 0, 6.28); ctx.fill();
          ctx.globalCompositeOperation = 'source-over';
        }
        ctx.fillStyle = open ? '#3d3227' : '#6b4a2c';
        ctx.fillRect(x - 18, y - 24, 36, 24);
        ctx.fillStyle = '#8d6438'; ctx.fillRect(x - 18, y - 24, 36, 5);
        ctx.strokeStyle = '#d9b15f'; ctx.lineWidth = 2; ctx.strokeRect(x - 17, y - 23, 34, 22);
        ctx.fillStyle = '#e8c979';
        ctx.fillRect(x - 3, y - 18, 6, 8);
        if (!open) {
          ctx.fillStyle = '#7a532f'; ctx.beginPath(); ctx.ellipse(x, y - 24, 18, 7, 0, Math.PI, 0); ctx.fill();
          ctx.strokeStyle = '#d9b15f'; ctx.stroke();
        } else {
          ctx.fillStyle = '#2a2118'; ctx.fillRect(x - 15, y - 23, 30, 6);
        }
        ctx.restore();
        break;
      }
      case 'shrine': {
        const pulse = .75 + Math.sin(this.time * 2) * .2;
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createRadialGradient(x, y - 34, 2, x, y - 34, 52);
        g.addColorStop(0, `rgba(255,225,150,${.3 * pulse})`); g.addColorStop(1, 'transparent');
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 34, 52, 0, 6.28); ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = '#6b6a7c'; ctx.beginPath(); ctx.ellipse(x, y + 6, 20, 6, 0, 0, 6.28); ctx.fill();
        ctx.fillStyle = '#4c4b5c'; ctx.fillRect(x - 6, y - 20, 12, 26);
        ctx.fillStyle = '#ffe9a8';
        ctx.beginPath(); ctx.moveTo(x, y - 50); ctx.lineTo(x + 8, y - 34); ctx.lineTo(x, y - 18); ctx.lineTo(x - 8, y - 34); ctx.closePath(); ctx.fill();
        ctx.strokeStyle = 'rgba(255,240,190,.6)'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.ellipse(x, y - 34, 18 + Math.sin(this.time * 2) * 3, 6, .2, 0, 6.28); ctx.stroke();
        ctx.restore();
        break;
      }
      case 'sign': {
        ctx.fillStyle = '#5b3e27'; ctx.fillRect(x - 3, y - 18, 6, 26);
        ctx.fillStyle = '#8a6238'; ctx.fillRect(x - 16, y - 34, 32, 18);
        ctx.strokeStyle = '#d2ac68'; ctx.lineWidth = 1; ctx.strokeRect(x - 15, y - 33, 30, 16);
        ctx.fillStyle = 'rgba(255,240,200,.4)';
        ctx.fillRect(x - 11, y - 29, 22, 1.5); ctx.fillRect(x - 11, y - 25, 16, 1.5);
        break;
      }
      case 'gate': {
        ctx.save();
        ctx.fillStyle = '#4a4658';
        ctx.fillRect(x - 24, y - 46, 8, 54); ctx.fillRect(x + 16, y - 46, 8, 54);
        ctx.fillStyle = '#6b667c';
        ctx.fillRect(x - 26, y - 50, 12, 8); ctx.fillRect(x + 14, y - 50, 12, 8);
        if (!o.open) {
          ctx.strokeStyle = '#a68bff'; ctx.globalAlpha = .8;
          for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(x - 14 + i * 9, y - 44); ctx.lineTo(x - 14 + i * 9, y + 4); ctx.stroke(); }
          ctx.globalAlpha = .25; ctx.fillStyle = '#a68bff'; ctx.fillRect(x - 16, y - 44, 32, 48);
        }
        ctx.restore();
        break;
      }
      case 'relic': {
        const bob = Math.sin(this.time * 2.2) * 4;
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createRadialGradient(x, y - 28 + bob, 2, x, y - 28 + bob, 46);
        g.addColorStop(0, 'rgba(255,230,150,.4)'); g.addColorStop(1, 'transparent');
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 28 + bob, 46, 0, 6.28); ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = '#4c4b5c'; ctx.fillRect(x - 7, y - 6, 14, 14);
        ctx.fillStyle = '#ffe9a8';
        ctx.beginPath(); ctx.moveTo(x, y - 44 + bob); ctx.lineTo(x + 10, y - 28 + bob); ctx.lineTo(x, y - 12 + bob); ctx.lineTo(x - 10, y - 28 + bob); ctx.closePath(); ctx.fill();
        ctx.strokeStyle = 'rgba(255,240,190,.7)'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.ellipse(x, y - 28 + bob, 17, 5, .3, 0, 6.28); ctx.stroke();
        ctx.restore();
        break;
      }
      case 'rune': {
        const active = o.active || false;
        const color = active ? '#ffd27a' : '#8f86b8';
        ctx.save();
        if (active) {
          ctx.globalCompositeOperation = 'lighter';
          const g = ctx.createRadialGradient(x, y - 4, 2, x, y - 4, 42);
          g.addColorStop(0, 'rgba(255,215,120,.35)'); g.addColorStop(1, 'transparent');
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 4, 42, 0, 6.28); ctx.fill();
        }
        ctx.strokeStyle = color; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(x, y + 4, 20, 7, 0, 0, 6.28); ctx.stroke();
        ctx.beginPath(); ctx.arc(x, y - 6, 10, 0, 6.28); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(x, y - 22); ctx.lineTo(x, y - 40); ctx.stroke();
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(x, y - 50); ctx.lineTo(x + 7, y - 40); ctx.lineTo(x, y - 30); ctx.lineTo(x - 7, y - 40); ctx.closePath(); ctx.fill();
        ctx.restore();
        break;
      }
      case 'runeDisplay': {
        const active = o.active;
        const color = active ? o.color : '#555a70';
        ctx.save();
        if (active) {
          ctx.globalCompositeOperation = 'lighter';
          const g = ctx.createRadialGradient(x, y - 20, 2, x, y - 20, 40);
          g.addColorStop(0, hexA(o.color, .35)); g.addColorStop(1, 'transparent');
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 20, 40, 0, 6.28); ctx.fill();
        }
        ctx.strokeStyle = color; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(x, y + 4, 18, 6, 0, 0, 6.28); ctx.stroke();
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(x, y - 38); ctx.lineTo(x + 8, y - 20); ctx.lineTo(x, y - 4); ctx.lineTo(x - 8, y - 20); ctx.closePath(); ctx.fill();
        ctx.restore();
        break;
      }
      case 'altar': {
        const pulse = .8 + Math.sin(this.time * 2.4) * .15;
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        const g = ctx.createRadialGradient(x, y - 30, 4, x, y - 30, 64);
        g.addColorStop(0, `rgba(255,235,170,${.35 * pulse})`); g.addColorStop(1, 'transparent');
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 30, 64, 0, 6.28); ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = '#5a5870'; ctx.fillRect(x - 20, y - 12, 40, 20);
        ctx.fillStyle = '#716f88'; ctx.fillRect(x - 16, y - 22, 32, 12);
        ctx.fillStyle = '#ffe9a8';
        ctx.beginPath(); ctx.arc(x, y - 32, 10, 0, 6.28); ctx.fill();
        ctx.strokeStyle = 'rgba(255,240,190,.7)'; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.ellipse(x, y - 32, 20 + Math.sin(this.time * 2) * 3, 7, .3, 0, 6.28); ctx.stroke();
        ctx.restore();
        break;
      }
      case 'fountain': {
        ctx.save();
        ctx.fillStyle = '#6c6a7b'; ctx.beginPath(); ctx.ellipse(x, y + 4, 32, 12, 0, 0, 6.28); ctx.fill();
        ctx.fillStyle = '#4e6f86'; ctx.beginPath(); ctx.ellipse(x, y - 1, 24, 8, 0, 0, 6.28); ctx.fill();
        ctx.fillStyle = '#7a7890'; ctx.fillRect(x - 5, y - 26, 10, 26);
        ctx.fillStyle = '#6fe8d4'; ctx.globalAlpha = .6;
        for (let i = 0; i < 4; i++) {
          const a = this.time * 1.5 + i * 1.57;
          ctx.beginPath(); ctx.arc(x + Math.cos(a) * 14, y - 18 + Math.sin(a * 2) * 6, 2, 0, 6.28); ctx.fill();
        }
        ctx.restore();
        break;
      }
      case 'brazier': {
        ctx.save();
        ctx.fillStyle = '#4a4658'; ctx.fillRect(x - 8, y - 8, 16, 14);
        ctx.fillStyle = '#ff9a55'; ctx.globalCompositeOperation = 'lighter';
        const f = 6 + Math.sin(this.time * 8 + x) * 2;
        ctx.beginPath(); ctx.ellipse(x, y - 16, 5, f, 0, 0, 6.28); ctx.fill();
        ctx.fillStyle = 'rgba(255,230,150,.8)'; ctx.beginPath(); ctx.ellipse(x, y - 14, 2.4, f * .55, 0, 0, 6.28); ctx.fill();
        ctx.restore();
        break;
      }
      case 'crystal': {
        this.drawCrystal(ctx, { x: o.x, y: o.y, color: o.color, variant: 1 });
        break;
      }
      default: break;
    }
  }

  /* ---------------------------------------------------------------------- */
  /* Weather / water                                                        */
  /* ---------------------------------------------------------------------- */
  renderWater(ctx, camera) {
    const x0 = Math.max(0, Math.floor(camera.x / T)), x1 = Math.min(this.map.w - 1, Math.ceil((camera.x + camera.w) / T));
    const y0 = Math.max(0, Math.floor(camera.y / T)), y1 = Math.min(this.map.h - 1, Math.ceil((camera.y + camera.h) / T));
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
      const ch = this.map.tiles[y][x];
      if (ch !== 'w' && ch !== 'W') continue;
      const t = this.time * 1.4 + x * .7 + y * .4;
      ctx.globalAlpha = .13 + Math.sin(t) * .05;
      ctx.strokeStyle = '#bff0ff'; ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(x * T + 6, y * T + 20 + Math.sin(t) * 3);
      ctx.quadraticCurveTo(x * T + 24, y * T + 16 + Math.sin(t + 1) * 3, x * T + 42, y * T + 21 + Math.sin(t + 2) * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  renderWeather(ctx, camera) {
    const type = this.map.ambient?.type;
    ctx.save();
    if (type === 'fireflies' || type === 'stars') ctx.globalCompositeOperation = 'lighter';
    for (const p of this.weather) {
      if (p.x < camera.x - 100 || p.x > camera.x + camera.w + 100 || p.y < camera.y - 100 || p.y > camera.y + camera.h + 100) continue;
      if (p.type === 'leaves') {
        ctx.save();
        ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        ctx.globalAlpha = p.alpha * .7;
        ctx.fillStyle = '#d9c27a';
        ctx.beginPath(); ctx.ellipse(0, 0, p.size * 1.6, p.size * .7, 0, 0, 6.28); ctx.fill();
        ctx.restore();
      } else if (p.type === 'fireflies') {
        const a = .35 + Math.sin(p.phase) * .3;
        ctx.globalAlpha = a;
        ctx.fillStyle = '#c8ff9a'; ctx.shadowColor = '#c8ff9a'; ctx.shadowBlur = 8;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, 6.28); ctx.fill();
        ctx.shadowBlur = 0;
      } else if (p.type === 'dust') {
        ctx.globalAlpha = p.alpha * .3;
        ctx.fillStyle = '#cfd0e8';
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, 6.28); ctx.fill();
      } else if (p.type === 'embers') {
        ctx.globalAlpha = p.alpha * .8;
        ctx.fillStyle = '#ff9a55'; ctx.shadowColor = '#ff7a45'; ctx.shadowBlur = 6;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, 6.28); ctx.fill();
        ctx.shadowBlur = 0;
      } else if (p.type === 'stars') {
        ctx.globalAlpha = .25 + Math.sin(p.phase) * .25;
        ctx.fillStyle = '#fff2c7';
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, 6.28); ctx.fill();
      }
    }
    ctx.restore();
  }
}

/* ==========================================================================
   ENTITIES — player, enemies, wild creatures, projectiles, hazards, particles.
   ========================================================================== */

import { ENEMIES, ITEMS, CREATURES, ELEMENTS, creatureXpForLevel } from './data.js';
import { T } from './world.js';
import { drawCreature } from './render.js';
import { audio } from './audio.js';

const DIRS = {
  down: { x: 0, y: 1 }, up: { x: 0, y: -1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 },
};
export function dirVec(facing) { return DIRS[facing] || DIRS.down; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function angleDiff(a, b) {
  let d = a - b;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return Math.abs(d);
}

/* -------------------------------------------------------------------------- */
/* Player                                                                     */
/* -------------------------------------------------------------------------- */
export class Player {
  constructor(game, state) {
    this.game = game;
    this.state = state;
    this.x = 19.5 * T; this.y = 16.5 * T;
    this.radius = 13;
    this.facing = 'down';
    this.walkPhase = 0;
    this.moving = false;
    this.attackTime = 0;
    this.attackDur = .3;
    this.attackCd = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.hitApplied = true;
    this.dodgeTime = 0;
    this.dodgeCd = 0;
    this.dodgeDir = { x: 0, y: 1 };
    this.invuln = 0;
    this.hurtTimer = 0;
    this.blocking = false;
    this.staminaDelay = 0;
    this.skillCd = {};
    this.attackBuff = 0;
    this.shieldTime = 0;
    this.shieldHp = 0;
    this.ghostCd = 0;
    this.creatureCd = 0;
    this.afterimages = [];
    this.manaDelay = 0;
    this.footstep = 0;
    this.buffPulse = 0;
  }

  get maxHp() { return this.game.derived.maxHp; }
  get maxMp() { return this.game.derived.maxMp; }
  get maxStamina() { return this.game.derived.maxStamina; }

  update(dt) {
    const g = this.game, input = g.input, st = this.state;
    const d = g.derived;
    // regen
    st.mp = Math.min(this.maxMp, st.mp + (2.2 + d.int * .06) * dt);
    if (this.staminaDelay > 0) this.staminaDelay -= dt;
    else st.stamina = Math.min(this.maxStamina, st.stamina + (18 + d.spd * .7) * dt);
    if (g.getActiveCreature()?.id === 'sylva') st.hp = Math.min(this.maxHp, st.hp + 1.1 * dt);
    st.hp = Math.min(st.hp, this.maxHp);
    st.mp = Math.min(st.mp, this.maxMp);

    // timers
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    if (this.comboTimer <= 0) this.combo = 0;
    this.dodgeCd = Math.max(0, this.dodgeCd - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.attackBuff = Math.max(0, this.attackBuff - dt);
    this.shieldTime = Math.max(0, this.shieldTime - dt);
    if (this.shieldTime <= 0) this.shieldHp = 0;
    this.ghostCd = Math.max(0, this.ghostCd - dt);
    this.buffPulse += dt;
    for (const k of Object.keys(this.skillCd)) this.skillCd[k] = Math.max(0, this.skillCd[k] - dt);

    // afterimages
    this.afterimages = this.afterimages.filter(a => (a.life -= dt) > 0);

    // menus / actions
    if (input.pressed('start')) { g.togglePause(); return; }
    if (input.pressed('select')) { g.toggleQuick(); return; }
    if (g.uiBlocking()) return;

    if (input.pressed('weapon')) g.cycleWeapon();
    if (input.pressed('creature')) g.cycleCreature();
    if (input.pressed('interact')) g.interact();
    if (input.pressed('skill')) this.castSkill();

    // dodge
    if (input.pressed('dodge') && this.dodgeCd <= 0 && this.dodgeTime <= 0) {
      if (st.stamina >= 22) {
        const ax = input.axis.x, ay = input.axis.y;
        this.dodgeDir = Math.hypot(ax, ay) > .2 ? { x: ax, y: ay } : dirVec(this.facing);
        this.dodgeTime = .23;
        this.dodgeCd = .68;
        this.invuln = .34;
        st.stamina -= 22;
        this.staminaDelay = .45;
        audio.sfx('dodge');
        g.particles.push(...Particle.burst(this.x, this.y - 12, 7, '#9fe4ff', { speed: 90, size: 2.4, life: .4 }));
        for (let i = 0; i < 3; i++) this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: .22 + i * .06, alpha: .22 });
      } else {
        g.toast('Sin resistencia para esquivar', 'bad');
      }
    }

    // block (hold dodge)
    const shield = g.getShield();
    this.blocking = !!shield && input.down('dodge') && this.dodgeTime <= 0 && st.stamina > 0 && !this.attackTime;
    if (this.blocking) {
      st.stamina = Math.max(0, st.stamina - 10 * dt);
      this.staminaDelay = .4;
      if (st.stamina <= 0) this.blocking = false;
    }

    // movement
    let mx = input.axis.x, my = input.axis.y;
    if (this.attackTime > 0) { mx *= .42; my *= .42; }
    if (this.blocking) { mx *= .35; my *= .35; }
    if (this.dodgeTime > 0) {
      this.dodgeTime -= dt;
      const sp = 520 * (0.8 + d.spd * .02);
      g.world.moveEntity(this, this.dodgeDir.x * sp * dt, this.dodgeDir.y * sp * dt, g.getAbilities());
      if (Math.random() < .5) this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: .18, alpha: .18 });
      this.moving = true;
      this.walkPhase += dt * 14;
    } else {
      const len = Math.hypot(mx, my);
      if (len > .08) {
        const base = 188 * (0.78 + d.spd * .032);
        const buff = this.attackBuff > 0 ? 1.35 : 1;
        const sp = base * buff * Math.min(1, len);
        const nx = mx / (len || 1), ny = my / (len || 1);
        g.world.moveEntity(this, nx * sp * dt, ny * sp * dt, g.getAbilities());
        this.moving = true;
        this.walkPhase += dt * 11;
        if (Math.abs(mx) > Math.abs(my)) this.facing = mx > 0 ? 'right' : 'left';
        else this.facing = my > 0 ? 'down' : 'up';
        this.footstep += dt;
        if (this.footstep > .32) { this.footstep = 0; audio.sfx('ui'); }
      } else {
        this.moving = false;
      }
    }

    // attack
    if (input.pressed('attack') && this.attackCd <= 0 && this.dodgeTime <= 0 && !this.blocking) this.startAttack();
    if (this.attackTime > 0) {
      this.attackTime += dt;
      const p = this.attackTime / this.attackDur;
      if (!this.hitApplied && p >= .36) {
        this.hitApplied = true;
        g.performPlayerAttack(this);
      }
      if (p >= 1) { this.attackTime = 0; this.hitApplied = true; }
    }

    // creature assist
    this.creatureCd = Math.max(0, this.creatureCd - dt);
    if (this.creatureCd <= 0) {
      const c = g.getActiveCreature();
      if (c) {
        const target = g.findNearestEnemy(this.x, this.y, 300);
        if (target) {
          g.creatureAssist(c, target);
          const charm = c.charm ? ITEMS[c.charm]?.charm : null;
          this.creatureCd = Math.max(1.2, 3.1 - c.level * .05) * (1 - (charm?.haste || 0));
        } else this.creatureCd = .5;
      }
    }

    // sync
    st.hp = Math.max(0, Math.min(st.hp, this.maxHp));
    st.mp = Math.max(0, Math.min(st.mp, this.maxMp));
    st.stamina = Math.max(0, Math.min(st.stamina, this.maxStamina));
    st.x = this.x; st.y = this.y;
  }

  startAttack() {
    const g = this.game;
    const weapon = g.getWeapon();
    const w = weapon?.weapon || { kind: 'fist', dmg: 6, speed: 1, range: 58, arc: 1.5, crit: 0 };
    this.combo = this.comboTimer > 0 ? (this.combo % 3) + 1 : 1;
    this.comboTimer = .85;
    this.attackDur = Math.max(.18, .34 / (w.speed || 1));
    this.attackTime = .0001;
    this.hitApplied = false;
    this.attackCd = this.attackDur + .06 / (w.speed || 1);
    this.attackAngle = Math.atan2(dirVec(this.facing).y, dirVec(this.facing).x);
    audio.sfx(w.kind === 'greatsword' ? 'heavy' : 'attack');
    this.game.shake(w.kind === 'greatsword' ? 2.5 : 1.2, .08);
  }

  castSkill() {
    const g = this.game;
    const id = this.state.skills.active;
    const sk = g.skillDef(id);
    if (!sk) return;
    if (!this.state.skills.unlocked.includes(id)) { g.toast('Habilidad no desbloqueada', 'bad'); return; }
    if ((this.skillCd[id] || 0) > 0) { g.toast('Habilidad en recarga', 'bad'); return; }
    if (this.state.mp < sk.cost) { g.toast('Maná insuficiente', 'bad'); return; }
    this.state.mp -= sk.cost;
    this.skillCd[id] = sk.cooldown;
    g.castSkill(id);
  }

  takeDamage(amount, sourceX = null, sourceY = null, opts = {}) {
    const g = this.game;
    if (this.invuln > 0 || this.dodgeTime > 0 || this.state.hp <= 0) return 0;
    let dmg = amount;
    if (this.blocking) {
      dmg *= .26;
      this.state.stamina = Math.max(0, this.state.stamina - 12);
      this.staminaDelay = .5;
      audio.sfx('block');
      g.particles.push(...Particle.burst(this.x, this.y - 20, 6, '#ffe6a0', { speed: 70, size: 2, life: .3 }));
    }
    dmg = Math.max(1, Math.round(dmg - g.derived.def * .55));
    if (this.shieldHp > 0) {
      const absorbed = Math.min(this.shieldHp, dmg);
      this.shieldHp -= absorbed;
      dmg -= absorbed;
      if (dmg <= 0) { g.addDamage(this.x, this.y - 44, 'Barrera', '#7fe8ff', 12); return 0; }
    }
    this.state.hp -= dmg;
    this.invuln = .62;
    this.hurtTimer = .34;
    g.addDamage(this.x, this.y - 48, dmg, '#ff7d9d', 18);
    g.particles.push(...Particle.burst(this.x, this.y - 20, 10, '#ff7d9d', { speed: 120, size: 2.6, life: .5 }));
    g.shake(6, .18);
    g.hitstop(.055);
    g.input.rumble(.55, .35, 130);
    audio.sfx('hit');
    if (sourceX != null) {
      const ang = Math.atan2(this.y - sourceY, this.x - sourceX);
      g.world.moveEntity(this, Math.cos(ang) * 13, Math.sin(ang) * 13, g.getAbilities());
    }
    if (this.state.hp <= 0) {
      this.state.hp = 0;
      g.playerDown();
    }
    return dmg;
  }

  heal(n) {
    const before = this.state.hp;
    this.state.hp = Math.min(this.maxHp, this.state.hp + n);
    return Math.round(this.state.hp - before);
  }

  render(ctx) {
    const g = this.game;
    const weapon = g.getWeapon();
    const shield = g.getShield();
    const p = this.attackTime > 0 ? clamp(this.attackTime / this.attackDur, 0, 1) : 0;
    const creature = g.getActiveCreature();
    const el = creature ? ELEMENTS[CREATURES[creature.id].element] : null;
    // afterimages
    for (const a of this.afterimages) {
      ctx.save(); ctx.globalAlpha = a.alpha;
      drawPlayerVisual(ctx, g, this, a.x, a.y, a.facing, 0, 0, false, false, 0, null, null, this.game.time);
      ctx.restore();
    }
    drawPlayerVisual(ctx, g, this, this.x, this.y, this.facing, this.moving ? this.walkPhase : 0, p, this.blocking, this.hurtTimer, this.dodgeTime, weapon, shield, this.game.time, el?.color, this.invuln > 0 && Math.floor(this.game.time * 20) % 2 === 0);
    if (this.shieldTime > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = `rgba(127,232,255,${.4 + Math.sin(this.game.time * 6) * .15})`;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(this.x, this.y - 24, 26, 34, 0, 0, 6.28); ctx.stroke();
      ctx.restore();
    }
  }
}

function drawPlayerVisual(ctx, g, player, x, y, facing, walk, attack, block, hurt, dodge, weapon, shield, time, aura, blink = false) {
  ctx.save();
  if (blink) ctx.globalAlpha = .55;
  const app = player.state.appearance;
  const weaponDef = weapon?.weapon ? weapon : null;
  // draw shield if equipped
  ctx.save();
  // render humanoid
  const { drawHumanoid, resolveAppearance } = g.renderRef;
  drawHumanoid(ctx, {
    x, y, time, facing, walk: walk ? Math.sin(walk) : 0,
    attack, block: block ? 1 : 0, hurt, dodge: dodge > 0 ? 1 : 0,
    appearance: resolveAppearance(app),
    weapon: weaponDef ? { ...weaponDef, celestial: weaponDef.celestial } : null,
    shield: !!shield,
    shieldColor: '#6b4a2c', shieldTrim: '#e2c47a',
    armor: !!g.state.equipment.armor,
    armorColor: g.state.equipment.armor === 'armadura_celestial' ? '#f2d188' : '#9aa6ba',
    accessory: !!g.state.equipment.accessory,
    accessoryColor: g.state.equipment.accessory === 'talisman_suerte' ? '#ffd27a' : '#6fe8d4',
    aura: aura || null,
    cape: true,
  });
  ctx.restore();
  ctx.restore();
}

/* -------------------------------------------------------------------------- */
/* Enemies                                                                    */
/* -------------------------------------------------------------------------- */
export class Enemy {
  constructor(game, type, tx, ty, level = 1, id = null) {
    this.game = game;
    this.type = type;
    this.def = ENEMIES[type];
    this.id = id || `${type}_${Math.random().toString(36).slice(2, 8)}`;
    this.level = level || this.def.level || 1;
    this.x = tx * T; this.y = ty * T;
    this.home = { x: this.x, y: this.y };
    this.radius = this.def.radius;
    this.maxHp = Math.round(this.def.hp * (1 + (this.level - this.def.level) * .18));
    this.hp = this.maxHp;
    this.atk = this.def.atk * (1 + (this.level - this.def.level) * .14);
    this.defense = this.def.def;
    this.speed = this.def.speed;
    this.xp = Math.round(this.def.xp * (1 + (this.level - 1) * .1));
    this.gold = this.def.gold;
    this.state = 'idle';
    this.stateTimer = 1 + Math.random() * 2;
    this.attackTimer = 1 + Math.random();
    this.telegraph = 0;
    this.telegraphTotal = 0;
    this.attackAnim = 0;
    this.hurt = 0;
    this.dead = false;
    this.deathTimer = 0;
    this.facing = 1;
    this.patrol = { x: this.x, y: this.y };
    this.phase = 1;
    this.phaseFlash = 0;
    this.knock = { x: 0, y: 0 };
    this.wanderAngle = Math.random() * 6.28;
    this.boss = !!this.def.boss;
    this.aggro = false;
    this.specialCd = 2.5;
    this.summoned = false;
  }

  get alive() { return !this.dead && this.hp > 0; }

  update(dt, player) {
    const g = this.game;
    if (this.dead) { this.deathTimer -= dt; return; }
    this.hurt = Math.max(0, this.hurt - dt);
    this.attackAnim = Math.max(0, this.attackAnim - dt);
    this.phaseFlash = Math.max(0, this.phaseFlash - dt);
    this.specialCd = Math.max(0, this.specialCd - dt);
    this.attackTimer = Math.max(0, this.attackTimer - dt);
    const dx = player.x - this.x, dy = player.y - this.y;
    const dist = Math.hypot(dx, dy);
    const aggroR = this.def.aggro;
    if (dist < aggroR || this.aggro || this.boss) this.aggro = true;
    if (this.aggro && dist > aggroR * 2.4 && !this.boss) this.aggro = false;

    // knockback
    if (Math.abs(this.knock.x) > 1 || Math.abs(this.knock.y) > 1) {
      g.world.moveEntity(this, this.knock.x * dt, this.knock.y * dt, []);
      this.knock.x *= .86; this.knock.y *= .86;
    }

    if (!this.aggro) {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) {
        this.stateTimer = 1.5 + Math.random() * 3;
        this.wanderAngle = Math.random() * 6.28;
        this.patrol = { x: this.home.x + Math.cos(this.wanderAngle) * 70, y: this.home.y + Math.sin(this.wanderAngle) * 70 };
      }
      const px = this.patrol.x - this.x, py = this.patrol.y - this.y;
      const pd = Math.hypot(px, py);
      if (pd > 10) {
        g.world.moveEntity(this, px / pd * this.speed * .32 * dt, py / pd * this.speed * .32 * dt, []);
        if (Math.abs(px) > 2) this.facing = px > 0 ? 1 : -1;
      }
      return;
    }

    if (this.type === 'wraith') { this.updateWraith(dt, player, dist, dx, dy); return; }
    if (this.boss) { this.updateBoss(dt, player, dist, dx, dy); return; }

    const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
    if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;

    if (this.telegraph > 0) {
      this.telegraph -= dt;
      if (this.telegraph <= 0) this.executeAttack(player, nx, ny);
      return;
    }

    if (this.state === 'attack') {
      this.stateTimer -= dt;
      if (this.state === 'attack' && this.type === 'wolf') {
        // lunge movement
        g.world.moveEntity(this, this.lungeX * dt, this.lungeY * dt, []);
        if (dist < this.radius + player.radius + 6) player.takeDamage(this.atk * .9, this.x, this.y);
      }
      if (this.stateTimer <= 0) { this.state = 'chase'; this.attackTimer = .8; }
      return;
    }

    if (dist < this.radius + player.radius + 4) {
      // contact damage
      if (this.attackTimer <= 0) {
        player.takeDamage(this.atk * .55, this.x, this.y);
        this.attackTimer = 1.1;
      }
      // slight separation
      g.world.moveEntity(this, -nx * 12 * dt, -ny * 12 * dt, []);
      return;
    }

    if (this.type === 'wolf' && dist < 120 && this.attackTimer <= 0) {
      this.state = 'telegraph'; this.telegraph = .38; this.telegraphTotal = .38;
      this.lungeX = nx * 430; this.lungeY = ny * 430;
      audio.sfx('dodge');
      return;
    }
    if (this.type === 'beetle' && dist < 115 && this.attackTimer <= 0) {
      this.state = 'telegraph'; this.telegraph = .55; this.telegraphTotal = .55;
      this.lungeX = nx * 300; this.lungeY = ny * 300;
      return;
    }

    const sp = this.speed * (this.type === 'blob' ? (1 + Math.sin(g.time * 4) * .12) : 1);
    g.world.moveEntity(this, nx * sp * dt, ny * sp * dt, []);
    // contact for blob
    if (this.type === 'blob' && dist < this.radius + player.radius + 8 && this.attackTimer <= 0) {
      player.takeDamage(this.atk * .6, this.x, this.y);
      this.attackTimer = 1.15;
    }
  }

  executeAttack(player, nx, ny) {
    const g = this.game;
    if (this.type === 'wolf' || this.type === 'beetle') {
      this.state = 'attack'; this.stateTimer = this.type === 'wolf' ? .22 : .3;
      this.attackAnim = .3;
      audio.sfx('attack');
      const d = Math.hypot(player.x - this.x, player.y - this.y);
      if (d < 80) player.takeDamage(this.atk, this.x, this.y);
    } else {
      this.attackTimer = 1;
    }
  }

  updateWraith(dt, player, dist, dx, dy) {
    const g = this.game;
    const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
    if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
    if (this.attackTimer <= 0 && dist < 340) {
      // fire orb
      const ang = Math.atan2(dy, dx);
      g.spawnEnemyProjectile(this.x, this.y - 20, Math.cos(ang) * 190, Math.sin(ang) * 190, this.atk * .9, '#a68bff', 7);
      audio.sfx('magic');
      this.attackTimer = 2.2;
      this.attackAnim = .4;
    }
    if (dist < 110) g.world.moveEntity(this, -nx * this.speed * dt, -ny * this.speed * dt, []);
    else if (dist > 220) g.world.moveEntity(this, nx * this.speed * .8 * dt, ny * this.speed * .8 * dt, []);
    else {
      const a = Math.atan2(dy, dx) + Math.PI / 2;
      g.world.moveEntity(this, Math.cos(a) * this.speed * .45 * dt, Math.sin(a) * this.speed * .45 * dt, []);
    }
    if (this.specialCd <= 0 && dist < 90) {
      // blink away
      const ang = Math.random() * 6.28;
      const tx = this.x + Math.cos(ang) * 160, ty = this.y + Math.sin(ang) * 160;
      if (!g.world.collidesCircle(tx, ty, this.radius, [])) {
        g.particles.push(...Particle.burst(this.x, this.y - 20, 12, '#a68bff', { speed: 120, size: 2.5, life: .5 }));
        this.x = tx; this.y = ty;
        g.particles.push(...Particle.burst(this.x, this.y - 20, 12, '#a68bff', { speed: 120, size: 2.5, life: .5 }));
        audio.sfx('magic');
      }
      this.specialCd = 5;
    }
  }

  updateBoss(dt, player, dist, dx, dy) {
    const g = this.game;
    const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
    if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
    const isFinal = this.type === 'boss';
    const thresholds = isFinal ? [.66, .33] : [.5];
    if (this.phase - 1 < thresholds.length && this.hp / this.maxHp <= thresholds[this.phase - 1]) {
      this.phase++;
      this.phaseFlash = 1.2;
      this.speed *= 1.12;
      this.atk *= 1.08;
      g.shake(12, .5);
      g.hitstop(.15);
      audio.sfx('boss');
      g.toast(isFinal ? `El Avatar entra en la Fase ${['I', 'II', 'III'][this.phase - 1]}` : 'El Guardián se enfurece', 'bad');
      g.particles.push(...Particle.burst(this.x, this.y - 30, 40, isFinal ? '#ff8ab5' : '#ff9caf', { speed: 220, size: 3.2, life: .9 }));
      // shockwave ring
      for (let i = 0; i < 12; i++) {
        const a = i / 12 * Math.PI * 2;
        g.spawnEnemyProjectile(this.x, this.y - 24, Math.cos(a) * 170, Math.sin(a) * 170, this.atk * .55, isFinal ? '#ff8ab5' : '#ff9caf', 6);
      }
    }

    if (this.telegraph > 0) {
      this.telegraph -= dt;
      if (this.telegraph <= 0) {
        this.executeBossAttack(player, nx, ny);
      }
      return;
    }

    if (this.state === 'dash') {
      this.stateTimer -= dt;
      g.world.moveEntity(this, this.dashX * dt, this.dashY * dt, []);
      if (dist < this.radius + player.radius + 8) player.takeDamage(this.atk * 1.1, this.x, this.y);
      if (this.stateTimer <= 0) { this.state = 'chase'; this.attackTimer = 1.4; }
      return;
    }

    if (dist < 100 && this.attackTimer <= 0) {
      this.state = 'telegraph'; this.telegraph = .42; this.telegraphTotal = .42;
      this.pending = 'slash';
      return;
    }
    if (this.attackTimer <= 0) {
      const roll = Math.random();
      if (isFinal) {
        if (this.phase >= 3 && roll < .35) { this.pending = 'dash'; this.telegraph = .35; this.telegraphTotal = .35; this.dashX = nx * 520; this.dashY = ny * 520; }
        else if (roll < .65) { this.pending = 'meteors'; this.telegraph = .55; this.telegraphTotal = .55; }
        else { this.pending = 'orbs'; this.telegraph = .45; this.telegraphTotal = .45; }
      } else {
        if (this.phase >= 2 && roll < .35) { this.pending = 'ring'; this.telegraph = .5; this.telegraphTotal = .5; }
        else if (roll < .7) { this.pending = 'orbs'; this.telegraph = .4; this.telegraphTotal = .4; }
        else { this.pending = 'shock'; this.telegraph = .45; this.telegraphTotal = .45; }
      }
      audio.sfx('boss');
      return;
    }

    const sp = this.speed;
    if (dist > 90) g.world.moveEntity(this, nx * sp * dt, ny * sp * dt, []);
    else if (dist < 65) g.world.moveEntity(this, -nx * sp * .5 * dt, -ny * sp * .5 * dt, []);
  }

  executeBossAttack(player, nx, ny) {
    const g = this.game;
    const isFinal = this.type === 'boss';
    const color = isFinal ? (this.phase >= 3 ? '#ff5c9d' : '#c58bff') : '#ff9caf';
    switch (this.pending) {
      case 'slash': {
        this.attackAnim = .4;
        audio.sfx('heavy');
        g.spawnSlash(this.x, this.y, Math.atan2(ny, nx), this.radius + 60, color, 1.8);
        if (Math.hypot(player.x - this.x, player.y - this.y) < this.radius + 70) player.takeDamage(this.atk * 1.25, this.x, this.y);
        this.attackTimer = 1.5;
        break;
      }
      case 'orbs': {
        const count = isFinal ? (this.phase >= 3 ? 9 : 6) : 5;
        for (let i = 0; i < count; i++) {
          const a = Math.atan2(ny, nx) + (i - (count - 1) / 2) * .28;
          g.spawnEnemyProjectile(this.x, this.y - 28, Math.cos(a) * 200, Math.sin(a) * 200, this.atk * .7, color, 7);
        }
        audio.sfx('magic');
        this.attackTimer = isFinal ? 2.1 : 2.8;
        break;
      }
      case 'shock': {
        for (let i = 0; i < 10; i++) {
          const a = i / 10 * Math.PI * 2;
          g.spawnEnemyProjectile(this.x, this.y - 20, Math.cos(a) * 150, Math.sin(a) * 150, this.atk * .6, color, 6);
        }
        this.attackTimer = 2.6;
        break;
      }
      case 'ring': {
        for (let i = 0; i < 16; i++) {
          const a = i / 16 * Math.PI * 2;
          g.spawnEnemyProjectile(this.x, this.y - 20, Math.cos(a) * 125, Math.sin(a) * 125, this.atk * .55, color, 5);
        }
        this.attackTimer = 2.2;
        break;
      }
      case 'meteors': {
        const count = this.phase >= 3 ? 5 : 3;
        for (let i = 0; i < count; i++) {
          const tx = player.x + (Math.random() - .5) * 260;
          const ty = player.y + (Math.random() - .5) * 200;
          g.addHazard(tx, ty, 62, this.atk * 1.1, color, .85, 2.4);
        }
        this.attackTimer = 3.2;
        break;
      }
      case 'dash': {
        this.state = 'dash'; this.stateTimer = .38;
        this.attackTimer = 2.4;
        break;
      }
    }
  }

  takeDamage(amount, opts = {}) {
    if (this.dead) return 0;
    const g = this.game;
    let dmg = amount;
    dmg = Math.max(1, Math.round(dmg - this.defense * .5));
    if (this.type === 'beetle' && !opts.heavy) dmg = Math.round(dmg * .82);
    if (this.boss) dmg = Math.round(dmg * .9);
    this.hp -= dmg;
    this.hurt = .18;
    this.aggro = true;
    g.addDamage(this.x, this.y - this.def.height - 8, dmg, opts.crit ? '#ffe066' : '#fff3d0', opts.crit ? 22 : 16);
    g.particles.push(...Particle.burst(this.x, this.y - this.def.height * .5, opts.crit ? 14 : 8, opts.color || '#ffe6a0', { speed: opts.crit ? 170 : 110, size: 2.2, life: .45 }));
    audio.sfx(opts.crit ? 'crit' : 'hit');
    g.hitstop(opts.crit ? .07 : .035);
    if (!this.boss && opts.knockback) {
      const ang = opts.angle ?? 0;
      this.knock.x = Math.cos(ang) * opts.knockback;
      this.knock.y = Math.sin(ang) * opts.knockback;
    }
    if (this.hp <= 0) this.die();
    return dmg;
  }

  die() {
    if (this.dead) return;
    this.dead = true;
    this.deathTimer = .9;
    this.hp = 0;
    const g = this.game;
    g.particles.push(...Particle.burst(this.x, this.y - this.def.height * .5, this.boss ? 60 : 20, this.def.colors[1], { speed: this.boss ? 240 : 150, size: 3, life: .9 }));
    g.shake(this.boss ? 16 : 4, this.boss ? .6 : .2);
    audio.sfx(this.boss ? 'boss' : 'hit');
    g.onEnemyDeath(this);
  }

  render(ctx) {
    const alpha = this.dead ? Math.max(0, this.deathTimer / .9) : 1;
    ctx.save();
    ctx.globalAlpha = alpha;
    if (this.phaseFlash > 0) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = `rgba(255,120,160,${this.phaseFlash * .3})`;
      ctx.beginPath(); ctx.arc(this.x, this.y - 30, 60, 0, 6.28); ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }
    const colors = this.type === 'boss' && this.phase >= 2
      ? (this.phase >= 3 ? ['#7a2c66', '#ff5c9d'] : ['#563078', '#c58bff'])
      : this.def.colors;
    const { drawEnemy } = this.game.renderRef;
    drawEnemy(ctx, this.def.kind, this.x, this.y, this.game.time, {
      colors, hurt: this.hurt, facing: this.facing,
      attack: this.attackAnim > 0 ? 1 - this.attackAnim / .4 : 0,
      scale: this.boss ? 1 : 1,
    });
    ctx.restore();
    if (!this.dead && (this.aggro || this.boss) && this.hp < this.maxHp) {
      const w = this.boss ? 64 : 36;
      const x = this.x - w / 2, y = this.y - this.def.height - (this.boss ? 36 : 18);
      ctx.save();
      ctx.fillStyle = 'rgba(4,7,14,.7)'; ctx.fillRect(x - 1, y - 1, w + 2, 6);
      ctx.fillStyle = this.boss ? '#ff5c7d' : '#ff8b9d';
      ctx.fillRect(x, y, w * clamp(this.hp / this.maxHp, 0, 1), 4);
      ctx.restore();
    }
    if (this.telegraph > 0) {
      const p = 1 - this.telegraph / Math.max(.01, this.telegraphTotal);
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = this.boss ? `rgba(255,100,150,${.3 + p * .4})` : `rgba(255,190,120,${.25 + p * .4})`;
      ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.arc(this.x, this.y - 10, (this.boss ? 55 : 26) + p * 26, 0, 6.28); ctx.stroke();
      ctx.restore();
    }
  }
}

/* -------------------------------------------------------------------------- */
/* Wild creatures                                                             */
/* -------------------------------------------------------------------------- */
export class WildCreature {
  constructor(game, spawn) {
    this.game = game;
    this.spawn = spawn;
    this.id = spawn.id;
    this.creature = spawn.creature;
    this.def = CREATURES[this.creature];
    this.level = spawn.level || 3;
    this.x = spawn.x * T; this.y = spawn.y * T;
    this.home = { x: this.x, y: this.y };
    this.maxHp = Math.round(this.def.wild.hp * (1 + (this.level - 3) * .12));
    this.hp = this.maxHp;
    this.radius = 15;
    this.provoked = false;
    this.hurt = 0;
    this.dead = false;
    this.deathTimer = 0;
    this.attackTimer = 2;
    this.phase = Math.random() * 6.28;
    this.captured = false;
    this.floatX = 0; this.floatY = 0;
    this.facing = 1;
  }

  get alive() { return !this.dead && !this.captured && this.hp > 0; }

  update(dt, player) {
    const g = this.game;
    if (this.dead) { this.deathTimer -= dt; return; }
    if (this.captured) return;
    this.hurt = Math.max(0, this.hurt - dt);
    this.attackTimer = Math.max(0, this.attackTimer - dt);
    this.phase += dt;
    const dx = player.x - this.x, dy = player.y - this.y;
    const dist = Math.hypot(dx, dy);
    if (this.provoked && dist < 300) {
      const nx = dx / (dist || 1), ny = dy / (dist || 1);
      if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
      if (dist > 170) g.world.moveEntity(this, nx * 50 * dt, ny * 50 * dt, []);
      else if (dist < 110) g.world.moveEntity(this, -nx * 42 * dt, -ny * 42 * dt, []);
      if (this.attackTimer <= 0) {
        const el = ELEMENTS[this.def.element];
        const ang = Math.atan2(dy, dx);
        g.spawnEnemyProjectile(this.x, this.y - 18, Math.cos(ang) * 165, Math.sin(ang) * 165, 5 + this.level * 1.2, el.color, 5.5);
        this.attackTimer = 2.4;
        audio.sfx('magic');
      }
    } else {
      const a = this.phase * .6;
      this.floatX = Math.cos(a) * 12;
      this.floatY = Math.sin(a * 1.3) * 8;
    }
  }

  takeDamage(amount, opts = {}) {
    if (this.dead || this.captured) return 0;
    const g = this.game;
    const dmg = Math.max(1, Math.round(amount * .8));
    this.hp -= dmg;
    this.hurt = .18;
    this.provoked = true;
    g.addDamage(this.x, this.y - 46, dmg, '#ffe066', 16);
    g.particles.push(...Particle.burst(this.x, this.y - 20, 8, this.def.colors[1], { speed: 100, size: 2, life: .4 }));
    audio.sfx('hit');
    if (this.hp <= 0) {
      this.hp = 0;
      this.dead = true;
      this.deathTimer = .8;
      g.particles.push(...Particle.burst(this.x, this.y - 20, 24, this.def.colors[1], { speed: 170, size: 2.6, life: .7 }));
      g.onWildDefeated(this);
    }
    return dmg;
  }

  render(ctx) {
    if (this.dead && this.deathTimer <= 0) return;
    const alpha = this.dead ? Math.max(0, this.deathTimer / .8) : 1;
    const bob = this.provoked ? 0 : Math.sin(this.game.time * 2 + this.phase) * 4;
    ctx.save();
    ctx.globalAlpha = alpha;
    drawCreature(ctx, this.creature, this.x + this.floatX, this.y + this.floatY + bob, this.game.time, .78, { alpha, flip: this.facing < 0 });
    if (!this.dead && this.hp < this.maxHp) {
      const w = 34;
      ctx.fillStyle = 'rgba(4,7,14,.7)'; ctx.fillRect(this.x - w / 2 - 1, this.y - 58, w + 2, 5);
      ctx.fillStyle = this.def.colors[0]; ctx.fillRect(this.x - w / 2, this.y - 57, w * clamp(this.hp / this.maxHp, 0, 1), 3);
    }
    if (!this.dead && this.hp / this.maxHp <= .4 && !this.provoked) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = 'rgba(255,225,130,.55)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(this.x, this.y - 22, 24 + Math.sin(this.game.time * 4) * 3, 0, 6.28); ctx.stroke();
    }
    ctx.restore();
  }
}

/* -------------------------------------------------------------------------- */
/* Projectiles                                                                */
/* -------------------------------------------------------------------------- */
export class Projectile {
  constructor(game, opts) {
    this.game = game;
    Object.assign(this, {
      x: 0, y: 0, vx: 0, vy: 0, radius: 5, damage: 10, owner: 'player',
      color: '#ffe6a0', life: 1.4, maxLife: 1.4, pierce: 0, homing: 0,
      element: null, kind: 'orb', knockback: 0, heavy: false,
    }, opts);
    this.trail = [];
    this.hit = new Set();
  }

  update(dt) {
    const g = this.game;
    this.life -= dt;
    this.x += this.vx * dt; this.y += this.vy * dt;
    this.trail.push({ x: this.x, y: this.y, life: .22 });
    this.trail = this.trail.filter(t => (t.life -= dt) > 0);
    if (this.life <= 0) return false;
    if (g.world.collidesCircle(this.x, this.y, this.radius, ['fly'])) {
      g.particles.push(...Particle.burst(this.x, this.y, 5, this.color, { speed: 70, size: 1.8, life: .3 }));
      return false;
    }
    if (this.owner === 'player') {
      for (const e of g.enemies) {
        if (e.dead || this.hit.has(e)) continue;
        if (Math.hypot(e.x - this.x, e.y - this.y) < e.radius + this.radius) {
          e.takeDamage(this.damage, { crit: Math.random() < .1, knockback: this.knockback, angle: Math.atan2(this.vy, this.vx), heavy: this.heavy });
          this.hit.add(e);
          if (this.pierce-- <= 0) return false;
        }
      }
      for (const w of g.wilds) {
        if (!w.alive || this.hit.has(w)) continue;
        if (Math.hypot(w.x - this.x, w.y - this.y) < w.radius + this.radius) {
          w.takeDamage(this.damage);
          this.hit.add(w);
          if (this.pierce-- <= 0) return false;
        }
      }
    } else {
      const p = g.player;
      if (Math.hypot(p.x - this.x, p.y - this.y) < p.radius + this.radius + 2) {
        p.takeDamage(this.damage, this.x, this.y);
        return false;
      }
    }
    return true;
  }

  render(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const t of this.trail) {
      ctx.globalAlpha = t.life * 2.2;
      ctx.fillStyle = this.color;
      ctx.beginPath(); ctx.arc(t.x, t.y, this.radius * .55, 0, 6.28); ctx.fill();
    }
    ctx.globalAlpha = .9;
    ctx.shadowColor = this.color; ctx.shadowBlur = 12;
    ctx.fillStyle = this.color;
    ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, 6.28); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.globalAlpha = .8;
    ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * .38, 0, 6.28); ctx.fill();
    ctx.restore();
  }
}

/* -------------------------------------------------------------------------- */
/* Hazards (boss AoE)                                                         */
/* -------------------------------------------------------------------------- */
export class Hazard {
  constructor(game, x, y, radius, damage, color, warn = .8, active = 2) {
    this.game = game;
    this.x = x; this.y = y; this.radius = radius; this.damage = damage;
    this.color = color; this.warn = warn; this.active = active;
    this.t = 0; this.done = false; this.hitCd = 0;
  }
  update(dt) {
    this.t += dt;
    this.hitCd = Math.max(0, this.hitCd - dt);
    if (this.t > this.warn + this.active) { this.done = true; return; }
    if (this.t >= this.warn && this.hitCd <= 0) {
      const p = this.game.player;
      if (Math.hypot(p.x - this.x, p.y - this.y) < this.radius) {
        p.takeDamage(this.damage, this.x, this.y);
        this.hitCd = .7;
      }
    }
    if (this.t >= this.warn && this.t < this.warn + .15) {
      this.game.shake(4, .15);
      this.game.particles.push(...Particle.burst(this.x, this.y, 20, this.color, { speed: 160, size: 2.6, life: .5 }));
      audio.sfx('heavy');
    }
  }
  render(ctx) {
    ctx.save();
    if (this.t < this.warn) {
      const p = this.t / this.warn;
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = this.color; ctx.globalAlpha = .4 + p * .4; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * (1.2 - p * .2), 0, 6.28); ctx.stroke();
      ctx.fillStyle = this.color; ctx.globalAlpha = .08 + p * .12;
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * p, 0, 6.28); ctx.fill();
    } else {
      const p = (this.t - this.warn) / this.active;
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = this.color; ctx.globalAlpha = Math.max(0, .35 * (1 - p));
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, 6.28); ctx.fill();
      ctx.strokeStyle = '#fff'; ctx.globalAlpha = .5 * (1 - p); ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * (1 + p * .2), 0, 6.28); ctx.stroke();
    }
    ctx.restore();
  }
}

/* -------------------------------------------------------------------------- */
/* Particles & damage numbers                                                 */
/* -------------------------------------------------------------------------- */
export class Particle {
  constructor(opts) { Object.assign(this, { x: 0, y: 0, vx: 0, vy: 0, life: .5, maxLife: .5, size: 2, color: '#fff', gravity: 0, drag: .96, glow: true, kind: 'dot' }, opts); this.maxLife = this.life; }
  static burst(x, y, count, color, opts = {}) {
    const arr = [];
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2, sp = (opts.speed || 100) * (.3 + Math.random() * .7);
      arr.push(new Particle({
        x: x + (Math.random() - .5) * 8, y: y + (Math.random() - .5) * 8,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - (opts.up || 0),
        life: (opts.life || .5) * (.6 + Math.random() * .6),
        size: (opts.size || 2) * (.6 + Math.random() * .8),
        color, gravity: opts.gravity ?? 80, glow: opts.glow !== false,
      }));
    }
    return arr;
  }
  update(dt) {
    this.life -= dt;
    this.vy += this.gravity * dt;
    this.vx *= this.drag; this.vy *= this.drag;
    this.x += this.vx * dt; this.y += this.vy * dt;
  }
  render(ctx) {
    const a = Math.max(0, this.life / this.maxLife);
    ctx.save();
    if (this.glow) ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = a;
    ctx.fillStyle = this.color;
    ctx.beginPath(); ctx.arc(this.x, this.y, this.size * (.4 + a * .6), 0, 6.28); ctx.fill();
    ctx.restore();
  }
}

export class DamageNumber {
  constructor(x, y, text, color = '#fff', size = 16) {
    this.x = x + (Math.random() - .5) * 10; this.y = y; this.text = String(text); this.color = color; this.size = size;
    this.life = .85; this.maxLife = .85; this.vy = -52;
  }
  update(dt) { this.life -= dt; this.y += this.vy * dt; this.vy *= .94; }
  render(ctx) {
    const a = Math.max(0, this.life / this.maxLife);
    ctx.save();
    ctx.globalAlpha = Math.min(1, a * 2.5);
    ctx.font = `700 ${this.size}px ${getComputedStyle(document.body).fontFamily}`;
    ctx.textAlign = 'center';
    ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(5,8,16,.8)';
    ctx.strokeText(this.text, this.x, this.y);
    ctx.fillStyle = this.color;
    ctx.fillText(this.text, this.x, this.y);
    ctx.restore();
  }
}

