  /* ---------------------------------------------------------------------- */
  /* Shop                                                                   */
  /* ---------------------------------------------------------------------- */
  showShop(kind = 'mira') {
    this.shop = { kind, tab: 'buy' };
    this.renderShop();
    this.syncChrome();
