295:   itemStatsHtml(d) {
296:     const rows = [];
297:     if (d.weapon) {
298:       rows.push(['Daño', d.weapon.dmg]);
299:       rows.push(['Velocidad', `${d.weapon.speed.toFixed(2)}×`]);
300:       rows.push(['Alcance', d.weapon.projectile ? 'A distancia' : `${d.weapon.range} px`]);
301:       rows.push(['Crítico', `${Math.round(d.weapon.crit * 100)}%`]);
302:     }
303:     if (d.stats) for (const [k, v] of Object.entries(d.stats)) {
304:       const label = { hp: 'Vida', mp: 'Maná', str: 'Fuerza', def: 'Defensa', spd: 'Velocidad', int: 'Inteligencia', luck: 'Suerte' }[k] || k;
305:       rows.push([label, `${v > 0 ? '+' : ''}${v}`]);
306:     }
307:     if (d.charm) for (const [k, v] of Object.entries(d.charm)) {
308:       const label = { atk: 'Ataque de criatura', hp: 'Vida de criatura', haste: 'Celeridad de asistencia' }[k] || k;
309:       rows.push([label, k === 'haste' ? `+${Math.round(v * 100)}%` : `+${v}`]);
310:     }
311:     if (d.effect) for (const [k, v] of Object.entries(d.effect)) {
312:       const label = { heal: 'Vida', mana: 'Maná', stamina: 'Resistencia', creatureXp: 'XP de criatura', bond: 'Vínculo', capture: 'Captura' }[k] || k;
313:       rows.push([label, k === 'capture' ? `+${Math.round(v * 100)}%` : `+${v}`]);
314:     }
315:     if (!rows.length) return '';
316:     return `<div>${rows.map(([a, b]) => `<div class="stat-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
317:   }
