322:     if (d.type === 'charm') return `<button class="btn ghost" data-action="open-tab" data-tab="creatures">${icon('creature')} Equipar en criatura</button>`;
323:     if (d.type === 'key') return `<div class="empty-note" style="padding:10px">Reliquia de la historia. No se puede usar desde la bolsa.</div>`;
324:     return `<div class="empty-note" style="padding:10px">Material de fabricación. Llévalo al yunque de Torin.</div>`;
325:   }
