469:           <p>${stage?.text || def.desc}</p>
470:           <div class="quest-progress"><div class="track"><i style="width:${done ? 100 : Math.round(prog / count * 100)}%"></i></div><span>${done ? 'Completada' : `${prog} / ${count}`}</span></div>
