102:     if (input.pressed('dodge') && this.dodgeCd <= 0 && this.dodgeTime <= 0) {
103:       if (st.stamina >= 22) {
104:         const ax = input.axis.x, ay = input.axis.y;
105:         this.dodgeDir = Math.hypot(ax, ay) > .2 ? { x: ax, y: ay } : dirVec(this.facing);
106:         this.dodgeTime = .23;
107:         this.dodgeCd = .68;
108:         this.invuln = .34;
109:         st.stamina -= 22;
110:         this.staminaDelay = .45;
111:         audio.sfx('dodge');
112:         g.particles.push(...Particle.burst(this.x, this.y - 12, 7, '#9fe4ff', { speed: 90, size: 2.4, life: .4 }));
113:         for (let i = 0; i < 3; i++) this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: .22 + i * .06, alpha: .22 });
114:       } else {
115:         g.toast('Sin resistencia para esquivar', 'bad');
116:       }
117:     }
118: 
119:     // block (hold dodge)
120:     const shield = g.getShield();
121:     this.blocking = !!shield && input.down('dodge') && this.dodgeTime <= 0 && st.stamina > 0 && !this.attackTime;
122:     if (this.blocking) {
123:       st.stamina = Math.max(0, st.stamina - 10 * dt);
124:       this.staminaDelay = .4;
125:       if (st.stamina <= 0) this.blocking = false;
126:     }
127: 
128:     // movement
129:     let mx = input.axis.x, my = input.axis.y;
130:     if (this.attackTime > 0) { mx *= .42; my *= .42; }
131:     if (this.blocking) { mx *= .35; my *= .35; }
132:     if (this.dodgeTime > 0) {
133:       this.dodgeTime -= dt;
134:       const sp = 520 * (0.8 + d.spd * .02);
135:       g.world.moveEntity(this, this.dodgeDir.x * sp * dt, this.dodgeDir.y * sp * dt, g.getAbilities());
136:       if (Math.random() < .5) this.afterimages.push({ x: this.x, y: this.y, facing: this.facing, life: .18, alpha: .18 });
137:       this.moving = true;
138:       this.walkPhase += dt * 14;
139:     } else {
140:       const len = Math.hypot(mx, my);
141:       if (len > .08) {
142:         const base = 188 * (0.78 + d.spd * .032);
143:         const buff = this.attackBuff > 0 ? 1.35 : 1;
144:         const sp = base * buff * Math.min(1, len);
145:         const nx = mx / (len || 1), ny = my / (len || 1);
146:         g.world.moveEntity(this, nx * sp * dt, ny * sp * dt, g.getAbilities());
147:         this.moving = true;
148:         this.walkPhase += dt * 11;
149:         if (Math.abs(mx) > Math.abs(my)) this.facing = mx > 0 ? 'right' : 'left';
150:         else this.facing = my > 0 ? 'down' : 'up';
151:         this.footstep += dt;
152:         if (this.footstep > .32) { this.footstep = 0; audio.sfx('ui'); }
153:       } else {
154:         this.moving = false;
155:       }
156:     }
157: 
158:     // attack
159:     if (input.pressed('attack') && this.attackCd <= 0 && this.dodgeTime <= 0 && !this.blocking) this.startAttack();
160:     if (this.attackTime > 0) {
161:       this.attackTime += dt;
162:       const p = this.attackTime / this.attackDur;
163:       if (!this.hitApplied && p >= .36) {
164:         this.hitApplied = true;
165:         g.performPlayerAttack(this);
166:       }
167:       if (p >= 1) { this.attackTime = 0; this.hitApplied = true; }
168:     }
169: 
170:     // creature assist
171:     this.creatureCd = Math.max(0, this.creatureCd - dt);
172:     if (this.creatureCd <= 0) {
173:       const c = g.getActiveCreature();
174:       if (c) {
175:         const target = g.findNearestEnemy(this.x, this.y, 300);
176:         if (target) {
177:           g.creatureAssist(c, target);
178:           const charm = c.charm ? ITEMS[c.charm]?.charm : null;
179:           this.creatureCd = Math.max(1.2, 3.1 - c.level * .05) * (1 - (charm?.haste || 0));
180:         } else this.creatureCd = .5;
181:       }
182:     }
183: 
184:     // sync
185:     st.hp = Math.max(0, Math.min(st.hp, this.maxHp));
186:     st.mp = Math.max(0, Math.min(st.mp, this.maxMp));
187:     st.stamina = Math.max(0, Math.min(st.stamina, this.maxStamina));
188:     st.x = this.x; st.y = this.y;
189:   }
190: 
191:   startAttack() {
192:     const g = this.game;
193:     const weapon = g.getWeapon();
194:     const w = weapon?.weapon || { kind: 'fist', dmg: 6, speed: 1, range: 58, arc: 1.5, crit: 0 };
195:     this.combo = this.comboTimer > 0 ? (this.combo % 3) + 1 : 1;
196:     this.comboTimer = .85;
197:     this.attackDur = Math.max(.18, .34 / (w.speed || 1));
198:     this.attackTime = .0001;
199:     this.hitApplied = false;
200:     this.attackCd = this.attackDur + .06 / (w.speed || 1);
201:     this.attackAngle = Math.atan2(dirVec(this.facing).y, dirVec(this.facing).x);
202:     audio.sfx(w.kind === 'greatsword' ? 'heavy' : 'attack');
203:     this.game.shake(w.kind === 'greatsword' ? 2.5 : 1.2, .08);
204:   }
205: 
206:   castSkill() {
207:     const g = this.game;
208:     const id = this.state.skills.active;
209:     const sk = g.skillDef(id);
210:     if (!sk) return;
211:     if (!this.state.skills.unlocked.includes(id)) { g.toast('Habilidad no desbloqueada', 'bad'); return; }
212:     if ((this.skillCd[id] || 0) > 0) { g.toast('Habilidad en recarga', 'bad'); return; }
213:     if (this.state.mp < sk.cost) { g.toast('Maná insuficiente', 'bad'); return; }
214:     this.state.mp -= sk.cost;
215:     this.skillCd[id] = sk.cooldown;
216:     g.castSkill(id);
217:   }
218: 
219:   takeDamage(amount, sourceX = null, sourceY = null, opts = {}) {
220:     const g = this.game;
221:     if (this.invuln > 0 || this.dodgeTime > 0 || this.state.hp <= 0) return 0;
222:     let dmg = amount;
223:     if (this.blocking) {
224:       dmg *= .26;
225:       this.state.stamina = Math.max(0, this.state.stamina - 12);
226:       this.staminaDelay = .5;
227:       audio.sfx('block');
228:       g.particles.push(...Particle.burst(this.x, this.y - 20, 6, '#ffe6a0', { speed: 70, size: 2, life: .3 }));
229:     }
230:     dmg = Math.max(1, Math.round(dmg - g.derived.def * .55));
231:     if (this.shieldHp > 0) {
232:       const absorbed = Math.min(this.shieldHp, dmg);
233:       this.shieldHp -= absorbed;
234:       dmg -= absorbed;
235:       if (dmg <= 0) { g.addDamage(this.x, this.y - 44, 'Barrera', '#7fe8ff', 12); return 0; }
236:     }
237:     this.state.hp -= dmg;
238:     this.invuln = .62;
239:     this.hurtTimer = .34;
240:     g.addDamage(this.x, this.y - 48, dmg, '#ff7d9d', 18);
241:     g.particles.push(...Particle.burst(this.x, this.y - 20, 10, '#ff7d9d', { speed: 120, size: 2.6, life: .5 }));
242:     g.shake(6, .18);
243:     g.hitstop(.055);
244:     g.input.rumble(.55, .35, 130);
245:     audio.sfx('hit');
246:     if (sourceX != null) {
247:       const ang = Math.atan2(this.y - sourceY, this.x - sourceX);
248:       g.world.moveEntity(this, Math.cos(ang) * 13, Math.sin(ang) * 13, g.getAbilities());
249:     }
250:     if (this.state.hp <= 0) {
251:       this.state.hp = 0;
252:       g.playerDown();
253:     }
254:     return dmg;
255:   }
256: 
257:   heal(n) {
258:     const before = this.state.hp;
259:     this.state.hp = Math.min(this.maxHp, this.state.hp + n);
260:     return Math.round(this.state.hp - before);
261:   }
262: 
263:   render(ctx) {
264:     const g = this.game;
265:     const weapon = g.getWeapon();
266:     const shield = g.getShield();
267:     const p = this.attackTime > 0 ? clamp(this.attackTime / this.attackDur, 0, 1) : 0;
268:     const creature = g.getActiveCreature();
269:     const el = creature ? ELEMENTS[CREATURES[creature.id].element] : null;
270:     // afterimages
271:     for (const a of this.afterimages) {
272:       ctx.save(); ctx.globalAlpha = a.alpha;
273:       drawPlayerVisual(ctx, g, this, a.x, a.y, a.facing, 0, 0, false, false, 0, null, null, this.game.time);
274:       ctx.restore();
275:     }
276:     drawPlayerVisual(ctx, g, this, this.x, this.y, this.facing, this.moving ? this.walkPhase : 0, p, this.blocking, this.hurtTimer, this.dodgeTime, weapon, shield, this.game.time, el?.color, this.invuln > 0 && Math.floor(this.game.time * 20) % 2 === 0);
277:     if (this.shieldTime > 0) {
278:       ctx.save();
279:       ctx.globalCompositeOperation = 'lighter';
280:       ctx.strokeStyle = `rgba(127,232,255,${.4 + Math.sin(this.game.time * 6) * .15})`;
281:       ctx.lineWidth = 2;
282:       ctx.beginPath(); ctx.ellipse(this.x, this.y - 24, 26, 34, 0, 0, 6.28); ctx.stroke();
283:       ctx.restore();
284:     }
285:   }
286: }
287: 
288: function drawPlayerVisual(ctx, g, player, x, y, facing, walk, attack, block, hurt, dodge, weapon, shield, time, aura, blink = false) {
289:   ctx.save();
290:   if (blink) ctx.globalAlpha = .55;
291:   const app = player.state.appearance;
292:   const weaponDef = weapon?.weapon ? weapon : null;
293:   // draw shield if equipped
294:   ctx.save();
295:   // render humanoid
296:   const { drawHumanoid, resolveAppearance } = g.renderRef;
297:   drawHumanoid(ctx, {
298:     x, y, time, facing, walk: walk ? Math.sin(walk) : 0,
299:     attack, block: block ? 1 : 0, hurt, dodge: dodge > 0 ? 1 : 0,
300:     appearance: resolveAppearance(app),
301:     weapon: weaponDef ? { ...weaponDef, celestial: weaponDef.celestial } : null,
302:     shield: !!shield,
303:     shieldColor: '#6b4a2c', shieldTrim: '#e2c47a',
304:     armor: !!g.state.equipment.armor,
305:     armorColor: g.state.equipment.armor === 'armadura_celestial' ? '#f2d188' : '#9aa6ba',
306:     accessory: !!g.state.equipment.accessory,
307:     accessoryColor: g.state.equipment.accessory === 'talisman_suerte' ? '#ffd27a' : '#6fe8d4',
308:     aura: aura || null,
309:     cape: true,
310:   });
311:   ctx.restore();
312:   ctx.restore();
313: }
