315: /* -------------------------------------------------------------------------- */
316: /* Enemies                                                                    */
317: /* -------------------------------------------------------------------------- */
318: export class Enemy {
319:   constructor(game, type, tx, ty, level = 1, id = null) {
320:     this.game = game;
321:     this.type = type;
322:     this.def = ENEMIES[type];
323:     this.id = id || `${type}_${Math.random().toString(36).slice(2, 8)}`;
324:     this.level = level || this.def.level || 1;
325:     this.x = tx * T; this.y = ty * T;
326:     this.home = { x: this.x, y: this.y };
327:     this.radius = this.def.radius;
328:     this.maxHp = Math.round(this.def.hp * (1 + (this.level - this.def.level) * .18));
329:     this.hp = this.maxHp;
330:     this.atk = this.def.atk * (1 + (this.level - this.def.level) * .14);
331:     this.defense = this.def.def;
332:     this.speed = this.def.speed;
333:     this.xp = Math.round(this.def.xp * (1 + (this.level - 1) * .1));
334:     this.gold = this.def.gold;
335:     this.state = 'idle';
336:     this.stateTimer = 1 + Math.random() * 2;
337:     this.attackTimer = 1 + Math.random();
338:     this.telegraph = 0;
339:     this.telegraphTotal = 0;
340:     this.attackAnim = 0;
341:     this.hurt = 0;
342:     this.dead = false;
343:     this.deathTimer = 0;
344:     this.facing = 1;
345:     this.patrol = { x: this.x, y: this.y };
346:     this.phase = 1;
347:     this.phaseFlash = 0;
348:     this.knock = { x: 0, y: 0 };
349:     this.wanderAngle = Math.random() * 6.28;
350:     this.boss = !!this.def.boss;
351:     this.aggro = false;
352:     this.specialCd = 2.5;
353:     this.summoned = false;
354:   }
355: 
356:   get alive() { return !this.dead && this.hp > 0; }
357: 
358:   update(dt, player) {
359:     const g = this.game;
360:     if (this.dead) { this.deathTimer -= dt; return; }
361:     this.hurt = Math.max(0, this.hurt - dt);
362:     this.attackAnim = Math.max(0, this.attackAnim - dt);
363:     this.phaseFlash = Math.max(0, this.phaseFlash - dt);
364:     this.specialCd = Math.max(0, this.specialCd - dt);
365:     this.attackTimer = Math.max(0, this.attackTimer - dt);
366:     const dx = player.x - this.x, dy = player.y - this.y;
367:     const dist = Math.hypot(dx, dy);
368:     const aggroR = this.def.aggro;
369:     if (dist < aggroR || this.aggro || this.boss) this.aggro = true;
370:     if (this.aggro && dist > aggroR * 2.4 && !this.boss) this.aggro = false;
371: 
372:     // knockback
373:     if (Math.abs(this.knock.x) > 1 || Math.abs(this.knock.y) > 1) {
374:       g.world.moveEntity(this, this.knock.x * dt, this.knock.y * dt, []);
375:       this.knock.x *= .86; this.knock.y *= .86;
376:     }
377: 
378:     if (!this.aggro) {
379:       this.stateTimer -= dt;
380:       if (this.stateTimer <= 0) {
381:         this.stateTimer = 1.5 + Math.random() * 3;
382:         this.wanderAngle = Math.random() * 6.28;
383:         this.patrol = { x: this.home.x + Math.cos(this.wanderAngle) * 70, y: this.home.y + Math.sin(this.wanderAngle) * 70 };
384:       }
385:       const px = this.patrol.x - this.x, py = this.patrol.y - this.y;
386:       const pd = Math.hypot(px, py);
387:       if (pd > 10) {
388:         g.world.moveEntity(this, px / pd * this.speed * .32 * dt, py / pd * this.speed * .32 * dt, []);
389:         if (Math.abs(px) > 2) this.facing = px > 0 ? 1 : -1;
390:       }
391:       return;
392:     }
393: 
394:     if (this.type === 'wraith') { this.updateWraith(dt, player, dist, dx, dy); return; }
395:     if (this.boss) { this.updateBoss(dt, player, dist, dx, dy); return; }
396: 
397:     const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
398:     if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
399: 
400:     if (this.telegraph > 0) {
401:       this.telegraph -= dt;
402:       if (this.telegraph <= 0) this.executeAttack(player, nx, ny);
403:       return;
404:     }
405: 
406:     if (this.state === 'attack') {
407:       this.stateTimer -= dt;
408:       if (this.state === 'attack' && this.type === 'wolf') {
409:         // lunge movement
410:         g.world.moveEntity(this, this.lungeX * dt, this.lungeY * dt, []);
411:         if (dist < this.radius + player.radius + 6) player.takeDamage(this.atk * .9, this.x, this.y);
412:       }
413:       if (this.stateTimer <= 0) { this.state = 'chase'; this.attackTimer = .8; }
414:       return;
415:     }
416: 
417:     if (dist < this.radius + player.radius + 4) {
418:       // contact damage
419:       if (this.attackTimer <= 0) {
420:         player.takeDamage(this.atk * .55, this.x, this.y);
421:         this.attackTimer = 1.1;
422:       }
423:       // slight separation
424:       g.world.moveEntity(this, -nx * 12 * dt, -ny * 12 * dt, []);
425:       return;
426:     }
427: 
428:     if (this.type === 'wolf' && dist < 120 && this.attackTimer <= 0) {
429:       this.state = 'telegraph'; this.telegraph = .38; this.telegraphTotal = .38;
430:       this.lungeX = nx * 430; this.lungeY = ny * 430;
431:       audio.sfx('dodge');
432:       return;
433:     }
434:     if (this.type === 'beetle' && dist < 115 && this.attackTimer <= 0) {
435:       this.state = 'telegraph'; this.telegraph = .55; this.telegraphTotal = .55;
436:       this.lungeX = nx * 300; this.lungeY = ny * 300;
437:       return;
438:     }
439: 
440:     const sp = this.speed * (this.type === 'blob' ? (1 + Math.sin(g.time * 4) * .12) : 1);
441:     g.world.moveEntity(this, nx * sp * dt, ny * sp * dt, []);
442:     // contact for blob
443:     if (this.type === 'blob' && dist < this.radius + player.radius + 8 && this.attackTimer <= 0) {
444:       player.takeDamage(this.atk * .6, this.x, this.y);
445:       this.attackTimer = 1.15;
446:     }
447:   }
448: 
449:   executeAttack(player, nx, ny) {
450:     const g = this.game;
451:     if (this.type === 'wolf' || this.type === 'beetle') {
452:       this.state = 'attack'; this.stateTimer = this.type === 'wolf' ? .22 : .3;
453:       this.attackAnim = .3;
454:       audio.sfx('attack');
455:       const d = Math.hypot(player.x - this.x, player.y - this.y);
456:       if (d < 80) player.takeDamage(this.atk, this.x, this.y);
457:     } else {
458:       this.attackTimer = 1;
459:     }
460:   }
461: 
462:   updateWraith(dt, player, dist, dx, dy) {
463:     const g = this.game;
464:     const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
465:     if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
466:     if (this.attackTimer <= 0 && dist < 340) {
467:       // fire orb
468:       const ang = Math.atan2(dy, dx);
469:       g.spawnEnemyProjectile(this.x, this.y - 20, Math.cos(ang) * 190, Math.sin(ang) * 190, this.atk * .9, '#a68bff', 7);
470:       audio.sfx('magic');
471:       this.attackTimer = 2.2;
472:       this.attackAnim = .4;
473:     }
474:     if (dist < 110) g.world.moveEntity(this, -nx * this.speed * dt, -ny * this.speed * dt, []);
475:     else if (dist > 220) g.world.moveEntity(this, nx * this.speed * .8 * dt, ny * this.speed * .8 * dt, []);
476:     else {
477:       const a = Math.atan2(dy, dx) + Math.PI / 2;
478:       g.world.moveEntity(this, Math.cos(a) * this.speed * .45 * dt, Math.sin(a) * this.speed * .45 * dt, []);
479:     }
480:     if (this.specialCd <= 0 && dist < 90) {
481:       // blink away
482:       const ang = Math.random() * 6.28;
483:       const tx = this.x + Math.cos(ang) * 160, ty = this.y + Math.sin(ang) * 160;
484:       if (!g.world.collidesCircle(tx, ty, this.radius, [])) {
485:         g.particles.push(...Particle.burst(this.x, this.y - 20, 12, '#a68bff', { speed: 120, size: 2.5, life: .5 }));
486:         this.x = tx; this.y = ty;
487:         g.particles.push(...Particle.burst(this.x, this.y - 20, 12, '#a68bff', { speed: 120, size: 2.5, life: .5 }));
488:         audio.sfx('magic');
489:       }
490:       this.specialCd = 5;
491:     }
492:   }
493: 
494:   updateBoss(dt, player, dist, dx, dy) {
495:     const g = this.game;
496:     const nx = dist > 0 ? dx / dist : 0, ny = dist > 0 ? dy / dist : 0;
497:     if (Math.abs(dx) > 2) this.facing = dx > 0 ? 1 : -1;
498:     const isFinal = this.type === 'boss';
499:     const thresholds = isFinal ? [.66, .33] : [.5];
500:     if (this.phase - 1 < thresholds.length && this.hp / this.maxHp <= thresholds[this.phase - 1]) {
501:       this.phase++;
502:       this.phaseFlash = 1.2;
503:       this.speed *= 1.12;
504:       this.atk *= 1.08;
505:       g.shake(12, .5);
506:       g.hitstop(.15);
507:       audio.sfx('boss');
508:       g.toast(isFinal ? `El Avatar entra en la Fase ${['I', 'II', 'III'][this.phase - 1]}` : 'El Guardián se enfurece', 'bad');
509:       g.particles.push(...Particle.burst(this.x, this.y - 30, 40, isFinal ? '#ff8ab5' : '#ff9caf', { speed: 220, size: 3.2, life: .9 }));
510:       // shockwave ring
511:       for (let i = 0; i < 12; i++) {
512:         const a = i / 12 * Math.PI * 2;
513:         g.spawnEnemyProjectile(this.x, this.y - 24, Math.cos(a) * 170, Math.sin(a) * 170, this.atk * .55, isFinal ? '#ff8ab5' : '#ff9caf', 6);
514:       }
515:     }
516: 
517:     if (this.telegraph > 0) {
518:       this.telegraph -= dt;
519:       if (this.telegraph <= 0) {
520:         this.executeBossAttack(player, nx, ny);
521:       }
522:       return;
523:     }
524: 
525:     if (this.state === 'dash') {
526:       this.stateTimer -= dt;
527:       g.world.moveEntity(this, this.dashX * dt, this.dashY * dt, []);
528:       if (dist < this.radius + player.radius + 8) player.takeDamage(this.atk * 1.1, this.x, this.y);
529:       if (this.stateTimer <= 0) { this.state = 'chase'; this.attackTimer = 1.4; }
530:       return;
531:     }
532: 
533:     if (dist < 100 && this.attackTimer <= 0) {
534:       this.state = 'telegraph'; this.telegraph = .42; this.telegraphTotal = .42;
535:       this.pending = 'slash';
536:       return;
537:     }
538:     if (this.attackTimer <= 0) {
539:       const roll = Math.random();
540:       if (isFinal) {
541:         if (this.phase >= 3 && roll < .35) { this.pending = 'dash'; this.telegraph = .35; this.telegraphTotal = .35; this.dashX = nx * 520; this.dashY = ny * 520; }
542:         else if (roll < .65) { this.pending = 'meteors'; this.telegraph = .55; this.telegraphTotal = .55; }
543:         else { this.pending = 'orbs'; this.telegraph = .45; this.telegraphTotal = .45; }
544:       } else {
545:         if (this.phase >= 2 && roll < .35) { this.pending = 'ring'; this.telegraph = .5; this.telegraphTotal = .5; }
546:         else if (roll < .7) { this.pending = 'orbs'; this.telegraph = .4; this.telegraphTotal = .4; }
