29: class MB {
30:   constructor(w, h, base = 'g') {
31:     this.w = w; this.h = h; this.base = base;
32:     this.t = Array.from({ length: h }, () => Array(w).fill(base));
33:   }
34:   inb(x, y) { return x >= 0 && y >= 0 && x < this.w && y < this.h; }
35:   set(x, y, c) { if (this.inb(x, y)) this.t[y][x] = c; }
36:   get(x, y) { return this.inb(x, y) ? this.t[y][x] : 't'; }
37:   rect(x, y, w, h, c) {
38:     for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) this.set(i, j, c);
39:   }
40:   border(c) {
41:     for (let x = 0; x < this.w; x++) { this.set(x, 0, c); this.set(x, this.h - 1, c); }
42:     for (let y = 0; y < this.h; y++) { this.set(0, y, c); this.set(this.w - 1, y, c); }
43:   }
44:   clearArea(x, y, r, c = 'g') {
45:     for (let j = y - r; j <= y + r; j++) for (let i = x - r; i <= x + r; i++) if (this.inb(i, j)) this.t[j][i] = c;
46:   }
47:   path(points, width = 2, c = 'p') {
48:     for (let p = 0; p < points.length - 1; p++) {
49:       const [x0, y0] = points[p], [x1, y1] = points[p + 1];
50:       const dist = Math.hypot(x1 - x0, y1 - y0);
51:       const steps = Math.max(1, Math.ceil(dist / .35));
52:       for (let s = 0; s <= steps; s++) {
53:         const x = Math.round(x0 + (x1 - x0) * s / steps);
54:         const y = Math.round(y0 + (y1 - y0) * s / steps);
55:         const x0b = x - Math.floor(width / 2), y0b = y - Math.floor(width / 2);
56:         for (let j = 0; j < width; j++) for (let i = 0; i < width; i++) this.set(x0b + i, y0b + j, c);
57:       }
58:     }
59:   }
60:   blob(cx, cy, rx, ry, c) {
61:     for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++)
62:       for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
63:         const d = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2;
64:         if (d <= 1) this.set(x, y, c);
65:       }
66:   }
67:   scatter(x, y, w, h, c, chance, seed, over = this.base) {
68:     const r = rng(seed);
69:     for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) {
70:       if (this.get(i, j) === over && r() < chance) this.set(i, j, c);
71:     }
72:   }
73: }
