402: /* -------------------------------------------------------------------------- */
403: /* World                                                                      */
404: /* -------------------------------------------------------------------------- */
405: export class World {
406:   constructor(game) {
407:     this.game = game;
408:     this.maps = buildMaps();
409:     this.zoneKey = null;
410:     this.map = null;
411:     this.decor = [];
412:     this.groundCanvas = null;
413:     this.weather = [];
414:     this.time = 0;
415:     this.lights = [];
416:     this.tileAnimated = [];
417:     this.transitionCooldown = 0;
418:   }
419: 
420:   load(zoneKey, spawnTile) {
421:     this.zoneKey = zoneKey;
422:     this.zone = ZONES[zoneKey];
423:     const baseMap = this.maps[zoneKey];
424:     this.map = {
425:       ...baseMap,
426:       tiles: baseMap.tiles.map(row => row.slice()),
427:       objects: baseMap.objects.map(o => ({ ...o })),
428:     };
429:     this.applyFlags();
430:     this.buildDecor();
431:     this.bakeGround();
432:     this.buildLights();
433:     this.initWeather();
434:     this.time = 0;
435:     this.transitionCooldown = .8;
436:     if (spawnTile) {
437:       this.spawn = { x: (spawnTile[0] + .5) * T, y: (spawnTile[1] + .5) * T };
438:     }
439:   }
440: 
441:   applyFlags() {
442:     const flags = this.game.state?.flags || {};
443:     for (const o of this.map.objects) {
444:       if (o.type === 'obstacle') {
445:         if (flags[`obstacle:${this.zoneKey}:${o.tx},${o.ty}`]) o.cleared = true;
446:       }
447:       if (o.type === 'chest' && flags[`chest:${o.id}`]) o.opened = true;
448:       if (o.type === 'relic' && flags[`relic:${o.id}`]) o.taken = true;
449:       if (o.type === 'gate' && (flags[`gate:${o.id}`] || (o.openFlag && flags[o.openFlag]))) o.open = true;
450:       if (o.type === 'rune' && flags[`rune:${o.id}`]) o.active = true;
451:       if (o.type === 'runeDisplay') o.active = !!flags[`rune_taken:${o.rune}`] || !!flags[`relic:relic_${o.rune.replace('runa_', 'runa_')}`];
452:     }
453:     // Generate obstacle objects from tiles
454:     for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
455:       const ch = this.map.tiles[y][x];
456:       if (ch === 'B' || ch === 'M' || ch === 'H') {
457:         const key = `obstacle:${this.zoneKey}:${x},${y}`;
458:         if (flags[key]) {
459:           this.map.tiles[y][x] = this.map.base;
460:         } else {
461:           this.map.objects.push({
462:             type: 'obstacle', id: `obs_${this.zoneKey}_${x}_${y}`, tx: x, ty: y,
463:             x: x + .5, y: y + .5, ability: ch === 'B' ? 'burn' : ch === 'M' ? 'freeze' : 'move',
464:             tile: ch, floor: this.map.base, solid: false,
465:           });
466:         }
467:       }
468:     }
469:   }
470: 
471:   buildDecor() {
472:     this.decor = [];
473:     const p = PAL[this.zoneKey] || PAL.aldea;
474:     for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
475:       const ch = this.map.tiles[y][x];
476:       const h = hash(x, y, 3);
477:       if (ch === 't') {
478:         this.decor.push({
479:           kind: 'tree', tx: x, ty: y, x: x + .5, y: y + .5,
480:           sortY: (y + 1) * T + 6, variant: Math.floor(h * 4), phase: h * 6.28,
481:           canopy: p.tree, canopy2: p.tree2,
482:         });
483:       } else if (ch === 'r') {
484:         this.decor.push({ kind: 'rock', tx: x, ty: y, x: x + .5, y: y + .5, sortY: (y + 1) * T, variant: Math.floor(h * 3), color: p.wall2 });
485:       } else if (ch === 'c') {
486:         this.decor.push({ kind: 'crystal', tx: x, ty: y, x: x + .5, y: y + .5, sortY: (y + 1) * T, color: p.water2 });
487:       } else if (ch === 'e') {
488:         this.decor.push({ kind: 'ember', tx: x, ty: y, x: x + .5, y: y + .5, sortY: 0, phase: h * 6.28 });
489:       }
490:     }
491:     // obstacle decor
492:     for (const o of this.map.objects) {
493:       if (o.type === 'obstacle' && !o.cleared) {
494:         this.decor.push({ kind: 'obstacle', obj: o, tx: o.tx, ty: o.ty, x: o.x, y: o.y, sortY: (o.ty + 1) * T });
495:       }
496:     }
497:     this.decor.sort((a, b) => a.sortY - b.sortY);
498:   }
499: 
500:   buildLights() {
501:     this.lights = [];
502:     const add = (x, y, r, color, intensity = .8) => this.lights.push({ x: x * T, y: y * T, r, color, intensity });
503:     for (const o of this.map.objects) {
504:       if (o.type === 'shrine') add(o.x, o.y, 150, '#ffd98a', .85);
505:       if (o.type === 'brazier') add(o.x, o.y, 130, '#ff9a55', .7);
506:       if (o.type === 'crystal') add(o.x, o.y, 120, o.color || '#7fb4ff', .6);
507:       if (o.type === 'altar') add(o.x, o.y, 200, '#ffd98a', .9);
508:       if (o.type === 'rune' && o.active) add(o.x, o.y, 150, '#ffd27a', .8);
509:       if (o.type === 'relic' && !o.taken) add(o.x, o.y, 110, '#ffd27a', .55);
510:       if (o.type === 'fountain') add(o.x, o.y, 110, '#6fe8d4', .5);
511:       if (o.type === 'gate' && !o.open) add(o.x, o.y, 80, '#a68bff', .4);
512:     }
513:     // ambient crystals from decor
514:     for (const d of this.decor) if (d.kind === 'crystal') add(d.x, d.y, 100, d.color || '#7fb4ff', .45);
515:   }
516: 
517:   initWeather() {
518:     const type = this.map.ambient?.type || 'dust';
519:     const count = type === 'stars' ? 70 : type === 'fireflies' ? 45 : 55;
520:     this.weather = [];
521:     for (let i = 0; i < count; i++) {
522:       this.weather.push(this._newParticle(type, true));
523:     }
524:   }
525: 
526:   _newParticle(type, initial = false) {
527:     const player = this.game.player;
528:     const cx = player ? player.x : (this.map.w * T) / 2;
529:     const cy = player ? player.y : (this.map.h * T) / 2;
530:     const w = (this.game.viewW || 1100) + 300, h = (this.game.viewH || 650) + 300;
531:     const x = cx + (Math.random() - .5) * w;
532:     const y = cy + (Math.random() - .5) * h;
533:     const base = { type, x, y, phase: Math.random() * 6.28, alpha: .4 + Math.random() * .5 };
534:     if (type === 'leaves') return { ...base, vx: 12 + Math.random() * 22, vy: 8 + Math.random() * 12, size: 2 + Math.random() * 3, rot: Math.random() * 6.28, spin: (Math.random() - .5) * 2 };
535:     if (type === 'fireflies') return { ...base, vx: (Math.random() - .5) * 12, vy: (Math.random() - .5) * 12, size: 1.2 + Math.random() * 1.8 };
536:     if (type === 'dust') return { ...base, vx: 2 + Math.random() * 6, vy: -2 - Math.random() * 5, size: 1 + Math.random() * 2 };
537:     if (type === 'embers') return { ...base, vx: (Math.random() - .5) * 10, vy: -16 - Math.random() * 26, size: 1 + Math.random() * 2.2 };
538:     return { ...base, vx: (Math.random() - .5) * 3, vy: (Math.random() - .5) * 3, size: .8 + Math.random() * 1.8 };
539:   }
540: 
541:   update(dt, player, camera) {
542:     this.time += dt;
543:     if (this.transitionCooldown > 0) this.transitionCooldown -= dt;
544:     for (let i = 0; i < this.weather.length; i++) {
545:       const p = this.weather[i];
546:       p.x += p.vx * dt; p.y += p.vy * dt;
547:       p.phase += dt * 2;
548:       if (p.type === 'leaves') { p.rot += p.spin * dt; p.x += Math.sin(p.phase) * 8 * dt; }
549:       if (p.type === 'fireflies') { p.x += Math.sin(p.phase * 1.3) * 10 * dt; p.y += Math.cos(p.phase) * 10 * dt; }
550:       if (p.type === 'stars') { p.y += Math.sin(p.phase) * 2 * dt; }
551:       const margin = 220;
552:       if (p.x < camera.x - margin || p.x > camera.x + camera.w + margin || p.y < camera.y - margin || p.y > camera.y + camera.h + margin) {
553:         this.weather[i] = this._newParticle(p.type);
554:       }
555:     }
556:   }
557: 
558:   /* ---------------------------------------------------------------------- */
559:   /* Collision                                                              */
560:   /* ---------------------------------------------------------------------- */
561:   tileAt(tx, ty) {
562:     if (tx < 0 || ty < 0 || tx >= this.map.w || ty >= this.map.h) return 't';
563:     return this.map.tiles[ty][tx];
564:   }
565:   tileAtPx(px, py) {
566:     return this.tileAt(Math.floor(px / T), Math.floor(py / T));
567:   }
568: 
569:   isTileSolid(tx, ty, abilities = []) {
570:     const ch = this.tileAt(tx, ty);
571:     if (ch === 'w' || ch === 'W') return !abilities.includes('swim');
572:     if (ch === 'v') return !abilities.includes('fly');
573:     return SOLID.has(ch);
574:   }
575: 
576:   collidesCircle(x, y, r, abilities = []) {
577:     const x0 = Math.floor((x - r) / T), x1 = Math.floor((x + r) / T);
578:     const y0 = Math.floor((y - r) / T), y1 = Math.floor((y + r) / T);
579:     for (let ty = y0; ty <= y1; ty++) for (let tx = x0; tx <= x1; tx++) {
580:       if (this.isTileSolid(tx, ty, abilities)) {
581:         // circle vs tile AABB
582:         const cx = Math.max(tx * T, Math.min(x, (tx + 1) * T));
583:         const cy = Math.max(ty * T, Math.min(y, (ty + 1) * T));
584:         if ((x - cx) ** 2 + (y - cy) ** 2 < r * r) return true;
585:       }
586:     }
587:     for (const o of this.map.objects) {
588:       if (!this._objectSolid(o)) continue;
589:       const ox = o.x * T, oy = o.y * T;
590:       const half = o.type === 'fountain' ? 30 : o.type === 'altar' ? 28 : o.type === 'shrine' ? 20 : 17;
591:       const cx = Math.max(ox - half, Math.min(x, ox + half));
592:       const cy = Math.max(oy - half, Math.min(y, oy + half));
593:       if ((x - cx) ** 2 + (y - cy) ** 2 < r * r) return true;
594:     }
595:     return false;
596:   }
597: 
598:   _objectSolid(o) {
599:     if (o.cleared || o.taken) return false;
600:     if (o.type === 'gate') return !o.open;
601:     if (o.type === 'chest') return true;
602:     if (o.type === 'relic') return !o.taken;
603:     if (o.type === 'obstacle') return false;
604:     return !!o.solid;
605:   }
606: 
607:   moveEntity(ent, dx, dy, abilities = []) {
608:     const r = ent.radius || 14;
609:     let movedX = false, movedY = false;
610:     if (dx) {
611:       if (!this.collidesCircle(ent.x + dx, ent.y, r, abilities)) { ent.x += dx; movedX = true; }
612:       else {
613:         // slide small steps
614:         const step = Math.sign(dx);
615:         for (let i = 1; i <= Math.abs(dx); i++) {
616:           if (!this.collidesCircle(ent.x + step, ent.y, r, abilities)) { ent.x += step; movedX = true; } else break;
617:         }
618:       }
619:     }
620:     if (dy) {
621:       if (!this.collidesCircle(ent.x, ent.y + dy, r, abilities)) { ent.y += dy; movedY = true; }
622:       else {
623:         const step = Math.sign(dy);
624:         for (let i = 1; i <= Math.abs(dy); i++) {
625:           if (!this.collidesCircle(ent.x, ent.y + step, r, abilities)) { ent.y += step; movedY = true; } else break;
626:         }
627:       }
628:     }
629:     ent.x = Math.max(T * .4, Math.min((this.map.w - .4) * T, ent.x));
630:     ent.y = Math.max(T * .4, Math.min((this.map.h - .4) * T, ent.y));
631:     return { movedX, movedY };
632:   }
633: 
634:   /* ---------------------------------------------------------------------- */
635:   /* Interaction                                                            */
636:   /* ---------------------------------------------------------------------- */
637:   findInteractable(px, py, radius = 74, abilities = []) {
638:     let best = null, bestD = Infinity;
639:     for (const o of this.map.objects) {
640:       if (o.taken || o.cleared) continue;
641:       if (o.type === 'chest' && o.opened) continue;
642:       if (o.type === 'obstacle' && !o.cleared) {
643:         // handled below with ability hint
644:       }
645:       if (o.type === 'gate' && o.open) continue;
646:       if (o.type === 'relic' && o.taken) continue;
647:       if (o.type === 'chest' && o.hidden && !abilities.includes(o.requires)) continue;
648:       if (o.type === 'npc' || o.type === 'chest' || o.type === 'shrine' || o.type === 'sign' || o.type === 'relic' || o.type === 'rune' || o.type === 'altar' || o.type === 'gate' || o.type === 'obstacle' || o.type === 'runeDisplay') {
649:         const d = Math.hypot(o.x * T - px, o.y * T - py);
650:         if (d < radius && d < bestD) { best = o; bestD = d; }
651:       }
652:     }
653:     return best;
654:   }
655: 
656:   getExitAt(px, py) {
657:     for (const e of this.map.exits) {
658:       const [x, y, w, h] = e.rect;
659:       if (px >= x * T && px <= (x + w) * T && py >= y * T && py <= (y + h) * T) return e;
660:     }
661:     return null;
662:   }
663: 
664:   clearObstacle(obj) {
665:     obj.cleared = true;
666:     const tx = obj.tx, ty = obj.ty;
667:     this.map.tiles[ty][tx] = obj.floor;
668:     this.decor = this.decor.filter(d => d.obj !== obj);
669:     this.paintTile(tx, ty, obj.floor);
670:     this.buildLights();
671:   }
672: 
673:   /* ---------------------------------------------------------------------- */
674:   /* Ground baking / rendering                                              */
675:   /* ---------------------------------------------------------------------- */
676:   bakeGround() {
677:     const c = document.createElement('canvas');
678:     c.width = this.map.w * T; c.height = this.map.h * T;
679:     const g = c.getContext('2d');
680:     for (let y = 0; y < this.map.h; y++) for (let x = 0; x < this.map.w; x++) {
681:       this.paintTileTo(g, x, y, this.map.tiles[y][x]);
682:     }
683:     this.groundCanvas = c;
684:   }
685: 
686:   paintTile(tx, ty, ch) {
687:     if (!this.groundCanvas) return;
688:     const g = this.groundCanvas.getContext('2d');
689:     this.paintTileTo(g, tx, ty, ch);
690:   }
691: 
692:   paintTileTo(g, tx, ty, ch) {
693:     const p = PAL[this.zoneKey] || PAL.aldea;
694:     const x = tx * T, y = ty * T;
695:     const h = hash(tx, ty, 7);
696:     const h2 = hash(tx, ty, 11);
697:     switch (ch) {
698:       case 'g': case 'G': {
699:         g.fillStyle = h > .5 ? p.grass : p.grass2;
700:         g.fillRect(x, y, T, T);
701:         // blades
702:         g.strokeStyle = p.grass3; g.lineWidth = 1; g.globalAlpha = .45;
703:         for (let i = 0; i < 4; i++) {
704:           const bx = x + 6 + hash(tx, ty, i + 20) * 36;
705:           const by = y + 10 + hash(tx, ty, i + 30) * 30;
706:           g.beginPath(); g.moveTo(bx, by); g.lineTo(bx + 2, by - 4); g.stroke();
707:         }
708:         g.globalAlpha = 1;
709:         if (h2 > .86) {
710:           g.fillStyle = p.flower;
711:           g.globalAlpha = .8;
712:           for (let i = 0; i < 3; i++) {
713:             const fx = x + 12 + hash(tx, ty, i + 40) * 24;
714:             const fy = y + 12 + hash(tx, ty, i + 50) * 24;
715:             g.beginPath(); g.arc(fx, fy, 1.6, 0, 6.28); g.fill();
716:           }
717:           g.globalAlpha = 1;
718:         }
719:         break;
720:       }
