281: function drawHeldWeapon(ctx, weapon, { t, atk, side, block, celestial }) {
282:   const kind = weapon.kind || 'sword';
283:   ctx.save();
284:   ctx.translate(14, -27);
285:   let angle = side ? -0.1 : 0.55;
286:   if (atk > 0) {
287:     const p = clamp(atk, 0, 1);
288:     angle = lerp(-1.55, 1.35, easeOutCubic(p));
289:     ctx.translate(Math.sin(p * Math.PI) * 5, -Math.sin(p * Math.PI) * 4);
290:   }
291:   if (block > 0) angle = -1.3;
292:   ctx.rotate(angle);
293:   const glow = celestial || weapon.glow;
294:   if (glow) { ctx.shadowColor = '#ffe6a0'; ctx.shadowBlur = 12; }
295:   switch (kind) {
296:     case 'greatsword':
297:       ctx.fillStyle = '#4a3a2a'; rr(ctx, -2, -4, 4, 13, 1.5); ctx.fill();
298:       ctx.fillStyle = '#c9a14a'; rr(ctx, -7, -7, 14, 3, 1.5); ctx.fill();
299:       ctx.fillStyle = glow ? '#fff3c4' : '#cfd9ea';
300:       ctx.beginPath(); ctx.moveTo(-3.4, -7); ctx.lineTo(0, -47); ctx.lineTo(3.4, -7); ctx.closePath(); ctx.fill();
301:       ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 1; ctx.stroke();
