305:       ctx.fillStyle = '#c9a14a'; rr(ctx, -4, -5, 8, 2, 1); ctx.fill();
306:       ctx.fillStyle = glow ? '#fff3c4' : '#d7dfef';
307:       ctx.beginPath(); ctx.moveTo(-2.2, -5); ctx.lineTo(0, -24); ctx.lineTo(2.2, -5); ctx.closePath(); ctx.fill();
308:       break;
309:     case 'spear':
