311:       ctx.fillStyle = glow ? '#fff3c4' : '#c7d3e6';
312:       ctx.beginPath(); ctx.moveTo(0, -64); ctx.lineTo(4, -52); ctx.lineTo(0, -48); ctx.lineTo(-4, -52); ctx.closePath(); ctx.fill();
313:       break;
314:     case 'bow':
