318:       ctx.beginPath(); ctx.moveTo(5.5, -27); ctx.lineTo(5.5, -1); ctx.stroke();
319:       ctx.fillStyle = '#e9f5ff';
320:       ctx.beginPath(); ctx.moveTo(-14, -14); ctx.lineTo(4, -18); ctx.lineTo(4, -10); ctx.closePath(); ctx.fill();
321:       break;
322:     case 'staff':
323:       ctx.fillStyle = '#5a4a6d'; rr(ctx, -1.8, -46, 3.6, 51, 1.8); ctx.fill();
324:       ctx.fillStyle = '#f2d188'; ctx.shadowColor = '#ffe9a8'; ctx.shadowBlur = 14;
