342: export function drawSlash(ctx, x, y, angle, radius, progress, color = '#ffe6a0', arc = 1.6) {
343:   if (progress <= 0 || progress >= 1) return;
344:   const a0 = angle - arc / 2;
345:   const sweep = arc * easeOutCubic(clamp(progress, 0, 1));
346:   ctx.save();
347:   ctx.translate(x, y - 26);
348:   ctx.rotate(a0 + sweep * .5);
349:   ctx.globalCompositeOperation = 'lighter';
350:   const alpha = (1 - progress) * .9;
351:   const g = ctx.createRadialGradient(0, 0, radius * .25, 0, 0, radius);
352:   g.addColorStop(0, 'rgba(255,255,255,0)');
353:   g.addColorStop(.72, color);
354:   g.addColorStop(1, 'rgba(255,255,255,0)');
355:   ctx.globalAlpha = alpha;
356:   ctx.strokeStyle = g;
357:   ctx.lineWidth = 5 + (1 - progress) * 9;
358:   ctx.beginPath();
359:   ctx.arc(0, 0, radius * .8, -sweep / 2, sweep / 2);
360:   ctx.stroke();
361:   ctx.globalAlpha = alpha * .5;
362:   ctx.lineWidth = 2;
363:   ctx.beginPath();
364:   ctx.arc(0, 0, radius * .95, -sweep / 2, sweep / 2);
365:   ctx.stroke();
366:   ctx.restore();
367: }
