777:         g.strokeStyle = 'rgba(0,0,0,.18)';
778:         g.beginPath(); g.moveTo(x + 16, y + 3); g.lineTo(x + 16, y + 26); g.stroke();
779:         g.beginPath(); g.moveTo(x + 32, y + 22); g.lineTo(x + 32, y + 43); g.stroke();
780:         break;
781:       }
782:       case 't': {
783:         g.fillStyle = p.grass; g.fillRect(x, y, T, T);
784:         break;
785:       }
786:       case 'r': {
787:         g.fillStyle = p.grass; g.fillRect(x, y, T, T);
788:         g.fillStyle = 'rgba(0,0,0,.08)'; g.beginPath(); g.arc(x + T / 2, y + T / 2 + 5, 16, 0, 6.28); g.fill();
789:         break;
790:       }
791:       case 'w': case 'W': {
792:         g.fillStyle = p.water; g.fillRect(x, y, T, T);
793:         g.fillStyle = p.water2; g.globalAlpha = .25;
794:         for (let i = 0; i < 3; i++) {
795:           g.beginPath();
796:           g.ellipse(x + 8 + i * 15 + Math.sin(hash(tx, ty, i) * 6) * 3, y + 12 + i * 12, 8, 2.2, 0, 0, 6.28);
797:           g.fill();
798:         }
799:         g.globalAlpha = 1;
800:         break;
801:       }
802:       case 'b': {
803:         g.fillStyle = '#7b5a36'; g.fillRect(x, y, T, T);
804:         g.strokeStyle = '#5c4026'; g.lineWidth = 2;
805:         for (let i = 0; i < 5; i++) { g.beginPath(); g.moveTo(x + 4 + i * 10, y + 2); g.lineTo(x + 4 + i * 10, y + T - 2); g.stroke(); }
806:         g.fillStyle = 'rgba(255,255,255,.1)'; g.fillRect(x, y + 4, T, 2);
807:         break;
808:       }
809:       case 'l': {
810:         const lg = g.createLinearGradient(x, y, x, y + T);
811:         lg.addColorStop(0, '#d2572b'); lg.addColorStop(.5, '#ff8a3c'); lg.addColorStop(1, '#a8321c');
812:         g.fillStyle = lg; g.fillRect(x, y, T, T);
813:         g.fillStyle = 'rgba(255,220,120,.35)';
814:         g.beginPath(); g.ellipse(x + 12 + h * 24, y + 14 + h2 * 20, 9, 3, 0, 0, 6.28); g.fill();
815:         break;
816:       }
817:       case 'v': {
818:         g.fillStyle = '#0a0818'; g.fillRect(x, y, T, T);
819:         g.fillStyle = 'rgba(140,110,255,.25)';
820:         for (let i = 0; i < 3; i++) {
821:           g.beginPath(); g.arc(x + 8 + hash(tx, ty, i) * 32, y + 8 + hash(tx, ty, i + 5) * 32, 1 + h, 0, 6.28); g.fill();
822:         }
823:         break;
824:       }
825:       case 'i': {
826:         g.fillStyle = '#9fdcf0'; g.fillRect(x, y, T, T);
827:         g.strokeStyle = 'rgba(255,255,255,.5)'; g.lineWidth = 1;
828:         g.beginPath(); g.moveTo(x + 6, y + 10); g.lineTo(x + 20, y + 24); g.lineTo(x + 16, y + 38); g.stroke();
829:         break;
830:       }
831:       case 'u': {
832:         g.fillStyle = p.plaza2; g.fillRect(x, y, T, T);
833:         g.fillStyle = 'rgba(180,180,200,.18)';
834:         for (let i = 0; i < 4; i++) g.fillRect(x + 6 + hash(tx, ty, i) * 30, y + 8 + hash(tx, ty, i + 3) * 28, 5 + h * 6, 3);
835:         break;
836:       }
837:       case 'e': {
838:         g.fillStyle = '#5b3a2e'; g.fillRect(x, y, T, T);
839:         g.fillStyle = 'rgba(255,130,60,.22)';
840:         g.beginPath(); g.arc(x + T / 2, y + T / 2, 14 + h * 6, 0, 6.28); g.fill();
841:         g.fillStyle = 'rgba(255,210,120,.4)';
842:         g.beginPath(); g.arc(x + 16 + h * 16, y + 20 + h2 * 12, 1.6, 0, 6.28); g.fill();
843:         break;
844:       }
845:       case 'h': {
846:         g.fillStyle = p.hedge; g.fillRect(x, y, T, T);
847:         g.fillStyle = 'rgba(255,255,255,.08)';
848:         g.beginPath(); g.arc(x + 14, y + 16, 9, 0, 6.28); g.fill();
849:         g.beginPath(); g.arc(x + 32, y + 28, 8, 0, 6.28); g.fill();
850:         break;
851:       }
852:       case 'B': case 'M': case 'H': case 'R': case 'A': case 'c': {
853:         g.fillStyle = p.grass; g.fillRect(x, y, T, T);
854:         if (ch === 'R') {
855:           g.strokeStyle = 'rgba(242,209,136,.5)'; g.lineWidth = 1.6;
856:           g.beginPath(); g.arc(x + T / 2, y + T / 2, 15, 0, 6.28); g.stroke();
857:           g.beginPath(); g.arc(x + T / 2, y + T / 2, 9, 0, 6.28); g.stroke();
858:           for (let i = 0; i < 4; i++) {
859:             const a = i * Math.PI / 2 + .4;
860:             g.beginPath(); g.moveTo(x + T / 2 + Math.cos(a) * 8, y + T / 2 + Math.sin(a) * 8);
861:             g.lineTo(x + T / 2 + Math.cos(a) * 15, y + T / 2 + Math.sin(a) * 15); g.stroke();
862:           }
863:         }
864:         break;
865:       }
866:       default: {
867:         g.fillStyle = p.grass; g.fillRect(x, y, T, T);
868:       }
869:     }
870:   }
