872:   /* ---------------------------------------------------------------------- */
873:   /* Drawables & object rendering                                           */
874:   /* ---------------------------------------------------------------------- */
875:   visible(x, y, camera, margin = 130) {
876:     return x > camera.x - margin && x < camera.x + camera.w + margin && y > camera.y - margin && y < camera.y + camera.h + margin;
877:   }
878: 
879:   getDrawables(camera, abilities = []) {
880:     const list = [];
881:     for (const d of this.decor) {
882:       if (!this.visible(d.x * T, d.y * T, camera)) continue;
883:       if (d.kind === 'obstacle') {
884:         list.push({ sortY: d.sortY, draw: ctx => this.drawObstacle(ctx, d.obj) });
885:       } else if (d.kind === 'tree') list.push({ sortY: d.sortY, draw: ctx => this.drawTree(ctx, d) });
886:       else if (d.kind === 'rock') list.push({ sortY: d.sortY, draw: ctx => this.drawRock(ctx, d) });
887:       else if (d.kind === 'crystal') list.push({ sortY: d.sortY, draw: ctx => this.drawCrystal(ctx, d) });
888:       else if (d.kind === 'ember') list.push({ sortY: 0, draw: ctx => this.drawEmber(ctx, d) });
889:     }
890:     for (const o of this.map.objects) {
891:       if (o.cleared || o.taken) continue;
892:       if (!this.visible(o.x * T, o.y * T, camera)) continue;
893:       if (o.type === 'obstacle') continue;
894:       if (o.type === 'chest' && o.hidden && !abilities.includes(o.requires)) continue;
895:       const sortY = (o.y + .5) * T;
896:       list.push({ sortY, draw: ctx => this.drawObject(ctx, o, abilities) });
897:     }
898:     list.sort((a, b) => a.sortY - b.sortY);
899:     return list;
900:   }
901: 
902:   drawTree(ctx, d) {
903:     const x = d.x * T, y = d.y * T;
904:     const sway = Math.sin(this.time * 1.2 + d.phase) * 2.2;
905:     ctx.save();
906:     // trunk
907:     ctx.fillStyle = '#4a3323';
908:     ctx.beginPath(); ctx.moveTo(x - 5, y + 10); ctx.lineTo(x - 3, y - 34); ctx.lineTo(x + 3, y - 34); ctx.lineTo(x + 5, y + 10); ctx.fill();
909:     // canopy layers
910:     const c1 = d.canopy, c2 = d.canopy2;
911:     const g = ctx.createRadialGradient(x - 10 + sway, y - 62, 4, x, y - 50, 38);
912:     g.addColorStop(0, lighten(c2, 22)); g.addColorStop(.55, c1); g.addColorStop(1, darken(c1, 24));
913:     ctx.fillStyle = g;
914:     const r = 30 + d.variant * 3;
915:     ctx.beginPath(); ctx.arc(x + sway, y - 58, r, 0, 6.28); ctx.fill();
916:     ctx.beginPath(); ctx.arc(x - r * .65 + sway * .6, y - 42, r * .7, 0, 6.28); ctx.fill();
917:     ctx.beginPath(); ctx.arc(x + r * .65 + sway * .6, y - 44, r * .66, 0, 6.28); ctx.fill();
918:     ctx.fillStyle = 'rgba(255,255,255,.12)';
919:     ctx.beginPath(); ctx.arc(x - r * .32 + sway, y - 66, r * .3, 0, 6.28); ctx.fill();
920:     ctx.restore();
921:   }
922: 
923:   drawRock(ctx, d) {
924:     const x = d.x * T, y = d.y * T;
925:     const s = 13 + d.variant * 3;
926:     ctx.save();
927:     ctx.fillStyle = d.color;
928:     ctx.beginPath();
929:     ctx.moveTo(x - s, y + 8); ctx.lineTo(x - s * .8, y - s * .6);
930:     ctx.lineTo(x - s * .1, y - s); ctx.lineTo(x + s * .8, y - s * .45);
931:     ctx.lineTo(x + s, y + 8); ctx.closePath(); ctx.fill();
932:     ctx.fillStyle = 'rgba(255,255,255,.14)';
933:     ctx.beginPath(); ctx.moveTo(x - s * .6, y - s * .4); ctx.lineTo(x - s * .1, y - s); ctx.lineTo(x + s * .3, y - s * .5); ctx.closePath(); ctx.fill();
934:     ctx.fillStyle = 'rgba(0,0,0,.2)'; ctx.beginPath(); ctx.ellipse(x, y + 8, s, 4, 0, 0, 6.28); ctx.fill();
935:     ctx.restore();
936:   }
937: 
938:   drawCrystal(ctx, d) {
939:     const x = d.x * T, y = d.y * T;
940:     const color = d.color || '#7fb4ff';
941:     const pulse = .7 + Math.sin(this.time * 2 + d.x) * .2;
942:     ctx.save();
943:     ctx.globalCompositeOperation = 'lighter';
944:     const g = ctx.createRadialGradient(x, y - 22, 2, x, y - 22, 44);
945:     g.addColorStop(0, hexA(color, .32 * pulse)); g.addColorStop(1, 'transparent');
946:     ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 22, 44, 0, 6.28); ctx.fill();
947:     ctx.globalCompositeOperation = 'source-over';
948:     ctx.fillStyle = color;
949:     ctx.beginPath(); ctx.moveTo(x - 9, y + 8); ctx.lineTo(x - 5, y - 30); ctx.lineTo(x + 2, y - 44); ctx.lineTo(x + 9, y - 24); ctx.lineTo(x + 7, y + 8); ctx.closePath(); ctx.fill();
950:     ctx.fillStyle = 'rgba(255,255,255,.45)';
951:     ctx.beginPath(); ctx.moveTo(x - 2, y + 2); ctx.lineTo(x + 1, y - 38); ctx.lineTo(x + 4, y - 26); ctx.lineTo(x + 2, y + 2); ctx.closePath(); ctx.fill();
952:     ctx.restore();
953:   }
954: 
955:   drawEmber(ctx, d) {
956:     ctx.save();
957:     ctx.globalCompositeOperation = 'lighter';
958:     const a = .25 + Math.sin(this.time * 3 + d.phase) * .12;
959:     ctx.fillStyle = `rgba(255,140,70,${a})`;
960:     ctx.beginPath(); ctx.ellipse(d.x * T, d.y * T, 18, 6, 0, 0, 6.28); ctx.fill();
961:     ctx.restore();
962:   }
963: 
964:   drawObstacle(ctx, o) {
965:     if (o.cleared) return;
966:     const x = o.x * T, y = o.y * T;
967:     ctx.save();
968:     if (o.tile === 'B') {
969:       ctx.fillStyle = '#2a3d26';
970:       for (let i = 0; i < 5; i++) {
971:         const a = i * 1.3;
972:         ctx.beginPath(); ctx.ellipse(x + Math.cos(a) * 14, y - 6 + Math.sin(a) * 8, 11, 7, a, 0, 6.28); ctx.fill();
973:       }
974:       ctx.strokeStyle = '#5c3a2a'; ctx.lineWidth = 2.2;
975:       for (let i = 0; i < 5; i++) {
976:         const a = i * 1.7;
977:         ctx.beginPath(); ctx.moveTo(x, y + 2); ctx.lineTo(x + Math.cos(a) * 22, y - 18 + Math.sin(a) * 12); ctx.stroke();
978:       }
979:       ctx.fillStyle = '#d95a5a';
980:       for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.arc(x + Math.cos(i * 2) * 15, y - 10 + Math.sin(i * 2) * 8, 2, 0, 6.28); ctx.fill(); }
981:     } else if (o.tile === 'M') {
982:       ctx.fillStyle = '#7fc8e8';
983:       ctx.beginPath(); ctx.moveTo(x - 12, y + 6); ctx.lineTo(x - 9, y - 34); ctx.lineTo(x, y - 46); ctx.lineTo(x + 9, y - 34); ctx.lineTo(x + 12, y + 6); ctx.closePath(); ctx.fill();
984:       ctx.fillStyle = 'rgba(255,255,255,.5)';
985:       ctx.beginPath(); ctx.moveTo(x - 3, y + 2); ctx.lineTo(x, y - 40); ctx.lineTo(x + 4, y - 28); ctx.lineTo(x + 3, y + 2); ctx.closePath(); ctx.fill();
986:       ctx.strokeStyle = 'rgba(200,245,255,.7)'; ctx.lineWidth = 1.4;
987:       ctx.beginPath(); ctx.arc(x, y - 18, 20, 0, 6.28); ctx.stroke();
988:     } else {
989:       ctx.fillStyle = '#6b6577';
990:       ctx.fillRect(x - 19, y - 32, 38, 38);
991:       ctx.fillStyle = '#4b4658'; ctx.fillRect(x - 19, y - 32, 38, 6);
992:       ctx.strokeStyle = '#9b8fd0'; ctx.lineWidth = 1.4;
993:       ctx.strokeRect(x - 14, y - 26, 28, 26);
994:       ctx.beginPath(); ctx.arc(x, y - 13, 8, 0, 6.28); ctx.stroke();
995:     }
996:     ctx.restore();
997:   }
