999:   drawObject(ctx, o, abilities = []) {
1000:     const x = o.x * T, y = o.y * T;
1001:     switch (o.type) {
1002:       case 'npc': {
1003:         drawHumanoid(ctx, {
1004:           x, y: y + 8, time: this.time, facing: 'down', walk: 0,
1005:           appearance: resolveAppearance(o.appearance),
1006:           weapon: o.weaponKind ? { kind: o.weaponKind } : null,
1007:           shield: o.weaponKind === 'spear',
1008:           cape: o.id === 'elara' || o.id === 'roderic',
1009:           aura: o.id === 'elara' ? 'rgba(166,139,255,.22)' : null,
1010:         });
1011:         break;
1012:       }
1013:       case 'chest': {
1014:         const open = o.opened;
1015:         ctx.save();
1016:         if (!open) {
1017:           ctx.globalCompositeOperation = 'lighter';
1018:           const g = ctx.createRadialGradient(x, y - 10, 2, x, y - 10, 34);
1019:           g.addColorStop(0, 'rgba(242,209,136,.25)'); g.addColorStop(1, 'transparent');
1020:           ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 10, 34, 0, 6.28); ctx.fill();
1021:           ctx.globalCompositeOperation = 'source-over';
1022:         }
1023:         ctx.fillStyle = open ? '#3d3227' : '#6b4a2c';
1024:         ctx.fillRect(x - 18, y - 24, 36, 24);
1025:         ctx.fillStyle = '#8d6438'; ctx.fillRect(x - 18, y - 24, 36, 5);
1026:         ctx.strokeStyle = '#d9b15f'; ctx.lineWidth = 2; ctx.strokeRect(x - 17, y - 23, 34, 22);
1027:         ctx.fillStyle = '#e8c979';
1028:         ctx.fillRect(x - 3, y - 18, 6, 8);
1029:         if (!open) {
1030:           ctx.fillStyle = '#7a532f'; ctx.beginPath(); ctx.ellipse(x, y - 24, 18, 7, 0, Math.PI, 0); ctx.fill();
1031:           ctx.strokeStyle = '#d9b15f'; ctx.stroke();
1032:         } else {
1033:           ctx.fillStyle = '#2a2118'; ctx.fillRect(x - 15, y - 23, 30, 6);
1034:         }
1035:         ctx.restore();
1036:         break;
1037:       }
1038:       case 'shrine': {
1039:         const pulse = .75 + Math.sin(this.time * 2) * .2;
1040:         ctx.save();
1041:         ctx.globalCompositeOperation = 'lighter';
1042:         const g = ctx.createRadialGradient(x, y - 34, 2, x, y - 34, 52);
1043:         g.addColorStop(0, `rgba(255,225,150,${.3 * pulse})`); g.addColorStop(1, 'transparent');
1044:         ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 34, 52, 0, 6.28); ctx.fill();
1045:         ctx.globalCompositeOperation = 'source-over';
1046:         ctx.fillStyle = '#6b6a7c'; ctx.beginPath(); ctx.ellipse(x, y + 6, 20, 6, 0, 0, 6.28); ctx.fill();
1047:         ctx.fillStyle = '#4c4b5c'; ctx.fillRect(x - 6, y - 20, 12, 26);
1048:         ctx.fillStyle = '#ffe9a8';
1049:         ctx.beginPath(); ctx.moveTo(x, y - 50); ctx.lineTo(x + 8, y - 34); ctx.lineTo(x, y - 18); ctx.lineTo(x - 8, y - 34); ctx.closePath(); ctx.fill();
1050:         ctx.strokeStyle = 'rgba(255,240,190,.6)'; ctx.lineWidth = 1.2;
1051:         ctx.beginPath(); ctx.ellipse(x, y - 34, 18 + Math.sin(this.time * 2) * 3, 6, .2, 0, 6.28); ctx.stroke();
1052:         ctx.restore();
1053:         break;
1054:       }
1055:       case 'sign': {
1056:         ctx.fillStyle = '#5b3e27'; ctx.fillRect(x - 3, y - 18, 6, 26);
1057:         ctx.fillStyle = '#8a6238'; ctx.fillRect(x - 16, y - 34, 32, 18);
1058:         ctx.strokeStyle = '#d2ac68'; ctx.lineWidth = 1; ctx.strokeRect(x - 15, y - 33, 30, 16);
1059:         ctx.fillStyle = 'rgba(255,240,200,.4)';
1060:         ctx.fillRect(x - 11, y - 29, 22, 1.5); ctx.fillRect(x - 11, y - 25, 16, 1.5);
1061:         break;
1062:       }
1063:       case 'gate': {
1064:         ctx.save();
1065:         ctx.fillStyle = '#4a4658';
1066:         ctx.fillRect(x - 24, y - 46, 8, 54); ctx.fillRect(x + 16, y - 46, 8, 54);
1067:         ctx.fillStyle = '#6b667c';
1068:         ctx.fillRect(x - 26, y - 50, 12, 8); ctx.fillRect(x + 14, y - 50, 12, 8);
1069:         if (!o.open) {
1070:           ctx.strokeStyle = '#a68bff'; ctx.globalAlpha = .8;
1071:           for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(x - 14 + i * 9, y - 44); ctx.lineTo(x - 14 + i * 9, y + 4); ctx.stroke(); }
1072:           ctx.globalAlpha = .25; ctx.fillStyle = '#a68bff'; ctx.fillRect(x - 16, y - 44, 32, 48);
