1088:         ctx.strokeStyle = 'rgba(255,240,190,.7)'; ctx.lineWidth = 1.2;
1089:         ctx.beginPath(); ctx.ellipse(x, y - 28 + bob, 17, 5, .3, 0, 6.28); ctx.stroke();
1090:         ctx.restore();
1091:         break;
1092:       }
1093:       case 'rune': {
1094:         const active = o.active || false;
1095:         const color = active ? '#ffd27a' : '#8f86b8';
1096:         ctx.save();
1097:         if (active) {
1098:           ctx.globalCompositeOperation = 'lighter';
1099:           const g = ctx.createRadialGradient(x, y - 4, 2, x, y - 4, 42);
1100:           g.addColorStop(0, 'rgba(255,215,120,.35)'); g.addColorStop(1, 'transparent');
1101:           ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 4, 42, 0, 6.28); ctx.fill();
1102:         }
1103:         ctx.strokeStyle = color; ctx.lineWidth = 2;
1104:         ctx.beginPath(); ctx.ellipse(x, y + 4, 20, 7, 0, 0, 6.28); ctx.stroke();
1105:         ctx.beginPath(); ctx.arc(x, y - 6, 10, 0, 6.28); ctx.stroke();
1106:         ctx.beginPath(); ctx.moveTo(x, y - 22); ctx.lineTo(x, y - 40); ctx.stroke();
1107:         ctx.fillStyle = color;
1108:         ctx.beginPath(); ctx.moveTo(x, y - 50); ctx.lineTo(x + 7, y - 40); ctx.lineTo(x, y - 30); ctx.lineTo(x - 7, y - 40); ctx.closePath(); ctx.fill();
1109:         ctx.restore();
1110:         break;
1111:       }
1112:       case 'runeDisplay': {
1113:         const active = o.active;
1114:         const color = active ? o.color : '#555a70';
1115:         ctx.save();
1116:         if (active) {
1117:           ctx.globalCompositeOperation = 'lighter';
1118:           const g = ctx.createRadialGradient(x, y - 20, 2, x, y - 20, 40);
1119:           g.addColorStop(0, hexA(o.color, .35)); g.addColorStop(1, 'transparent');
1120:           ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y - 20, 40, 0, 6.28); ctx.fill();
1121:         }
1122:         ctx.strokeStyle = color; ctx.lineWidth = 2;
1123:         ctx.beginPath(); ctx.ellipse(x, y + 4, 18, 6, 0, 0, 6.28); ctx.stroke();
1124:         ctx.fillStyle = color;
1125:         ctx.beginPath(); ctx.moveTo(x, y - 38); ctx.lineTo(x + 8, y - 20); ctx.lineTo(x, y - 4); ctx.lineTo(x - 8, y - 20); ctx.closePath(); ctx.fill();
1126:         ctx.restore();
1127:         break;
1128:       }
1129:       case 'altar': {
1130:         const pulse = .8 + Math.sin(this.time * 2.4) * .15;
1131:         ctx.save();
1132:         ctx.globalCompositeOperation = 'lighter';
