+    }
+  }
+
+  setQuestStage(id, stage, progress = 0) {
+    const q = this.state.quests[id];
+    if (!q) return;
+    q.stage = stage;
+    q.progress = progress;
+    q.status = 'active';
+  }
+
+  addQuestProgress(id, n = 1) {
