+  }
+
+  /* ---------------------------------------------------------------------- */
+  /* Interaction                                                            */
+  /* ---------------------------------------------------------------------- */
+  findCapturableWild() {
+    if (!this.player) return null;
+    let best = null, bestD = 92;
+    for (const w of this.wilds) {
+      if (!w.alive) continue;
+      if (w.hp / w.maxHp > .4) continue;
+      const d = Math.hypot(w.x - this.player.x, w.y - this.player.y);
