+
+  /* ---------------------------------------------------------------------- */
+  /* Shops                                                                  */
+  /* ---------------------------------------------------------------------- */
+  buyItem(id) {
+    const def = ITEMS[id];
+    if (!def) return;
+    const price = def.value || 0;
