+  }
+
+  /* ---------------------------------------------------------------------- */
+  /* Inventory, equipment & skills                                          */
+  /* ---------------------------------------------------------------------- */
+  useItem(id) {
+    const def = ITEMS[id];
+    if (!def || def.type !== 'consumable') return;
+    if (!(this.state.inventory[id] > 0)) { this.toast('No tienes ese objeto', 'bad'); return; }
+    const eff = def.effect || {};
